(window.GIM_TS=window.GIM_TS||{})["Yevamot.0"]={"from":0,"a":[["מצות התורה ליבם את אשת האח שמת ללא ילדים, או לפטור אותה על ידי חליצה, אמורה רק כאשר האלמנה מותרת להינשא ליבם (האח החי). אולם אם האלמנה אסורה על היבם משום שהיא קרובה לו קירבת משפחה, ואם ישא אותה יתחייב משום גילוי עריות — במקרה זה לא חלה על האשה מצות ייבום כלל, והיא פטורה לא רק מן הייבום אלא גם מן החליצה. ולמדו חכמים, שלא זו בלבד שאשה זו פטורה מן הייבום, אלא גם צרתה פטורה. שאם היתה לאח המת אשה אחרת שניה (\"צרה\"), שאיננה קרובה של האח החי, כיון שאחת הנשים אסורה עליו משום ערוה — גם השניה, צרתה, פטורה מן החליצה ומן הייבום. ולא עוד אלא אם אותה צרה התייבמה לאח אחר של המת (שלגביו איננה אסורה משום ערוה), אם גם אח זה ימות בלא ילדים, ותחול שוב על האח הראשון חובת הייבום, לא זו בלבד שזו שהיא צרת ערוה פטורה מן הייבום והחליצה, אלא גם צרת הצרה פטורה. כלומר, שגם אשה אחרת של האח השני נפטרת ממצות ייבום משום שהיא צרתה של הצרה הראשונה. והוא הדין גם אם נמשך הדבר, שאותה צרה נתייבמה לאח אחר שלא היתה אסורה עליו, שכלל הוא: כל אשה שנפטרה מן היבם משום צרת ערוה נעשית לגביו כמו ערוה עצמה, ופטורה מן החליצה ומן הייבום. והמשנה מפרטת את המקרים השונים: \u0003חמש עשרה נשים\u0004 הן קרובות משפחה שיש בהן משום ערוה, והן \u0003פוטרות צרותיהן וצרות צרותיהן מן החליצה ומן היבום עד סוף העולם,\u0004 וכן הן פוטרות גם צרות־של־צרות־של־צרות, וכך הלאה.","\u0003ואלו הן:\u0004 אם היתה אשת המת \u0003בתו\u0004 של האח החי, שהאח שמת נשא את בתו, וכשמת בלא בנים נמצא שעל הבת חלה (\"נופלת לפניו\") חובת ייבום, \u0003ו\u0004כן אם היתה אשת האח שמת \u0003בת בתו\u0004 של המייבם, \u0003ו\u0004כן אם היתה \u0003בת בנו,\u0004 וכן אם היתה אשת המת \u0003בת אשתו\u0004 של היבם, או היתה","\u0003בת בנה\u0004 של אשתו, או \u0003בת בתה\u0004 של אשתו, או שאשת האח שמת היתה \u0003חמותו\u0004 של היבם, או \u0003אם חמותו,\u0004 או \u0003אם חמיו,\u0004 או שאשת המת היתה","\u0003אחותו\u0004 של האח החי \u0003מאמו\u0004 (ולא היתה אחות האח המת, שלא היו הם אחים אלא מאב), או שהיתה \u0003אחות אמו\u0004 של האח החי, או שהיתה \u0003אחות אשתו,\u0004 או שהיתה \u0003אשת אחיו מאמו,\u0004 ולאחר שאותו אח מאם מת או גירש את אשתו נשא אותה אחיו של זה מאביו, ואותה אשה איננה קרובתו, ומת אח זה ונפלה האשה לייבום לפני האח החי (אחר שהיתה בעבר אשת אחיו מאמו),"],["\u0003ו\u0004כן \u0003אשת אחיו שלא היה בעולמו,\u0004 כלומר, אשתו של אח שמת לפני שהאח הזה נולד. וכפי שנלמד להלן לא חלה במקרה זה על האח הזה חובת ייבום, ולא עוד אלא שבגלל שאין כאן לגביו מצות ייבום אשת אח זה נשארת היא באיסורה עליו באיסור ערוה כאשת אח שלא הותרה. \u0003ו\u0004כן אם הדיתה אשת האח המת קודם נישואיה לאחיו \u0003כלתו,\u0004 ומת בנו ונשאה אחיו, ואחר כך מת אח זה. \u0003הרי\u0004 חמש עשרה נשים \u0003אלו פוטרות צרותיהן, וצרות צרותיהן מן החליצה ומן הייבום עד סוף העולם.\u0004","\u0003וכולן,\u0004 כל אותן הנשים שמנינו, האסורות משום ערוה, הדברים שנאמרו ביחס אליהן אמורים רק כאשר אותן קרובות (\"עריות\") היו נשואות לאח שמת עד מותו. אבל, \u0003אם מתו\u0004 עוד בחיי הבעל (האח שמת), \u0003או מיאנו\u0004 בבעליהן כשהיו קטנות, שתיקנו חכמים שילדה קטנה שמת אביה רשאים אימה ואחיה להשיא אותה, אבל נישואין אלה אינם נישואין גמורים, ותיקנו שילדה זו יכולה למאן, שאם אמרה בעודה קטנה שאיננה רוצה בנישואין הרי היא עוקרת בכך לחלוטין את הנישואין הללו,","\u0003או נתגרשו\u0004 הקרובות מן הבעל (האח שמת), \u0003או שנמצאו אילונית\u0004 (אשה פגומה מבחינה מינית, עד כדי כך שאינה נחשבת כאשה גמורה) ונישואין לאשה כזו נחשבים כנישואי טעות ובטלים מיסודם — הרי במקרים אלה \u0003צרותיהן מותרות,\u0004 לפי שפטור זה של צרת ערוה כוחו יפה לגבי היבם רק כאשר היתה הערוה עצמה אשת אחיו בשעת מותו, כאשר חלה עליה מצות ייבום.","ומעירה המשנה לגבי לשונו של כלל זה, שאיננה מדוייקת לחלוטין, לפי ש\u0003אי\u0004 (אין) \u0003אתה יכול לומר בחמותו ובאם חמותו ובאם חמיו שנמצאו אילונית\u0004 שהרי אילונית אינה יולדת ולכן אינה יכולה להיות חמות. וכן אינה מדוייקת בהן הלשון \u0003או שמיאנו\u0004 כיון שהממאנת היא רק ילדה קטנה, שאינה מסוגלת ללדת.","ומעתה מבארת המשנה \u0003כיצד פוטרות צרותיהן: היתה בתו\u0004 למשל, \u0003או אחת מכל העריות האלו, נשואות לאחיו, ולו\u0004 (לאח) \u0003אשה אחרת, ומת\u0004 האח, \u0003כשם שבתו פטורה — כך צרתה פטורה. הלכה צרת בתו ונשאת לאחיו השני,\u0004 שהרי היא מותרת לו, לפי שאינה בגדר ערוה לו, \u0003ולו אשה אחרת, ומת\u0004 גם הוא בלי בנים, ונפלה אשה זו לפני היבם הראשון, אבי הבת, \u0003כשם שצרת בתו פטורה — כך צרת צרתה\u0004 (האשה האחרת) \u0003פטורה.\u0004","\u0003אפילו הן מאה\u0004 אחים, וחזר הדבר כך, שאם לאשה שנפטרה מייבום משום שהיא צרת ערוה או צרת צרה, יש צרה נוספת, הרי אף צרה זו פטורה ופוטרת מייבום.","\u0003כיצד\u0004 היה המקרה ש\u0003אם מתו צרותיהן מותרות:\u0004 כגון ש\u0003היתה בתו, או אחת מכל העריות האלו, נשואות לאחיו, ולו\u0004 (לאח) \u0003אשה אחרת\u0004 שאינה ערוה לו, אם \u0003מתה בתו או נתגרשה, ואחר כך מת אחיו — צרתה מותרת. ו\u0004עוד כלל אמרו:","\u0003כל\u0004 אחת מן העריות הללו שהיתה קטנה \u0003היכולה למאן\u0004 אף על פי ש\u0003לא מיאנה — צרתה חולצת ולא מתייבמת.\u0004 איננה מתייבמת — משום שהיא צרת ערוה, אבל איננה פטורה לגמרי מן הייבום וצריכה חליצה, משום שהנישואין של אותה ערוה לא היו נישואין גמורים, ולכן אין האשה האחרת נחשבת מדין תורה כצרת ערוה.","תחילה שואלים על סדר הדברים במשנה: \u0003מכדי כולהו\u0004 \u0005[הרי כולם],\u0006 כל העריות הללו הפטורות ופוטרות, \u0003מ\u0004דין \u0003אחות אשה ילפינן\u0004 \u0005[אנו לומדים]\u0006 כפי שיבואר להלן, שעיקר הלימוד לפטור את הקרובות מן הייבום הוא מן הדין האמור באחות אשתו, ואם כן \u0003ליתני\u0004 \u0005[שישנה]\u0006 \u0003אחות אשה ברישא\u0004 \u0005[בתחילה],\u0006 ואחר כך ישנה את כל המקרים האחרים הבאים ונלמדים ממנה!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 כי ה\u0003תנא חומרי־חומרי\u0004 \u0005[\u0006את הדברים \u0005החמורים־חמורים]\u0006 \u0003נקט\u0004 תחילה, שסידר אותם לפי חומרת האיסורים, \u0003ו\u0004שיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר\u0004 שמיתת בית דין ב\u0003שריפה חמורה\u0004 יותר מאשר סקילה. ולכן, בתו ובת בתו ובת בנו וכו' שהן עריות שהחוטא בהן נענש בשריפה — הקדימן התנא, ואחר כך סידר את אלה שעונשן חמור פחות —","אולם גם כך אין הסדר ברור; כי \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003ליתני\u0004 \u0005[שישנה]\u0006 דין \u0003חמותו ברישא\u0004 \u0005[בתחילה],\u0006 ש\u0003עיקר\u0004 דין \u0003שריפה\u0004 הלא \u0003בחמותו כתיבא\u0004 \u0005[נאמר],\u0006 ככתוב: \"ואיש אשר יקח את אשה ואת אמה זמה היא באש ישרפו אותו ואתהן\" (ויקרא כ, יד)! \u0003ועוד:\u0004 לפי סדר זה \u0003בתר\u0004 \u0005[אחר]\u0006 דין \u0003חמותו ליתני\u0004 \u0005[שישנה]\u0006 דין \u0003כלתו, דבתר\u0004 \u0005[ש\u0006הלא \u0005אחר]\u0006 מיתת \u0003שריפה סקילה חמורה\u0004 משאר עונשי מיתות בית דין!","\u0003אלא\u0004 יש לחזור מן ההסבר הקודם, ולומר אחרת: \u0003בתו, כיון דאתיא מדרשא\u0004 \u0005[ש\u0006עצם איסורה \u0005בא,\u0006 נלמד, \u0005מדרשה]\u0006 ולא נכתב במפורש בתורה, על כן היא \u0003חביבא ליה\u0004 \u0005[חביבה עליו,\u0006 על התנא\u0005],\u0006 שכיון שיש בכך חידוש הקדים אותה לפני כל המקרים האחרים."],["\u0003כולהו נמי מדרשא אתו\u0004 \u0005[\u0006כל העריות \u0005כולן\u0006 שבמשנה \u0005גם כן מדרשה באו,\u0006 נלמדו\u0005]\u0006 שפטורות מן הייבום! ומשיבים: \u0003נהי\u0004 \u0005[אמנם כן]\u0006 ש\u0003לענין ייבום אתיין מדרשא\u0004 \u0005[\u0006הן \u0005באות,\u0006 נלמדות, \u0005מדרשה]\u0006 אבל \u0003עיקר איסורייהו\u0004 \u0005[איסורן]\u0006 \u0003בהדיא כתיב בהו\u0004 \u0005[במפורש כתוב בהן],\u0006 ואילו איסור \u0003בתו\u0004 שאיננה בת אשתו אלא בת אנוסתו, \u0003עיקר איסורא\u0004 \u0005[האיסור]\u0006 שבה נלמד \u0003מדרשא\u0004 \u0005[מדרשה]\u0006 ואינו מפורש בכתוב.","ש\u0003אמר רבא: אמר לי רב יצחק בר אבדימי: אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה של המילים \u0003\"הנה\" \"הנה\"\u0004 (ויקרא יח, י, ושם יז), ללמד, שבתו מכל מקום, אפילו בת אנוסתו, אסורה כבתו מאשתו,","\u0003אתיא\u0004 \u0005[באה]\u0006 גזירה שווה של המילים \u0003\"זמה\" \"זמה\"\u0004 (שם יח, יז, ושם כ, יד), ללמד שהאב הבא על בתו מאנוסתו נידון בשריפה כדין אב הבא על בתו מאשתו.","ושואלים: \u0003השתא דאמרת כל מלתא דאתיא מדרשא חביבא ליה\u0004 \u0005[עכשיו שאתה אומר\u0006 ש\u0005כל דבר שבא מן הדרשה חביב לו]\u0006 והתנא מקדים אותו, \u0003ליתני\u0004 \u0005[שישנה]\u0006 את דין \u0003אחות אשה לבסוף\u0004 שהרי לפי כלל זה דין אחות אשה הוא הפשוט שבהם, שכן שם מקור ההלכה! ומשיבים: \u0003איידי דאיירי\u0004 \u0005[מתוך שעסק]\u0006 \u0003באיסור אחוותא\u0004 \u0005[אחיות]\u0006 שונות, \u0003תנא\u0004 \u0005[שנה]\u0006 איתן גם את איסור \u0003אחות אשתו.\u0004","ושואלים: אם כן, \u0003וליתנייא להאי בבא\u0004 \u0005[ושישנה\u0006 את כל הקטע \u0005הזה]\u0006 הנוגע לאחיות \u0003לבסוף\u0004 אגב הזכרת אחות אשתו! \u0003אלא,\u0004 יש לדחות את מה שאמרנו ולתת הסבר אחר: ה\u0003תנא קורבי־קורבי\u0004 \u0005[קירבות־קירבות]\u0006 \u0003נקט,\u0004 ולפי יחסי הקירבה של העריות השונות סידר את המשנה. כיצד: \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003בתו ובת בתו ובת בנו\u0004 שהן \u0003קרובי עצמו,\u0004","\u0003ואיידי דתנא\u0004 \u0005[ומתוך ששנה]\u0006 \u0003שלשה דורות למטה דידיה\u0004 \u0005[שלו],\u0006 כלומר, שלושה דורות של צאצאיו: בתו ובת בתו ובת בנו שלו, \u0003תנא נמי\u0004 \u0005[שנה גם כן]\u0006 \u0003שלשה דורות למטה דידה\u0004 \u0005[שלה]\u0006 של אשתו: היא, בתה ובת בתה. \u0003ואיידי דתנא\u0004 \u0005[ומתוך ששנה]\u0006 \u0003שלשה דורות למטה דידה\u0004 \u0005[שלה]\u0006 \u0003תנא\u0004 \u0005[שנה]\u0006 גם כן \u0003שלשה דורות למעלה\u0004 (של ההורים) \u0003דידה\u0004 \u0005[שלה],\u0006 שהן חמותו ואם חמותו.","\u0003ו\u0004אחר כך \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003אחותו ואחות אמו\u0004 שהן \u0003קרובי עצמו\u0004 בקירבה פחות הדוקה מהקירבה לבתו. \u0003ואיידי דאיירי\u0004 \u0005[ומתוך שעסק]\u0006 \u0003באיסור אחוה\u0004 \u0005[אחיות],\u0006 \u0003תנא\u0004 \u0005[שנה]\u0006 גם כן \u0003אחות אשתו. ובדין הוא דליקדמה\u0004 \u0005[שיקדים]\u0006 את ההלכה ב\u0003כלתו מקמי\u0004 \u0005[לפני]\u0006 \u0003אשת אחיו שלא היה בעולמו,\u0004 שכן \u0003לא משום קורבא\u0004 \u0005[קירבה]\u0006 \u0003הוא דאסירא\u0004 \u0005[שאסורה]\u0006 אלא מפני טעם אחר, לפי שאינה בכלל מצות הייבום, \u0003אלא איידי דאיירי\u0004 \u0005[מתוך שעסק]\u0006 \u0003באיסור אחוה\u0004 \u0005[אחיות]\u0006 \u0003תנא\u0004 \u0005[שנה]\u0006 גם \u0003אשת אחיו שלא היה בעולמו\u0004 שגם היא בגדר איסור אחוה, \u0003והדר תנא\u0004 \u0005[וחזר ושנה]\u0006 דין \u0003כלתו.\u0004","ועוד בירור בלשונה של המשנה: \u0003ומאי איריא\u0004 \u0005[ומה שייך,\u0006 מדוע דווקא\u0005]\u0006 \u0003דתנא\u0004 \u0005[ש\u0006הוא \u0005שונה]\u0006 \u0003\"פוטרות\u0004 צרותיהן \u0003\", ליתני\u0004 \u0005[שישנה]\u0006 \u0003\"אוסרות\u0004 צרותיהן \u0003\",\u0004 שהרי הצרות לא רק נפטרו מחובת הייבום אלא אף אסורות על היבם! ומסבירים: \u0003אי תנא\u0004 \u0005[אם\u0006 היה \u0005שונה]\u0006 \u0003\"אוסרות\u0004 צרותיהן \u0003\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 הכוונה היא ש\u0003אסור לייבם, אבל מיחלץ\u0004 \u0005[לחלוץ]\u0006 — \u0003חלצה\u0004 \u0005[חולצת],\u0006 לכן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 בלשון זו, לומר שהיא פטורה לגמרי.","ומקשים: אם כן \u0003וליתני\u0004 \u0005[ושישנה]\u0006 \u0003\"אסורה לחלוץ\"!\u0004 את ההצעה הזו דוחים: אי אפשר לכתוב בלשון זו, שכן אף אם חולץ לה \u0003מאי קעביד\u0004 \u0005[מה הוא עושה]?\u0006 שאם אדם מניח לאשה לחלוץ את נעלו מה איסור יש בכך? ולכן אי אפשר לומר \"אסורה לחלוץ\". ושואלים: \u0003אלמה\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 הרי בכל זאת יש בכך צד איסור, שכן \u0003אם אתה אומר \"חולצת\"\u0004 יבואו לומר שבקירבה כגון זו היא גם \u0003מתייבמת,\u0004 אלא שבמקרה זה חלץ לה מפני שלא רצה בה, אבל אחר הרוצה בצרת יבמתו רשאי ליבמה!","אלא יש לומר טעם אחר שבגללו לא שנה \"אוסרות\", והוא: \u0003כיון\u0004 שרק \u0003במקום מצוה הוא דאסירה\u0004 \u0005[שאסורה]\u0006 \u0003צרה,\u0004 שרק כאשר חלה עליה מצות ייבום, רק אז אסורה עליו הצרה, \u0003ושלא במקום מצוה שריא\u0004 \u0005[מותרת],\u0006 שמותר לאיש לשאת אשה שהיתה צרת אחת מקרובותיו ונתאלמנה, וכגון שנשא חתנו פרט לבתו גם אשה אחרת ומת, שאותה אשה שהיא זרה לו מותרת לו, שלא נאסרה צרה אלא במקום שיש צד ייבום לגבי צרתה (שהיא קרובתו), \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003תני\u0004 \u0005[שנה]\u0006 \u0003\"פוטרות\",\u0004 ולא \"אסורות\", להשמיע לנו שהן כשלעצמן אינן אסורות עליו.","ועוד הסבר בלשון המשנה: \u0003ומאי איריא\u0004 \u0005[ומה שייך,\u0006 מדוע דווקא\u0005]\u0006 \u0003דתני\u0004 \u0005[ש\u0006הוא \u0005שונה]\u0006 \u0003\"מן החליצה ומן הייבום\"? ליתני\u0004 \u0005[שישנה]\u0006 \u0003\"מן הייבום\" לחודיה\u0004 \u0005[לבדו]!\u0006 ומשיבים: \u0003אי תנא\u0004 \u0005[אילו\u0006 היה \u0005שונה]\u0006 \u0003\"מן הייבום\" הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003מיחלץ\u0004 \u0005[לחלוץ]\u0006 — \u0003חלצה\u0004 \u0005[חולצת],\u0006 אבל \u0003יבומי\u0004 \u0005[לייבם]\u0006 — \u0003לא מייבמה\u0004 \u0005[אינה מתייבמת],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 התנא בלשון זו ש\u0003כל\u0004 אשה \u0003העולה לייבום\u0004, כלומר, כל אשה הראויה ליבום — \u0003עולה לחליצה, וכל שאינו עולה לייבום\u0004 — \u0003אינו עולה לחליצה,\u0004 שאין חובת חליצה אלא כשיש חובת ייבום.","ומבררים עוד: ושיקדים במשנה את הייבום לחליצה, \u0003וליתני\u0004 \u0005[ושישנה]\u0006 \u0003\"מן הייבום ומן החליצה\",\u0004 שהרי התורה מקדימה את אפשרות הייבום, \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 שישנה \u0003\"מן החליצה\" לחודה\u0004 \u0005[לבדה]\u0006 ונבין מכאן גם למצות הייבום? ומשיבים: משנה זו כשיטת \u0003אבא שאול היא,\u0004 ש\u0003אמר\u0004 ש\u0003מצות חליצה קודמת למצות ייבום,\u0004 שלדעתו, כל שאינו מייבם לשם שמים הריהו עובר באיסור אשת אח, ועדיף בכל מקרה שיחלוץ, ולכן הקדים חליצה לייבום.","ומוסיפים לשאול בלשון המשנה: \u0003מנינא דרישא\u0004 \u0005[המנין שבראש\u0006 המשנה\u0005]\u0006 המתחילה \"חמש עשרה נשים\", שיש לדייק ממנו כי דווקא אלה ולא יותר, \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 מן הדברים שהיינו יכולים להוסיף? \u0003ו\u0004כן \u0003מנינא דסיפא\u0004 \u0005[המנין שבסוף]\u0006 המשנה, שנאמר: \"הרי אלו פוטרות\", שמשמע אלו ולא אחרות, \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה\u0006 בא\u0005]?\u0006 שהרי נראה שהמשנה מדייקת שרק נשים אלה ולא אחרות, ומה הן אותן אחרות שאפשר היה לחשוב שהם נכללות בכלל אלה, ונתמעטו?"],["\u0003למעוטי\u0004 \u0005[למעט]\u0006 את זו שהוסיף \u0003רב ו\u0004זו שהוסיף \u0003רב אסי,\u0004 שרב הוסיף לרשימה זו צרת סוטה, ורב אסי הוסיף צרת אילונית. ושואלים: ו\u0003ל\u0004שיטת \u0003רב ולרב אסי — למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 בא המנין והדיוק שבמשנה?","ומשיבים: \u0003אי סבירא להו דהדדי\u0004 \u0005[אם סבורים הם זה כ\u0006שיטת \u0005זה],\u0006 הרי לשון מיעוט \u0003חדא\u0004 \u0005[אחת]\u0006 היא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003צרת ממאנת,\u0004 שאם היו לאח המת שתי נשים, ואחת מהן היתה קטנה, ומיאנה ביבם, אף צרתה אינה מתייבמת, ובאה המשנה לחדש שאינה נפטרת לגמרי וחייבת בחליצה. \u0003וחדא\u0004 \u0005[ואחת]\u0006 באה \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003צרת מחזיר גרושתו\u0004 שהחזירה אחיו באיסור אחרי שנישאה לאחר ומת, שאף צרתה נפטרת מן הייבום, ומחדשת המשנה שאינה פטורה לגמרי ועדיין חייבת בחליצה.","\u0003ואי לא סבירא להו דהדדי\u0004 \u0005[אם אינם סבורים זה כ\u0006שיטת \u0005זה]\u0006 אם כן \u0003חדא למעוטי דחבריה\u0004 \u0005[אחת למעט\u0006 מה \u0005ש\u0006אמר \u0005חבירו],\u0006 שהרי הוא איננו סבור כמותו בנושא זה, \u0003וחדא למעוטי\u0004 \u0005[ו\u0006לשון מיעוט \u0005אחת למעט]\u0006 \u0003או צרת ממאנת, או צרת מחזיר גרושתו.\u0004","ושואלים: \u0003לרב ולרב אסי, ליתנינהו\u0004 \u0005[שישנה אותן]\u0006 את צרת הסוטה ואת צרת האילונית! שהרי לדעתם יש יותר מחמש עשרה נשים שנמנו, ומדוע לא שנה אותן התנא במשנתנו?","ומשיבים: לא נשנו אלה משום שאינן נכנסות בכלל הלכות אלה בשלמותן, \u0003לפי שאינה בצרת צרה.\u0004 שהרי בחמש עשרה הנשים שמנינו יש מקום לדון גם בצרותיהן וגם בצרות צרותיהן, אבל בשתי אלו של רב ורב אסי אין הדבר אפשרי, שכן הסוטה או האילונית פטורות ואסורות לכל האחים בשווה, לפי שהאיסור איננו בגלל קירבה לאחד האחים החיים אלא בגלל סיבה אישית שבהן כשלעצמן, ולכן אי אפשר לכלול אותן בתוך חמש עשרה הנשים שנמנו במשנה.","לאחר שעסקנו בבירור ענייני סדר ולשון במשנה, באים עכשיו לדון בגופן של ההלכות הכתובות בה. \u0003מנא הני מילי\u0004 \u0005[מניין הדברים הללו]\u0006 שאם נפלה לייבום אשה האסורה איסור ערוה ליבם — אסור לייבמה, וכן אסור לייבם את צרתה וצרת צרתה? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים],\u0006 נאמר: \u0003\"\u0004ו\u0003אשה אל אחותה לא תקח לצרר לגלות ערותה עליה בחייה\"\u0004 (ויקרא יח, יח), ויש להבין: המלה \u0003\"עליה\", מה תלמוד לומר?\u0004 שהרי מלה זו נראית לכאורה כמיותרת!","ומסבירים: \u0003לפי שנאמר\u0004 באשת האח שמת: \u0003\"יבמה יבא עליה\"\u0004 (דברים כה, ה), ומלשון הפסוק \u0003שומע\u0004 (למד) \u0003אני\u0004 שמצוה זו של ייבום היא כללית, ו\u0003אפילו באחת מכל עריות האמורות בתורה הכתוב מדבר,\u0004 ועל כן למדים בגזירה שווה: \u0003נאמר כאן\u0004 באחות אשתו \u0003\"עליה\" ונאמר להלן\u0004 ביבמה \u0003\"עליה\",\u0004","\u0003מה להלן\u0004 ביבמה, שנאמר בה \"יבמה יבוא עליה\" הוא \u0003במקום מצוה, אף כאן\u0004 שנאמר \"לגלות ערותה עליה\" הוא \u0003במקום מצוה, ואמר רחמנא\u0004 \u0005[ואמרה התורה]\u0006 \u0003\"לא תקח\",\u0004 שהמלה \"עליה\" באה ללמדנו, שגם במקרה שיש חיוב של \"יבמה יבוא עליה\" — מכל מקום אסרה התורה \"לגלות ערוותה עליה\".","וממשיכים: \u0003ואין לי אלא היא,\u0004 אחות אשתו, שפטורה מן הייבום, \u0003צרתה מנין? תלמוד לומר,\u0004 מן המלה \u0003\"לצרר\",\u0004 לומר שלא רק היא אסורה אלא גם צרתה. \u0003ואין לי אלא צרתה\u0004 בלבד, \u0003צרת צרתה מניין\u0004 שאף היא פטורה? \u0003תלמוד לומר,\u0004 לשון \u0003\"לצרר\"\u0004 שאמר הכתוב \u0003ולא \"לצור\",\u0004 שהמלה \"לצרור\" משמעה צרה אחר צרה.","\u0003ואין לי אלא אחות אשה,\u0004 שלמדנו מגזירה שווה זו שאין מצוות ייבום חלה עליה, \u0003שאר עריות מניין? אמרת\u0004 שאפשר לומר זאת באופן הבא: \u0003מה אחות אשה מיוחדת\u0004 — \u0003שהיא ערוה\u0004 עליו, וחומרת איסורה היא בזה ש\u0003חייבין על זדונה\u0004 (אם בא עליה בזדון) \u0003כרת, ועל שגגתה\u0004 (אם בא עליה בשוגג) קרבן \u0003חטאת, ו\u0004היא \u0003אסורה ליבם,\u0004 הרי מעתה אפשר ללמוד במידת ההלכה של בנין אב, מן הפרט אל הכלל: \u0003אף כל שהיא ערוה וחייבין על זדונה כרת ועל שגגתה חטאת — אסורה ליבם.\u0004","\u0003ואין לי אלא הן\u0004 אותן העריות עצמן, \u0003צרותיהן מניין\u0004 שאף הן פטורות מייבום? \u0003אמרת\u0004 שאפשר ללמוד זאת בבנין אב: \u0003מה אחות אשה מיוחדת\u0004 — \u0003שהיא ערוה\u0004 עליו ו\u0003חייבים על זדונה כרת ועל שגגתה חטאת ואסורה ליבם, ו\u0004הדין ש\u0003צרתה אסורה, אף כל שהיא ערוה\u0004 כעין זה, \u0003וחייבין על זדונה כרת ועל שגגתה חטאת ואסורה ליבם — צרתה אסורה. מכאן אמרו חכמים: חמש עשרה נשים פוטרות צרותיהן וצרות צרותיהן מן החליצה ומן הייבום עד סוף העולם.\u0004","\u0003יכול שאני מרבה\u0004 בכלל זה \u0003אף שש עריות חמורות מאלו,\u0004 שגם בהן יש איסור כרת, כגון אמו ואשת אביו ועוד (המנויות במשנה להלן יבמות יג, ב) הנשואות לאחרים \u0003שיהו צרותיהם אסורות\u0004 להינשא לזה משום צרת ערוה?","\u0003אמרת: מה אחות אשתו מיוחדת — שהיא ערוה, וחייבין על זדונה כרת ועל שגגתה חטאת, ואפשר\u0004 לה \u0003לינשא ל\u0004אחד מן ה\u0003אחים, ו\u0004היא \u0003אסורה ליבם וצרתה אסורה, אף כל שהיא ערוה ו\u0004דינה ש\u0003חייבין על זדונה כרת ועל שגגתה חטאת, ואפשר לינשא לאחים, ואסורה ליבם — צרתה אסורה.\u0004","\u0003יצאו שש עריות חמורות מאלו, הואיל\u0004 ש\u0003אי אפשר\u0004 לה \u0003לינשא לאחים\u0004 כיון שהן אסורות על כל האחים שהרי אמו של זה אסורה להינשא גם לאחיו, בין כשהיא אמו של האח או רק אשת אביו, לכן \u0003צרותיהן מותרות. שאין צרה אלא מאח,\u0004 כלומר, איסור זה של צרת ערוה איננו בא לאסור על אדם לשאת צרת אשה שהיא ערוה לו אלא רק במקום שיש זיקת ייבום ביניהם, אבל כשאין זיקת ייבום — אין איסור בצרה.","ומוסיפים: שכל אשה שהיא לו ערוה שהיא בכלל \u0003אזהרה\u0004 (מצוות לא תעשה) עליו \u0003שמענו\u0004 (למדים אנו) אכן מן הכתוב הזה \"לא תקח לצרור\", אולם, \u0003עונש, מניין\u0004 שהוא חייב אם עבר וייבם אותה? — \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כי כל אשר יעשה מכל התועבת\u0004 האלה ונכרתו הנפשות העושות מקרב עמם\u0003\"\u0004 (ויקרא יח, כט). עד כאן לשונה של ברייתא זו, הדורשת את המקראות שהם הבסיס להלכה של משנתנו.","ומעתה באים לבאר את הענין לגופו ולשורשיו. ומעירים: \u0003טעמא דכתב רחמנא\u0004 \u0005[הטעם,\u0006 דווקא, \u0005שכתבה התורה]\u0006 \u0003\"עליה\", הא לאו הכי, הוה אמינא\u0004 \u0005[הרי\u0006 אם \u0005לא כן, הייתי אומר]\u0006 \u0003אחות אשה מייבמת\u0004 \u0005[מתייבמת],\u0006 \u0003מאי טעמא\u0004 \u0005[מה הטעם\u0006 בשיקול זה\u0005]?\u0006 \u0003דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 ונוהגים לפי הכלל: \u0003אתי\u0004 \u0005[באה]\u0006 מצות \u0003עשה\u0004 של ייבום \u0003ודחי\u0004 \u0005[ודוחה]\u0006 את מצות \u0003לא תעשה,\u0004 אולם, מדוע יחול כלל זה כאן?","\u0003אימר דאמרינן אתי\u0004 \u0005[אמור שאנו אומרים\u0006 כרגיל ש\u0005בא]\u0006 \u0003עשה ודחי\u0004 \u0005[ודוחה]\u0006 את \u0003לא תעשה\u0004 רק כשמדובר ב\u0003לא תעשה גרידא\u0004 \u0005[סתם]\u0006 שעונשו מלקות בלבד, אבל \u0003לא תעשה שיש בו\u0004 חיוב \u0003כרת — מי דחי\u0004 \u0005[האם\u0006 העשה \u0005דוחה\u0006 אותו\u0005]?\u0006 שהרי איסור כזה חמור ביותר, ושמא הוא אינו נדחה מפני מצות עשה! \u0003ותו\u0004 \u0005[ועוד]\u0006 אפשר לשאול: \u0003לא תעשה גרידא\u0004 \u0005[סתם]\u0006 \u0003מנלן דדחי\u0004 \u0005[מניין לנו שדוחה]\u0006 אותה מצות עשה —"],["\u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא תלבש שעטנז\u0004 צמר ופשתים יחדו. \u0003גדילים תעשה לך\u0004 על ארבע כנפות כסותך אשר תכסה בה\u0003\"\u0004 (דברים כב, יא-יב), ללמדנו: אף על פי שיש איסור בלבישת שעטנז, מכל מקום אפשר לעשות ציציות גם אם הן שעטנז (כגון פתיל תכלת של צמר על ציצית של פשתים), ומכאן שמצות עשה של ציצית דוחה את מצות לא תעשה של שעטנז.","\u0003ואמר ר' אלעזר: סמוכים מן התורה מנין,\u0004 כלומר, מניין שיש מקום ללמוד מסמיכות הדברים זה לזה, שמתוך שהדינים כתובים סמוך זה לזה משמע שהם למדים זה מזה, \u0003שנאמר: \"סמוכים לעד לעולם עשוים באמת וישר\"\u0004 (תהלים קיא, ח).","\u0003ו\u0004לימוד כיוצא בו \u0003אמר רב ששת אמר ר' אלעזר משום\u0004 (בשם) \u0003ר' אלעזר בן עזריה: מנין ליבמה שנפלה לפני מוכה שחין שאין חוסמין אותה,\u0004 כלומר, אין מכריחים אותה להתייבם לו, ואף כופים אותו לחלוץ — \u0003שנאמר: \"לא תחסם שור בדישו\"\u0004 (דברים כה, ד) \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 נאמר: \u0003\"כי ישבו אחים יחדו\"\u0004 (שם ה), והמשך הכתובים עניינם פרשת ייבום. וסמיכות זו באה ללמדנו, שכשם שחסים על השור שלא יצטער כשדש תבואה ואינו אוכל ממנה, כך חסים על היבמה שלא תצטער ביבם מוכה שחין.","\u0003ואמר רב יוסף: אפילו למאן דלא דריש\u0004 \u0005[אפילו ל\u0006דעת \u0005מי שאיננו דורש]\u0006 \u0003סמוכים בעלמא\u0004 \u0005[בכלל],\u0006 הרי \u0003ב\u0004ספר \u0003משנה תורה\u0004 (דברים) \u0003דריש\u0004 \u0005[דורש\u0006 הוא\u0005].\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003ר' יהודה בעלמא לא דריש\u0004 \u0005[בכלל איננו דורש\u0006 סמוכים\u0005]\u0006 \u0003ובמשנה תורה דריש\u0004 \u0005[דורש\u0006 הוא\u0005].\u0006","ומפרטים: \u0003ובעלמא מנלן דלא דריש\u0004 \u0005[ובכלל מניין לנו שאיננו דורש]?\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בן עזאי אומר, נאמר: \"מכשפה לא תחיה\"\u0004 (שמות כב, יז) אבל לא נאמר כיצד ממיתים אותה, \u0003ונאמר: \"כל שכב עם בהמה מות יומת\"\u0004 (שם, יח), \u0003סמכו ענין\u0004 מכשפה \u0003לו,\u0004 לומר: \u0003מה שוכב עם בהמה\u0004 דינו \u0003בסקילה\u0004 כפי שזה נלמד מהכתובים בספר ויקרא (כ, טז), \u0003אף מכשפה\u0004 דינה \u0003בסקילה.\u0004","\u0003אמר לו ר' יהודה: וכי מפני שסמכו ענין לו נוציא זה לסקילה?\u0004 וכי אפשר לסמוך על דרשה כזו הנובעת רק מסמיכות המקראות עד כדי הוצאת המכשפה למיתה חמורה?","\u0003אלא,\u0004 הלכה זו כך היא נלמדת: \u0003אוב וידעוני בכלל מכשפים היו, ולמה יצאו\u0004 מן הכלל ונתפרש דינם במיוחד? הרי זה כדי ללמוד במידה מקובלת של מדרש ההלכה \u0003להקיש להם\u0004 (להשוות אותם) \u0003ולומר לך: מה אוב וידעוני\u0004 דינם \u0003בסקילה,\u0004 כמפורש בהם: \"ואיש או אשה כי יהיה בהם אוב או ידעוני מות יומתו באבן ירגמו אותם דמיהם בם\" (ויקרא כ, כז) — \u0003אף מכשפה\u0004 שנאמר בה \"לא תחיה\" (שמות כב, יז) דינה \u0003בסקילה.\u0004 הרי שבדרך כלל אין ר' יהודה דורש סמוכים.","\u0003ובמשנה תורה מנלן דדריש\u0004 \u0005[מניין לנו ש\u0006הוא כן \u0005דורש]?\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003נושא אדם אנוסת אביו ומפותת אביו\u0004 למרות שאסור באשת אביו. וכן, נושא \u0003אנוסת בנו ומפותת בנו\u0004 אף על פי שאסור בכלתו. שכן האיסור חל על אלה רק אם נתקשרו ביחסי נישואין, ולא בשל יחסי אישות בלבד. \u0003ר' יהודה אוסר באנוסת אביו ומפותת אביו.\u0004","\u0003ואמר רב גידל אמר רב: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 \u0003דר' יהודה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא יקח איש את אשת אביו\u0004 של \u0003ולא יגלה כנף אביו\"\u0004 (דברים כג, א), וכוונתו: \u0003כנף שראה אביו לא יגלה,\u0004 כלומר, שאסור לאדם לבוא, על אשה שאביו בא עליה כבר.","\u0003וממאי\u0004 \u0005[וממה\u0006 יודעים אנו\u0005]\u0006 ש\u0003באנוסה כתיב\u0004 \u0005[נאמר\u0006 הדבר\u0005]\u0006 ואיננו רק ביאור לאיסור אשת אביו — \u0003מעילויה דקרא\u0004 \u0005[מהמקרא שלמעלה,\u0006 שלפני זה\u0005],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בו דין אונס: \u0003\"ונתן האיש השכב עמה לאבי הנער חמשים כסף\"\u0004 (שם כב, כט) \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 נאמר: \u0003\"לא יקח איש\u0004 את אשת אביו ולא יגלה את כנף אביו","\u0003\"\u0004(שם כג, א). הרי שר' יהודה דורש סמוכים במשנה תורה, אף שאיננו דורש בשאר התורה. ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 שאינם סבורים כר' יהודה, מה הם משיבים על טענה זו? הם אומרים: \u0003אי הוה סמיך ליה\u0004 \u0005[אם היה סמוך לו\u0006 ממש\u0005],\u0006 היה זה \u0003כדקאמרת\u0004 \u0005[כפי שאתה אומר],\u0006 \u0003השתא דלא סמיך ליה\u0004 \u0005[עכשיו שאיננו סמוך לו],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006הלא \u0005נאמר]\u0006 \u0003\"לא יקח איש את אשת אביו\" בינתים,\u0004 בין דין אנוסה לבין \"לא יגלה כנף אביו\", הרי זה מפסיק את הסמיכות ויש לומר שמקרא מיוחד זה של \"לא יגלה כנף אביו\" —","\u0003בשומרת יבם\u0004 של אביו \u0003הכתוב מדבר,\u0004 באשת אחי אביו שמת, והיא ממתינה (\"שומרת\") לאביו שייבם אותה, הרי היא כבר \"כנף אביו\", ואסורה על הבן. ואף ששומרת יבם זו היא אשת דודו שאיסורה מפורש — כתוב זה בא ללמד \u0003לעבור עליו בשני לאוין.\u0004 שאם בא עליה נענש משום אשת דודו ומשום \"כנף אביו\".","ושואלים: \u0003ו\u0004ר' יהודה, שכרגיל אינו לומד מסמיכות הפרשיות — \u0003במשנה תורה מאי טעמא דדריש\u0004 \u0005[מה הטעם\u0006 שהוא כן \u0005דורש]?\u0006 ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 טעם אחד — \u0003משום\u0004 ש\u0003מוכח\u0004 הדבר כאן מן הענין, \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 טעם אחר \u0003משום דמופני\u0004 \u0005[ש\u0006הוא \u0005מופנה],\u0006 שפסוק זה מיותר, ולא בא אלא ללמד לדרשה זו.","ומפרטים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 \u0003משום\u0004 ש\u0003מוכח\u0004 הדבר כאן מן הענין \u0003— ש\u0004\u0003אם כן,\u0004 אם לא היתה כוונה ללמדנו מסמיכות הפרשיות, \u0003לכתביה רחמנא\u0004 \u0005[שתכתוב אותו התורה]\u0006 לדין זה שלא יקח איש את אשת אביו \u0003גבי\u0004 \u0005[אצל]\u0006 שאר דיני ה\u0003עריות\u0004 בספר ויקרא, וכיון שנכתב שלא במקומו, בודאי בא ללמד שיש לדרוש מן הסמיכות. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003משום דמופני\u0004 \u0005[ש\u0006הוא \u0005מופנה]\u0006 — ש\u0003אם כן,\u0004 שלולא בא הדבר ללמדנו הלכה נוספת \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 רק \u0003\"לא יקח איש את אשת אביו\", \"לא יגלה כנף אביו\" למה לי?\u0004"],["\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שבאו רק \u0003לאפנויי\u0004 \u0005[להפנות,\u0006 לייתר\u0005]\u0006 את הכתוב, שיהיה פנוי ממשמעות אחרת, ומיותר במקומו, על מנת ללמוד ממנו הלכה מיוחדת. \u0003וגבי\u0004 \u0005[ואצל]\u0006 \u0003ציצית נמי\u0004 \u0005[גם כן]\u0006 יש טעם מיוחד לדרשת הסמוכים; \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שיש לדרוש זאת \u0003משום\u0004 ש\u0003מוכח\u0004 הדבר כאן מן הענין, \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003משום\u0004 שהוא \u0003מופנה,\u0004 שפסוק זה מיותר, ולא בא אלא ללמד לדרשה זו.","ומפרטים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 \u0003משום\u0004 ש\u0003מוכח\u0004 הדבר מן הענין \u0003— ש\u0004\u0003אם כן\u0004 שאיננו בא ללמוד מן הסמיכות \u0003לכתביה רחמנא\u0004 \u0005[שתכתוב אותו התורה]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003פרשת ציצית\u0004 (במדבר פרק טו), \u0003למאי הלכתא כתביה הכא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה כתבו כאן] —\u0006 ודאי ללמוד מסמיכות הפסוקים. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003משום\u0004 שהוא \u0003מופנה,\u0004 שמיותר הכתוב — \u0003מכדי\u0004 \u0005[הרי\u0006 כבר\u0005]\u0006 \u0003כתב: \"ובגד כלאים שעטנז לא יעלה עליך\"\u0004 (ויקרא יט, יט), ואם כן \u0003\"לא תלבש שעטנז\"\u0004 (דברים כב, יא) \u0003למה לי?\u0004 אלא ודאי \u0003שמע מינה לאפנויי\u0004 \u0005[למד מכאן\u0006 שבא \u0005להפנות]\u0006 את הכתוב לצורך דרשת הסמוכים.","את הנימוק הזה דוחים: \u0003הני מצרך צריכי\u0004 \u0005[\u0006שני כתובים \u0005אלה צריכים\u0006 הם\u0005]\u0006 להיכתב, \u0003דאי כתב רחמנא\u0004 \u0005[שאילו כתבה התורה]\u0006 רק \u0003\"לא יעלה עליך\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003כל דרך העלאה\u0004 שמעלה בגד שעטנז על עצמו \u0003אסר רחמנא\u0004 \u0005[אסרה התורה],\u0006 \u0003ואפילו מוכרי כסות\u0004 שאינם לובשים את הבגדים אלא רק מניחים אותם על כתפם, על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"לא תלבש שעטנז\",\u0004 לומר שאין האיסור אלא \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003לבישה דאית ביה\u0004 \u0005[שיש בה]\u0006 \u0003הנאה\u0004 ולא העלאה בלבד.","ומצד שני \u0003ואי כתב רחמנא\u0004 \u0005[ואילו כתבה התורה]\u0006 רק \u0003\"לא תלבש\" הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003דוקא לבישה, דנפיש הנייתה\u0004 \u0005[שמרובה הנאתה]\u0006 שיש בה גם חימום וגם קישוט, \u0003אבל העלאה\u0004 כלל \u0003לא\u0004 נאסרה, גם כשמתחמם בבגד, על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"לא יעלה עליך\",\u0004 לומר, שאף בהעלאה בלבד יש איסור.","ומשיבים: בכל זאת יש כאן ייתור, ש\u0003אם כן לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 רק \u0003\"לא תלבש שעטנז\",\u0004 והמילים \u0003\"צמר ופשתים\" למה לי\u0004 לכתוב? שהרי אנחנו יכולים לדעת מהו שעטנז ממקור אחר.","כיצד: \u0003מכדי כתב\u0004 \u0005[הרי כתב\u0006 כבר\u0005]\u0006 \u0003\"ובגד כלאים שעטנז לא יעלה עליך\", ותנא דבי\u0004 \u0005[ושנה\u0006 החכם מ\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: הואיל ונאמרו בתורה סתם \"בגדים\", ופרט לך הכתוב באחד מהן\u0004 בדיני נגעים (ויקרא יג, מז) שבגדים הם בגדי \u0003צמר ופשתים — אף כל\u0004 בגדים האמורים בתורה \u0003צמר ופשתים\u0004 הם. ואם כן \u0003\"צמר ופשתים\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 במפורש לגבי שעטנז \u0003למה לי? שמע מינה לאפנויי\u0004 \u0005[למד מכאן\u0006 שבאו רק \u0005להפנות,\u0006 לייתר את הכתוב\u0005]\u0006 ללימוד אחר.","ומקשים: \u0003ואכתי איצטריך\u0004 \u0005[ועדיין הוצרך]\u0006 פסוק זה, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003העלאה\u0004 בלבד \u0003היא\u0004 ש\u0003לא נפיש\u0004 \u0005[מרובה]\u0006 \u0003הנאתה\u0004 ולכן נאסרו בהעלאה רק צמר ופשתים, \u0003אבל לבישה דנפיש הנייתה\u0004 \u0005[שמרובה הנאתה] —\u0006 \u0003כל תרי מיני\u0004 \u0005[שני מינים]\u0006 יחד \u0003אסר רחמנא\u0004 \u0005[אסרה התורה]\u0006 ללובשם, על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 גם לענין לבישה \u0003\"צמר ופשתים\"!\u0004","ומשיבים: \u0003אם כן לשתוק קרא מיניה\u0004 \u0005[שישתוק הכתוב ממנו]\u0006 ולא יזכיר כלל \"צמר ופשתים\", \u0003ותיתי\u0004 \u0005[ויבוא,\u0006 וילמד\u0005]\u0006 דין זה בגזירה שווה \u0003\"שעטנז\" \"שעטנז\" מהעלאה\u0004 שגם בלבישה אסור רק צמר ופשתים יחד, וכיון שנזכר הדבר שוב — בודאי לא בא אלא לומר שיש לדרוש סמוכים.","ושואלים: \u0003ו\u0004ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל,\u0004 שלדבריו \"צמר ופשתים\" מיותר, ונדייק מכאן: \u0003טעמא דכתב רחמנא\u0004 \u0005[הטעם,\u0006 דווקא \u0005שכתבה התורה]\u0006 \u0003\"צמר ופשתים\", הא לאו הכי\u0004 \u0005[הרי לולא כן]\u0006 לגבי \u0003כלאים בציצית הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003דאסר רחמנא\u0004 \u0005[שאסרה התורה]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"ועשו להם ציצת על כנפי בגדיהם\"\u0004 (במדבר טו, לח)","\u0003ותנא דבי\u0004 \u0005[ושנה\u0006 החכם מ\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: כל בגדים\u0004 האמורים בתורה \u0003צמר ופשתים הם,\u0004 משמע שמטילים ציצית גם בבגדי פשתן \u0003ואמר רחמנא\u0004 \u0005[ואמרה התורה]\u0006 בדיני ציצית \u0003עביד ליה\u0004 \u0005[עשה לו]\u0006 \u0003תכלת, ו\u0004הרי \u0003תכלת עמרא\u0004 \u0005[צמר]\u0006 \u0003הוא,\u0004 ונמצא שהתורה מצוה בפירוש לקשור לפחות חוט אחד של תכלת, שהוא צמר, אף בבגד פשתים, ונמצא שהותר שעטנז בציצית. בדרך אגב שואלים לבירור הדברים: \u0003וממאי\u0004 \u0005[וממה,\u0006 מניין יודעים\u0005]\u0006 ש\u0003תכלת עמרא\u0004 \u0005[צמר]\u0006 \u0003הוא?\u0004 ומשיבים: \u0003מ\u0004כיון ש\u0003\"שש\"\u0004 האמור בבגדי כהונה הוא \u0003כיתנא\u0004 \u0005[פשתים]\u0006 (ראה יומא עא, ב) — \u0003תכלת\u0004 בודאי \u0003עמרא\u0004 \u0005[צמר]\u0006 \u0003הוא.\u0004","ולעיקר השאלה משיבים: אף לשיטה זו \u0003איצטריך\u0004 \u0005[צריך]\u0006 את הלימוד מן הסמוכים להתיר כלאים בציצית, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003כ\u0004דעת \u0003רבא,\u0004 ש\u0003רבא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 \"ונתנו על ציצית הכנף פתיל תכלת\" (שם שם) \u0003\"הכנף\"\u0004 משמע \u0003מין כנף,\u0004 ומכאן שאת חוטי הציצית עושים מאותו מין שממנו עשויה כנף הבגד ומכל מין שהוא, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"צמר ופשתים\",\u0004 ומשמע שרק מאלה עושים ציצית ולא מדבר אחר!","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 ניישב את הסתירה? אלא, ציצית של \u0003צמר ופשתים פוטרין\u0004 את הבגד במצוות ציצית \u0003בין\u0004 בבגד \u0003במינן\u0004 (של צמר ופשתים), \u0003בין שלא במינן\u0004 בכל מיני אריגים אחרים. ואילו \u0003שאר מינין\u0004 שעושים מהם חוטי ציצית, \u0003במינן — פוטרין,\u0004 כגון ציצית משי בבגד משי, אבל את הבגד \u0003שלא במינן — אין פוטרין.\u0004 ונמצא שלולא הפסוק \"צמר ופשתים\" היה צריך לעשות ציצית ממין הכנף ולבגד צמר דווקא ציצית מצמר ולא מכלאים.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 ה\u0003תנא דבי\u0004 \u0005[\u0006מ\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את שיטת \u0003רבא,\u0004 שלדעתו בגד שאינו עשוי צמר ופשתים אינו חייב כלל בציצית, ואם כן לשיטתו אין צורך כלל בכתוב מיוחד להוציא מדרשת רבא בענין \"הכנף\" מין כנף.","ומשיבים: עדיין \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 לפחות \u0003כי דיוקא\u0004 \u0005[כמו הדיוק]\u0006 של \u0003רבא\u0004 ובאופן אחר קצת, שהייתי אומר: \u0003\"הכנף\" — מין כנף, והכי קאמר רחמנא\u0004 \u0005[וכך אמרה התורה]:\u0006 \u0003עביד ליה\u0004 \u0005[עשה לו]\u0006 ציציות \u0003צמר ל\u0004בגד \u0003צמר\u0004, \u0003ו\u0004ציציות \u0003פשתים לפשתים. וכי עבידת\u0004 \u0005[וכאשר עושה אתה]\u0006 ציציות \u0003צמר ל\u0004בגד \u0003צמר — צבעיה\u0004 \u0005[צבע אותו\u0006 בתכלת\u0005]\u0006 ותצא בכך ידי מצות ציצית, \u0003אבל\u0004 כאשר אין הציציות והבגד מאותו מין, וכגון ציציות \u0003צמר ל\u0004בגד \u0003פשתים, ופשתים ל\u0004בגד \u0003צמר — לא\u0004 תצא בכך, על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"צמר ופשתים\",\u0004 ש\u0003אפילו\u0004 בציציות \u0003צמר ל\u0004בגד \u0003פשתים ופשתים לצמר\u0004 יוצא ידי חובת ציצית."],["\u0003תינח\u0004 \u0005[נניח],\u0006 שהגענו למציאת הוכחה, \u0003ל\u0004שיטת ה\u0003תנא דבי\u0004 \u0005[\u0006מ\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל,\u0004 הסבור שכל בגדים האמורים בתורה הם בגדים העשויים צמר ופשתים בלבד. אולם \u0003לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 שאינם סבורים כן, \u0003מנא להו\u0004 \u0005[מניין להם]\u0006 שעשה דוחה את לא תעשה? שהרי, כפי שהוכחנו, לימוד זה שעשה של ציצית דוחה לא תעשה של כלאים תלוי בייתור, וייתור זה מתבסס על שיטת תנא דבי ר' ישמעאל.","ומשיבים: \u0003נפקא להו\u0004 \u0005[יוצא להם,\u0006 נלמד הדבר\u0005]\u0006 \u0003מ\"ראשו\"\u0004 האמור בדין המצורע. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר במצורע הנטהר מצרעתו: \"והיה ביום השביעי יגלח את כל שערו את ראשו ואת זקנו ואת גבות עיניו ואת כל שערו יגלח\" (ויקרא יד, ט) וכיון שנאמר כבר \"כל שערו\", \u0003\"ראשו\" מה תלמוד לומר,\u0004 מה בא ללמדנו? ומסבירים: \u0003לפי שנאמר \"לא תקפו פאת ראשכם\"\u0004 (שם יט, כז) שאסור לגלח את פאות הראש, ומהפסוק הזה \u0003שומע\u0004 (למד) \u0003אני\u0004 כי \u0003אף מצורע כן,\u0004 שגם הוא בכלל איסור זה,","\u0003תלמוד לומר\u0004 שפירש הכתוב \u0003\"ראשו\",\u0004 ללמדנו שמצות תגלחת מצורע דוחה את לא תעשה של הקפת (גילוח) פאת הראש. ומעירים: \u0003וקא סבר האי תנא\u0004 \u0005[וסבור תנא זה]\u0006 כי \u0003הקפת כל הראש שמה הקפה.\u0004 כי יש חכמים הסבורים שעובר משום הקפת פאת הראש רק כאשר משאיר חלק משערות הראש ומוריד את הפאות בלבד, אבל תנא זה סבור שאם מסיר את כל שערות הראש כולן, כמצורע המגלח כל שערו, אם הוריד גם את הפאות עובר משום לאו של הקפה, ומתגלחת מצורע למדנו איפוא שעשה דוחה את לא תעשה!","ומקשים: \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך,\u0006 לשבור\u0005]\u0006 את ההוכחה הזו ולומר: \u0003מה ללאו\u0004 (מצות לא תעשה) של \u0003הקפה\u0004 שהוא מיוחד ואי אפשר ללמוד ממנו לשאר דברים, \u0003שכן\u0004 הוא \u0003לאו שאין שוה בכל,\u0004 שמצות לא תעשה זו של הקפה אינה חלה על הכל, שכן הנשים אינן בכלל איסור זה, ואין ללמוד איפוא ממה שנדחה לאו כזה, שגם לא תעשה החל על הכל יידחה על ידי מצות עשה!","\u0003אלא\u0004 יש להציע דרך אחרת: \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר מייתור אחר, \u0003מ\"זקנו\". דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא אחרת\u0005]:\u0006 \u0003\"זקנו\"\u0004 שנאמר בתגלחת המצורע \u0003מה תלמוד לומר?\u0004 הרי הוא כבר נכלל ב\"כל שערו\"? אלא, ההסבר הוא: \u0003לפי שנאמר\u0004 בכהנים \u0003\"ופאת זקנם לא יגלחו\"\u0004 (שם כא, ה), ומפסוק זה \u0003שומע\u0004 (למד) \u0003אני\u0004 כי \u0003אף כהן מצורע\u0004 בכלל \u0003כן,\u0004 שאסור לו לגלח את זקנו — \u0003תלמוד לומר\u0004 במצורע במפורש \u0003\"זקנו\".\u0004","אמנם, גם גילוח זקן לאו שאינו שווה בכל, כיון שאינו חל על הנשים, \u0003ואם\u0004 לימוד זה מ\"זקנו\" \u0003אינו ענין ללאו שאין שוה בכל,\u0004 שהרי כבר למדנו מ\"ראשו\" שלאו שאינו שוה בכל נדחה מפני מצות עשה, ואין צורך איפוא בלימוד נוסף, על כן יש להבין שהחזרה על מקרה מסויים זה באה להרחיב את הלימוד, ולכן \u0003תנהו ענין ללאו השוה בכל,\u0004 שאף מצות לא תעשה השווה בכול נדחית על ידי מצות עשה.","את ההוכחה הזו דוחים: \u0003ואכתי איצטריך\u0004 \u0005[ועדיין נצרך]\u0006 \"זקנו\" להיאמר לגופו וללמד שהלאו של הקפת זקן הכהנים נדחה מפניו, ואין כאן ייתור שממנו אפשר ללמוד בדרך \"אם אינו ענין\", משום שיש בכתוב זה צד חידוש אחר, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003כהנים, הואיל וריבה בהן הכתוב מצות יתירות\u0004 ולכך יש להחמיר בהם, ואם כן \u0003אפילו לאו שאין שוה בכל\u0004 גם \u0003לא דחי\u0004 \u0005[תדחה]\u0006 מצות עשה, ולכן \u0003קא משמע לן דדחי\u0004 \u0005[השמיע לנו ש\u0006היא \u0005דוחה]!\u0006","\u0003אלא\u0004 יש לדחות מה שאמרנו, ולומר באופן אחר, ש\u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הכלל שעשה דוחה את לא תעשה מהלימוד \u0003מ\u0004המלה \u0003\"ראשו\" דהך תנא\u0004 \u0005[של תנא זה]\u0006 בדרך אחרת. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 על הכתוב במצורע \"יגלח את כל שערו את ראשו... \" (שם יד, ט): \u0003\"ראשו\" מה תלמוד לומר\u0004 אחר שכבר נאמר \"כל שערו\"? ומסבירים: \u0003לפי שנאמר\u0004 בנזיר \u0003\"תער לא יעבר על ראשו\"\u0004 (במדבר ו, ה) \u0003שומע אני\u0004 לכאורה ש\u0003אף מצורע ונזיר\u0004 בכלל \u0003כן,\u0004 שנזיר שנצטרע אסור לו לגלח ראשו בטהרתו, על כן \u0003תלמוד לומר: \"ראשו\"\u0004 ללמד שמצות עשה של גילוח מצורע דוחה את מצות לא תעשה של נזיר.","ודוחים: עדיין \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך]\u0006 את ההוכחה, ולומר כך: גם האיסור בנזיר איננו איסור חמור כל כך, כי יש לטעון: \u0003מה לנזיר מצורע — שכן\u0004 עצם נדר הנזיר \u0003ישנו בשאלה\u0004 לחכם ויש בכך התרה לאיסורו, ומשיתיר לו החכם נדרו, תותר נזירותו, ואז יתבטל גם איסור התגלחת, וכיון שהלאו הזה איננו חמור כל כך, אין להביא ממנו הוכחה לכל איסורי התורה. ומוסיפים עוד, \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך],\u0006 שהלאו בנזיר איננו חמור כלאוים אחרים — \u0003הא דקיימא לן\u0004 \u0005[זה שמוחזק לנו]\u0006 הכלל ההלכתי ש\u0003אין עשה דוחה\u0004 את \u0003לא תעשה ועשה\u0004 יחד, ואם כן הרי היה לנו","\u0003ליגמר\u0004 \u0005[ללמוד]\u0006 \u0003מנזיר\u0004 היפוכו של כלל זה, שהרי בנזיר יש גם מצות עשה של גידול שיער וגם מצות לא תעשה שלא לגלח את השיער. ולכאורה מצות עשה של גילוח מצורע דוחה את שתיהן! \u0003אלא, מנזיר מאי טעמא לא גמרינן\u0004 \u0005[מה טעם אין אנו לומדים]\u0006 הלכה כללית, משום \u0003דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום \u0005לפרוך]\u0006 את הראיה, ולומר שאין למדים מנזיר \u0003שכן ישנו בשאלה — הכי נמי\u0004 \u0005[כך גם כן]\u0006 לענייננו, ללמוד מכאן שעשה דוחה את לא תעשה בכלל, \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך]\u0006 בטענה \u0003שכן ישנו בשאלה.\u0004 ואם כן אין להביא ראיה מדין הנזיר.","\u0003אלא\u0004 יש לחזור מן ההצעות הללו, ולומר כי \u0003לעולם\u0004 נלמד הדבר"],["\u0003מקרא קמא\u0004 \u0005[מן הכתוב הראשון]\u0006 המתיר כלאים בציצית. וכנגד הטענה שהעלינו, שלדעת חכמים המילים \"צמר ופשתים\" הכתובות שם אינן מיותרות, ואין מהן הוכחה שיש לדרוש סמוכים להתיר כלאים בציצית ושידחה העשה את הלא תעשה — יש להשיב: \u0003אם כן,\u0004 שאין כאן לימוד נוסף, \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 רק \u0003\"ציצית תעשה לך\",\u0004 המלה \u0003\"גדילים\"\u0004 הכתובה שם \u0003למה לי? שמע מינה לאפנויי\u0004 \u0005[למד מכאן\u0006 שבא הדבר \u0005להפנות]\u0006 את הדבר ולייתר את המילים כדי ללמוד סמוכים.","ומקשים: \u0003האי\u0004 \u0005[זה]\u0006 \"גדילים\", \u0003לשיעורא\u0004 \u0005[ל\u0006שם \u0005שיעור]\u0006 הציציות \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 ללמדנו כמה חוטים צריך להיות בציצית, וכן שנינו: \u0003גדיל,\u0004 שהוא דבר שזור — לפחות \u0003שנים,\u0004 שני חוטים, שהרי אי אפשר לשזור אלא משני חוטים לפחות, וכאשר נאמר \u0003\"גדילים\"\u0004 בלשון רבים משמע איפוא: \u0003ארבעה\u0004 חוטים (שני גדילים, כל אחד של שני חוטים), והכוונה היא: \u0003עשה גדיל ופותלהו\u0004 (כפול אותו. תוספות) \u0003מתוכו\u0004 (מאמצעו), ומכאן שמונה חוטים שבציצית. הרי שהמלה \"גדילים\" אינה מיותרת כלל!","ומשיבים: \u0003אם כן,\u0004 שאין כאן ייתור מלה לשם דרשה, \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 רק \u0003\"לא תלבש שעטנז\",\u0004 המילים \u0003\"צמר ופשתים יחדו\" למה לי? שמע מינה לאפנויי\u0004 \u0005[למד מכאן\u0006 שבאו \u0005להפנות\u0006 אותן\u0005]\u0006 לדרשה.","ומקשים: \u0003ואכתי מיבעי ליה\u0004 \u0005[ועדיין נצרך לו]\u0006 שיאמר \"צמר ופשתים יחדיו\", כדי ללמד הלכה אחרת בדין כלאים: שאם מחבר אדם בגד צמר ובגד פשתן, אם \u0003תוכף שתי תכיפות\u0004 (תפירות מחט) — הרי זה \u0003חיבור,\u0004 ואילו \u0003תכיפה אחת\u0004 (תפר מחט אחד) — \u0003אינו חיבור,\u0004 ודבר זה נלמד מן ההדגשה \"יחדיו\", שיהיו שניהם מחוברים היטב יחד! ומשיבים: \u0003אם כן, לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"לא תלבש צמר ופשתים יחדו\",\u0004 המלה הנוספת \u0003\"שעטנז\" למה לי? שמע מינה לאפנויי\u0004 \u0005[למד מכאן\u0006 ש\u0005להפנות\u0006 אותה\u0005]\u0006 באה, וללמד.","ומקשים: \u0003ואכתי מיבעי ליה\u0004 \u0005[ועדיין צריך לו]\u0006 לאומרה, שאת המלה \"שעטנז\" מבינים כנוטריקון, קיצור מילים, ולמדים שאין דין כלאים חל אלא \u0003עד שיהא שוע\u0004 (חלק וסרוק) \u0003טווי\u0004 כחוט, \u0003ונוז\u0004 (מחובר, ארוג כאחד), ואם אין בו תכונות אלה איננו נקרא שעטנז! \u0003אלא\u0004 יש להסביר בדרך אחרת: כל הדרשה \u0003כולה מ\u0004המלה \u0003\"שעטנז\" נפקא\u0004 \u0005[יוצאת,\u0006 נלמדת\u0005]\u0006 כיון שהשתמש הכתוב במלה המיוחדת \"שעטנז\" (ולא נאמר רק \"צמר ופשתים יחדיו\"), לא זו בלבד שאנו למדים ממנה לענין הלכה, אלא אפשר ללמוד ממנה גם גזירה שווה מספר ויקרא (יט, יט). ונמצא שיש ייתור מילים בכתוב בספר דברים, ועל פי ייתור זה אפשר להגיע למסקנה כללית כי מצות עשה דוחה את לא תעשה.","בשלב זה של הדיון נמצא לו איפוא הוכחה לפי השיטות השונות, אולם לעצם הבעיה שהועלתה יש עוד מקום לבירור: \u0003אשכחן דאתי\u0004 \u0005[מצאנו שבאה]\u0006 מצות \u0003עשה ודחי\u0004 \u0005[ודוחה]\u0006 את מצות \u0003לא תעשה גרידא\u0004 \u0005[סתם],\u0006 אולם שמצות עשה דוחה את \u0003לא תעשה שיש בו כרת, היכא אשכחן דדחי דאיצטריך\u0004 \u0005[איפה מצאנו ש\u0006הוא \u0005דוחה, שהוצרכה]\u0006 המלה \u0003\"עליה\" למיסרה\u0004 \u0005[לאסור אותו]?\u0006 שהרי למדנו מייתור תיבת \"עליה\" שמצות ייבום איננה מבטלת את איסור אחות אשה, ולכאורה עדיין לא הוכחנו שגדול כוחה של כל מצות עשה לדחות לא תעשה חמור, שיש בו עונש כרת!","\u0003וכי תימא נילף\u0004 \u0005[ואם תאמר נלמד]\u0006 \u0003מ\u0004מצות \u0003מילה,\u0004 שמצות עשה של מילה דוחה את לא תעשה של איסור מלאכה בשבת שיש בו כרת, שהרי מלים ביום השמיני אפילו כשחל בשבת — אפשר לטעון כנגד זה: \u0003מה למילה\u0004 שהיא מצות עשה חמורה וחשובה ביותר, \u0003שכן נכרתו עליה שלש עשרה בריתות,\u0004 שהמלה \"ברית\" נאמרה בפרשת מילה (בראשית פרק יז) שלוש עשרה פעמים!","ומשיבים: נלמד \u0003מפסח\u0004 ששחיטתו דוחה את השבת, ואף כאן מצות עשה דוחה את לא תעשה שיש בו כרת! ודוחים: \u0003מה לפסח, שכן\u0004 מצות עשה חמורה היא שהרי חייב \u0003כרת\u0004 אם לא הביאו, מה שאין כן במצוות עשה אחרות!","ואומרים: אם כן נלמד \u0003מ\u0004קרבן \u0003תמיד\u0004 הנשחט בכל יום, אפילו בשבת ונמצא שמצות לא תעשה של שבת, שיש בה כרת, נדחית מפני העשה של הקרבת התמיד! ודוחים: \u0003מה לתמיד — שכן תדיר,\u0004 שמאחר שמצות התמיד חלה בכל יום ויום יש לה איפוא חשיבות מיוחדת ולכך היא דוחה אף לא תעשה חמור, אבל מצות עשה הבאה רק בזמנים מיוחדים — שמא אין כוחה גדול לדחות לא תעשה חמור.","ואומרים: אכן \u0003מחדא לא אתיא\u0004 \u0005[מאחת\u0006 מההוכחות הללו \u0005אינה באה],\u0006 אין להביא ראיה, ואולם \u0003תיתי מתרתי\u0004 \u0005[תבוא\u0006 ההוכחה \u0005משתים]\u0006 יחד, שנקח שתי מצוות יחד, ונלמד מן הצד השוה שבהן. ושואלים: \u0003מהי תיתי\u0004 \u0005[מאיזו תבוא]?\u0006 אם \u0003ממילה ופסח\u0004 יחד — הרי אף אלה מיוחדות בצד שווה חמור \u0003שכן\u0004 חייבים עליהן \u0003כרת!\u0004 אם נלמד \u0003מפסח ותמיד\u0004 הרי הן מיוחדות בצד אחר — \u0003שכן\u0004 הן \u0003צורך גבוה,\u0004 שהן לצורך המזבח, ולא לצורכו של אדם.","ואם תאמר, נלמד \u0003ממילה ותמיד\u0004 — גם הוכחה זו יש לדחות, שכן שתי המצוות הללו \u0003ישנן לפני הדבור,\u0004 שכבר קיימו אותן ישראל עוד לפני דיבור ה' במתן תורה. \u0003ואליבא דמאן דאמר\u0004 \u0005[ולפי שיטתו של מי שאומר]\u0006 כי \u0003עולה שהקריבו ישראל במדבר — עולת תמיד הוה\u0004 \u0005[היתה].\u0006 ועוד: \u0003ומכולהו נמי\u0004 \u0005[ומכולן,\u0006 ממילה פסח ותמיד \u0005גם כן]\u0006 אי אפשר ללמוד, \u0003שכן ישנן לפני הדבור\u0004 שהרי שלושתן היו לפני הדיבור, גם מצות פסח וגם מצות מילה, ואם כן אי אפשר ללמוד הלכה כללית ממצוות אלה!","\u0003אלא\u0004 יש להסביר בדרך אחרת, כי \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 לימוד מיוחד מן המלה \"עליה\", שאלמלא היא היינו אומרים שידחה עשה של ייבום את הלאו של אחות אשה (אף שיש בו כרת). כי \u0003סלקא דעתך אמינא תיתי\u0004 \u0005[יעלה על דעתך לומר\u0006 כי \u0005תבוא,\u0006 תילמד\u0005]\u0006 הלכה זו \u0003מכבוד אב ואם.\u0004","ומה עניינה — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יכול יהא כבוד אב ואם דוחה שבת — תלמוד לומר: \"איש אמו ואביו תיראו ואת שבתתי תשמרו\u0004 אני ה' אלהיכם\u0003\"\u0004 (ויקרא יט, ג), לומר: \u0003כולכם,\u0004 האב כמו הבן, \u0003חייבין בכבודי,\u0004 ולכן אין כבוד אביו דוחה כבוד ה' שציווה על השבת.","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן כגון ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביו: \u0003שחוט לי, בשל לי\u0004 או שאר מלאכות האסורות בשבת באיסור כרת, שאביו מצווה עליו לעשות, \u0003וטעמא דכתב רחמנא\u0004 \u0005[והטעם,\u0006 דווקא, משום \u0005שכתבה התורה]\u0006 במפורש \u0003\"את שבתתי תשמרו\"\u0004 להזהירנו שלא נבטל את מצות לא תעשה של שבת שיש בה כרת, משום כיבוד אב ואם, \u0003הא לאו הכי\u0004 \u0005[הרי לולא זה]\u0006 — \u0003דחי\u0004 \u0005[\u0006היתה \u0005דוחה]\u0006 ואפשר איפוא ללמוד מכאן שבדרך כלל מצות עשה דוחה את לא תעשה, אף על פי שיש בו כרת. ודוחים: \u0003לא\u0004"],["\u0003לאו\u0004 (מצות לא תעשה) של \u0003מחמר\u0004 אחר בהמה. שאף שדבר זה אסור בשבת משום עבודת הבהמה עצמה (\"לא תעשה כל מלאכה אתה... ובהמתך\". שמות כ, י), מכל מקום כיון שהוא עצמו אינו עושה כל מלאכה בבהמה עצמה, אין בו חיוב כרת, אלא מצות לא תעשה בלבד. \u0003ו\u0004אם אמר לו אביו לחלל את השבת בכך, ולחמר אחרי חמורו, \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003לא דחי\u0004 \u0005[אינה דוחה]\u0006 מצות כיבוד אב את מצות לא תעשה של מחמר.","ושואלים: אם כן, \u0003אלא\u0004 זו \u0003דקיימא לן\u0004 \u0005[שמוחזק לנו]\u0006 \u0003דאתי\u0004 \u0005[שבאה]\u0006 מצות \u0003עשה ודחי\u0004 \u0005[ודוחה]\u0006 את מצות \u0003לא תעשה,\u0004 אם כן \u0003ליגמר מהכא\u0004 \u0005[נלמד מכאן]\u0006 ש\u0003לא לידחי\u0004 \u0005[ידחה]!\u0006 שכשם שלמדנו בבנין אב ממצות ציצית שדוחה את לא תעשה של כלאים לכל מצוות עשה שדוחות את לא תעשה, מדוע לא נאמר להיפך: שמצות עשה איננה דוחה את לא תעשה, ונלמד זאת בבנין אב מכיבוד אב ואם!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שאין ללמוד מכאן, כי \u0003שאני לאוי\u0004 \u0005[שונים\u0006 איסורי \u0005לא\u0006 תעשה\u0005]\u0006 של \u0003שבת דחמירי\u0004 \u0005[ש\u0006הם \u0005חמורים]\u0006 ביותר, ומשום כך אינם נדחים מפני כיבוד אב ואם, \u0003ו\u0004אולם אין לומר כך, כי \u0003הא\u0004 \u0005[הרי]\u0006 ה\u0003תנא בעלמא קאי ולא קפריך\u0004 \u0005[בכלל מדבר ואיננו פורך,\u0006 מקשה\u0005]\u0006 קושיה זו!","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא אחרת\u0005]:\u0006 \u0003יכול אמר לו אביו\u0004 לבנו הכהן או הנזיר: \u0003היטמא\u0004 למת כדי להביא לי דבר ממקום טמא, \u0003או שאמר לו\u0004 לבנו: \u0003אל תחזיר\u0004 אבידה, \u0003יכול ישמע לו\u0004 הבן? \u0003תלמוד לומר: \"איש אמו ואביו תיראו ואת שבתתי תשמרו\u0004 אני ה' אלהיכם\u0003\"\u0004 (ויקרא יט, ג), לומר: \u0003כולכם חייבין בכבודי.\u0004 הרי שאין התנא מבדיל בין חילול שבת, שהוא מצות לא תעשה חמורה, לבין האיסור לכהן להיטמא למתים, שהיא מצות לא תעשה קלה יותר.","\u0003אלא,\u0004 יש לדחות מה שאמרנו, ולומר שבברייתא הראשונה אין מדובר במי שאמר לו אביו לחלל את השבת בשחיטה או בבישול שהן מלאכות שיש בהן איסור כרת. אלא שאין ללמוד ממה שנאמר לענין כיבוד אב שאין עשה דוחה לא תעשה, \u0003משום דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום \u0005לפרוך,\u0006 להקשות\u0005]\u0006 על אפשרות־לימוד כללית זו, ולומר:","\u0003מה להנך\u0004 \u0005[לאלה]\u0006 \u0003שכן\u0004 כאשר מחמר בשבת לכבוד אביו הרי הוא רק \u0003הכשר מצוה,\u0004 שיש בכך רק הכנה למצות כיבוד אב, ובינתיים הוא רק מכין את הדברים. ואין ללמוד מכאן למקומות אחרים (ר\"ח).","\u0003אלא\u0004 כך היינו יכולים לחשוב: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003תיתי\u0004 \u0005[תבוא,\u0006 תילמד\u0005]\u0006 סברה זו \u0003מבנין בית המקדש. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יכול יהא בנין בית המקדש דוחה\u0004 את ה\u0003שבת — תלמוד לומר: \"את שבתתי תשמרו ומקדשי תיראו\u0004 אני ה'\u0003\"\u0004 (שם יט, ל), וכוונת הפסוק: \u0003כולכם חייבין בכבודי\u0004 ושמירת השבת כבוד ה' היא, והוא מקפיד שהשבת תישמר אפילו כאשר בונים מקדש.","משמע שלולא לימוד מיוחד זה, היינו אומרים שבנין בית המקדש, שהוא מצות עשה, דוחה את לא תעשה של שבת, \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר בבנין בית המקדש במלאכות גמורות, כגון \u0003בבונה וסותר\u0004 שהן מלאכות שיש בהן איסור כרת, \u0003וטעמא\u0004 \u0005[והטעם,\u0006 דווקא\u0005]\u0006 \u0003דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003\"את שבתתי תשמרו\", הא לאו הכי, דחי\u0004 \u0005[הרי לולא כן,\u0006 היתה \u0005דוחה]!\u0006","ודוחים: \u0003לא,\u0004 גם כאן מדובר על \u0003לאו\u0004 (מצות לא תעשה) של \u0003מחמר, ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003לא דחי\u0004 \u0005[אינו דוחה].\u0006 ומקשים שוב, מעין קושייתנו הקודמת: \u0003ואלא\u0004 מה \u0003דקיימא לן דאתי\u0004 \u0005[שמוחזק לנו שבאה]\u0006 מצות \u0003עשה ודחי\u0004 \u0005[ודוחה]\u0006 את מצות \u0003לא תעשה, ליגמר מהכא דלא דחי\u0004 \u0005[נלמד מכאן,\u0006 מבנין בית המקדש \u0005שאינה דוחה]!\u0006","\u0003וכי תימא שאני לאוי\u0004 \u0005[ואם תאמר\u0006 כי \u0005שונים\u0006 איסורי \u0005לא\u0006 תעשה\u0005]\u0006 של \u0003שבת דחמירי\u0004 \u0005[ש\u0006הם \u0005חמורים]\u0006 — \u0003והא\u0004 \u0005[והרי]\u0006 ה\u0003תנא בעלמא קאי ולא קא פריך\u0004 \u0005[בכלל עומד,\u0006 מדבר, \u0005ואיננו פורך,\u0006 מקשה\u0005]\u0006 קושיה זו! \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יכול אמר לו אביו \"היטמא\", או שאמר לו \"אל תחזיר\"\u0004 אבידה \u0003יכול ישמע לו\u0004 הבן — \u0003תלמוד לומר: \"איש אמו ואביו תיראו\u0004 ואת שבתותי תשמורו\u0003\"\u0004 (שם יט, ג) כלומר, \u0003כולכם חייבים בכבודי.\u0004 הרי שאותה ראיה משמשת לא רק לגבי איסורי שבת אלא גם לגבי איסורים אחרים, שאין בהם כרת.","\u0003אלא,\u0004 אין להביא משם ראיה לכל איסורי תורה, מטעם אחר, \u0003משום דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום \u0005לפרוך,\u0006 להקשות\u0005]:\u0006 \u0003מה להנך\u0004 \u0005[לאלה]\u0006 \u0003שכן\u0004 מלאכה במחמר היא רק \u0003הכשר מצוה\u0004 של בנין המקדש, מה שאין כן בשאר מצוות. ומקשים: \u0003הכשר מצוה תיפוק לי מהתם\u0004 \u0005[יצא לי,\u0006 יילמד, \u0005משם]\u0006 ממה שכבר נאמר בדין כיבוד אב ואם שאינו דוחה מצות לא תעשה, ומדוע חזר ואמר אותו דבר גם לענין בנין בית המקדש?","ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך הוא\u0006 באמת \u0005גם כן].\u0006 ואם כן הכתוב \u0003\"ואת שבתתי תשמרו ומקדשי תיראו\"\u0004 (שם ל) \u0003למה לי?\u0004 שהרי את ההלכה הזו שאין בנין מקדש דוחה לאו של מחמר אנו למדים מכיבוד אב ואם. ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריך אותו]\u0006 לענין אחר, \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003יכול יתיירא אדם ממקדש\u0004 ויעשה אותו, את המקדש עצמו, נושא לעבוד אותו, \u0003תלמוד לומר: \"את שבתתי תשמרו ואת מקדשי תיראו\"\u0004 ומהשוואת הדברים בפסוק אחד אנו למדים: \u0003נאמרה שמירה בשבת ונאמרה מורא במקדש, מה שמירה האמורה בשבת\u0004"],["\u0003לא משבת\u0004 עצמה \u0003אתה מתיירא\u0004 שהרי לא נאמר בה \"מורא\", \u0003אלא ממי שהזהיר על השבת, אף מורא האמורה במקדש, לא ממקדש\u0004 עצמו \u0003אתה מתיירא אלא ממי שהזהיר על המקדש.\u0004","ומסבירים: \u0003ואי זו היא\u0004 איפוא הדרך בה מתקיימת מצות \u0003מורא מקדש?\u0004 — \u0003לא יכנס אדם בהר הבית במקלו\u0004 שהולך בו בדרך, או נעול \u0003במנעלו\u0004 כדרך שעושים במקום שאינו מקודש, ולא \u0003בפונדתו\u0004 (בחגורתו שהוא מחזיק בה את הכסף שלו), \u0003ובאבק שעל גבי רגליו, ולא יעשנו קפנדריא\u0004 (קיצור דרך), שלא יעבור דרך המקדש כדי לקצר את הדרך בלכתו ממקום למקום. \u0003ורקיקה\u0004 במקדש אסורה \u0003מקל וחומר.\u0004 שהרי בדברים הקודמים אין משום בזיון, אבל רקיקה, היא דבר מאוס אף בביתו של אדם פרטי, כל שכן בבית המקדש.","\u0003ואין לי\u0004 שחייבים במורא זה \u0003אלא בזמן שבית המקדש קיים, בזמן שאין בית המקדש קיים — מניין\u0004 שמצות מורא המקדש קיימת, ואסור לזלזל במקום של המקדש? \u0003תלמוד לומר: \"את שבתתי תשמרו ומקדשי תיראו\"\u0004 (ויקרא יט, ל), ללמד: \u0003מה שמירה האמורה בשבת — לעולם\u0004 היא, \u0003אף מורא האמורה במקדש\u0004 הריהו \u0003לעולם,\u0004 אף כשהוא חרב. על כל פנים לענייננו עדיין לא הגענו להסבר מדוע יצטרכו ללימוד מיוחד להודיענו שמצות עשה דוחה את לא תעשה שיש בו כרת.","\u0003אלא, סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003תיתי\u0004 \u0005[תבוא,\u0006 תילמד\u0005]\u0006 הנחה זו \u0003מ\u0004מלאכת \u0003הבערה\u0004 בשבת; \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל,\u0004 מה שנאמר: \u0003\"לא תבערו אש בכל משבתיכם\u0004 ביום השבת\u0003\"\u0004 (שמות לה, ג), \u0003מה תלמוד לומר,\u0004 מה בא הדבר ללמדנו, שהרי כבר נאמר באופן כללי שאסור לעשות מלאכה בשבת?","ותוהים: \u0003מה תלמוד לומר?!\u0004 מה שאלה היא זו? \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004שיטת \u0003ר' יוסי\u0004 בא פסוק זה — \u0003ללאו\u0004 (מצות לא תעשה), ללמד שהבערת אש בשבת אין חייבים עליה כרת או סקילה, כשאר מלאכות שבשבת, אלא עוברים בלא תעשה בלבד. \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004שיטת \u0003ר' נתן\u0004 בא הדבר — \u0003לחלק,\u0004 ללמדנו שכדי להתחייב בכרת או סקילה אין צורך שיעבור על כל מלאכות שבת, אלא די במלאכה אחת כדי לחייבו.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בנושא זה: \u0003הבערה ללאו יצתה, דברי ר' יוסי.\u0004 כלומר, אזהרת הבערה יצאה מכלל כל מלאכות שבת ונכתבה במפורש לומר לנו שאין דינה כמלאכות אחרות, ואין עליה חיוב סקילה, אלא מצות לא תעשה (לאו) בלבד. \u0003ר' נתן אומר: לחלק,\u0004 ולהודיע שכל אחת ממלאכות השבת היא איסור נבדל לעצמו, והעושה אותה בשגגה חייב עליה קרבן חטאת, ואם שגג בכמה מלאכות — מביא קרבנות כמספר המלאכות ששגג בהן.","\u0003ואמר רבא\u0004 כתשובה לתמיהתנו בדבר שאלת תנא דבי ר' ישמעאל: \u0003תנא\u0004 זה — המלה \u0003\"מושבות\"\u0004 (\"לא תבערו אש בכל מושבותיכם\") \u0003קא קשיא ליה\u0004 \u0005[קשה לו].\u0006 וכך יש להבין: \u0003\"מושבות\" מה תלמוד לומר,\u0004 מה הלימוד הנוסף שאנחנו למדים מהמלה הזו, הבאה להודיענו שאיסור השבת אינו שייך רק למקומות מושב מסויימים.","\u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003שבת חובת הגוף היא\u0004 וחלה על האדם עצמו, ולא על דברים שמחוצה לו, וכלל בידינו ש\u0003חובת הגוף נוהגת בין בארץ בין בחוץ לארץ,\u0004 ואם כן הדגשה זו של \"\u0003מושבות\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003בשבת — למה לי?\u0004","\u0003משום\u0004 \u0005[משמו]\u0006 של \u0003ר' ישמעאל אמר תלמיד אחד\u0004 דברים אלה, \u0003לפי שנאמר: \"וכי יהיה באיש חטא משפט מות והומת\"\u0004 (דברים כא, כב), ומכתוב זה \u0003שומע\u0004 (למד) \u0003אני\u0004 שממיתים את הנידון \u0003בין בחול בין בשבת. ומה אני מקיים\u0004 את \u0003\"\u0004ושמרתם את השבת כי קודש היא לכם \u0003מחלליה מות יומת\"\u0004 (שמות לא, יד) — \u0003בשאר מלאכות, חוץ ממיתת בית דין\u0004 שנעשית אף בשבת. \u0003או אינו אלא אפילו מיתת בית דין\u0004 בכלל הדברים שאסור לעשות בשבת, \u0003ומה אני מקיים\u0004 לפי זה את דברי הכתוב \u0003\"והומת\"\u0004 — כוונתו \u0003בחול ולא בשבת\u0004.","ואם נחזור ונטען \u0003או אינו אלא אפילו בשבת — תלמוד לומר,\u0004 על ידי גזירה שווה: \u0003\"לא תבערו אש בכל משבתיכם\u0004 ביום השבת\u0003\"\u0004 (שם לה, ג) \u0003ולהלן\u0004 הלאה, \u0003הוא אומר\u0004 בסוף משפט הרוצחים — \u0003\"והיו אלה לכם לחקת משפט לדרתיכם בכל משבתיכם\"\u0004 (במדבר לה, כט)","\u0003מה מושבות האמורים להלן\u0004 בספר במדבר, כוונתו \u0003בבית דין — אף מושבות האמורים כאן\u0004 כוונתו \u0003בבית דין,\u0004 מקום מושב הדיינים, \u0003ואמר רחמנא\u0004 \u0005[ואמרה התורה]:\u0006 \u0003\"לא תבערו\",\u0004 וכיון שאחת ממיתות בית דין היא מיתת שריפה, ונעשית על ידי הבערת אש — נלמד מכאן איפוא שאין מיתת בית דין דוחה את השבת.","ומכאן ממשיכים לענייננו: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 דעת תנא דבי ר' ישמעאל כדעת \u0003ר' נתן,\u0004 ש\u0003אמר\u0004 שאזהרת הבערה \u0003לחלק יצתה,\u0004 ולשיטתו יש גם על הבערה בפני עצמה איסור כרת וסקילה. \u0003ו\u0004אם כן, \u0003טעמא דכתב רחמנא\u0004 \u0005[הטעם,\u0006 דווקא, משום \u0005שכתבה התורה]\u0006 \u0003\"לא תבערו\", הא לאו הכי, דחי\u0004 \u0005[הרי לולא כן,\u0006 היתה מיתת בית דין \u0005דוחה]\u0006 שבת, ומכאן שמצות עשה של \"והומת\" דוחה את מצות לא תעשה שיש בה כרת של הבערת אש בשבת לולא הפסוק שאוסר זאת.","ודוחים: \u0003לא,\u0004 אין מכאן הוכחה, כי אפשר לומר שתנא דבי ר' ישמעאל סבור כ\u0003ר' יוסי\u0004 שהבערה היא איסור לאו בלבד. ומשיבים: \u0003ותיהוי נמי\u0004 \u0005[ו\u0006נניח \u0005שתהיה\u0006 זאת \u0005גם כן],\u0006 שיטת \u0003ר' יוסי\u0004 \u0005—\u0006 \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' יוסי\u0004 ש\u0003הבערה ללאו יצתה\u0004 הרי דבריו אלה הם ב\u0003הבערה גרידתא\u0004 \u0005[בלבד]\u0006 שעצם הבערת אש היא לדעתו רק לאו, אבל","\u0003הבערה\u0004 של \u0003בית דין\u0004 למי שחייב מיתה בשריפה הלא \u0003בישול פתילה הוא,\u0004 שיש בו גם מלאכת בישול חוץ מההבערה, שמיתת שריפה נעשית כאשר מתיכים (\"מבשלים\") חתיכת עופרת (\"פתילה\") ואחר כך יוצקים אותה לתוך פיו של הנידון.","\u0003ואמר רב ששת\u0004 על כך: \u0003מה לי בישול פתילה\u0004 שעושים במיתת בית דין, \u0003ומה לי בישול סמנין\u0004 (סממנים, לצבע ולשמן) שעשו אותו במשכן, שממנו למדנו את הגדרת המלאכה לגבי איסורי שבת. וכיון שיש במיתת בית דין מלאכת בישול גמורה (שלכל הדעות חייבים עליה כרת), הרי מזה לכאורה ראיה שלולא הכתוב המיוחד האוסר זאת היינו אומרים שמצות עשה דוחה אף לא תעשה שיש בו כרת.","אף טענה זו נדחית, \u0003אמר רב שימי בר אשי: האי תנא\u0004 \u0005[תנא זה]\u0006 \u0003לא משום דאתי\u0004 \u0005[שבאה]\u0006 מצות \u0003עשה ודחי\u0004 \u0005[ודוחה]\u0006 את מצות \u0003לא תעשה\u0004 הוא מעלה את האפשרות שמיתת בית דין תדחה שבת, \u0003אלא משום דמייתי\u0004 \u0005[שמביא,\u0006 מעלה את הלימוד\u0005]\u0006 \u0003מקל וחומר. והכי קאמר\u0004 \u0005[וכך אמר]\u0006 באופן הבא: \u0003מה אני מקיים\u0004 את דברי הכתוב \u0003\"מחלליה מות יומת\"\u0004 — \u0003בשאר מלאכות, חוץ ממיתת בית דין. אבל\u0004 אפשר לומר כי \u0003מיתת בית דין דחיא\u0004 \u0005[דוחה]\u0006 \u0003שבת מקל וחומר,\u0004"],["\u0003ומה עבודה,\u0004 עבודת המקדש והקרבנות, \u0003שהיא חמורה\u0004 עד כדי כך שהיא \u0003דוחה שבת,\u0004 שהרי מקריבים קרבנות גם בשבת, ובכל אופן \u0003רציחה דוחה אותה,\u0004 שכהן שרצח ונידון למיתה ורוצה לעבוד עבודה, בית הדין שולחים ומביאים אותו למות, והחובה להמיתו דוחה את העבודה, \u0003שנאמר\u0004 עליו: \u0003\"מעם מזבחי תקחנו למות\"\u0004 (שמות כא, יד), \u0003שבת שנדחת מפני עבודה, אינו דין\u0004 וכי אין זה קל וחומר \u0003שתהא רציחה דוחה אותה?\u0004","ובהמשך לקו־מחשבה זה: \u0003ומאי\u0004 \u0005[ומה]\u0006 ענין הביטוי \u0003\"או אינו\"\u0004 (\"או אינו אלא בחול ולא בשבת\") \u0003דקאמר\u0004 \u0005[שאמר]\u0006 התנא בדיון — \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 שאפשר לדחות ולומר: \u0003קבורת מת מצוה,\u0004 החובה לקבור מת שאין לו מי שיקברנו, \u0003תוכיח\u0004 שלא דנים את הקל וחומר, שאנו יודעים \u0003ש\u0004היא \u0003דוחה את העבודה, ו\u0004בכל זאת \u0003אין\u0004 היא \u0003דוחה את השבת. הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר\u0004 אותו תנא, בנימוקים הרמוזים בתוך הדיון שלו: הרי אפשר גם לומר כי \u0003קבורת מת מצוה תדחה שבת מ\u0004אותו \u0003קל וחומר: ומה עבודה שהיא דוחה\u0004 את ה\u0003שבת — קבורת מת מצוה דוחה אותה,\u0004","ואנו למדים זאת \u0003מ\u0004ייתור המלה \u0003\"ולאחותו\"\u0004 האמור בנזיר (\"לאביו ולאמו לאחיו ולאחותו לא יטמא להם במותם\". במדבר ו, ז) ומכאן למדו שאפילו נזיר והולך לשחוט קרבן פסח חייב להיטמא למת מצוה, אם כן \u0003שבת שנדחה מפני עבודה — אינו דין שתהא קבורת מת מצוה דוחה אותה?\u0004 על כן \u0003תלמוד לומר: \"לא תבערו\u0004 אש בכל מושבותיכם ביום השבת\u0003\"\u0004 (שמות לה, ג).","ושואלים: \u0003ולמאי דסליק אדעתיה מעיקרא\u0004 \u0005[ול\u0006פי \u0005מה שעלה על דעתו\u0006 של המקשה \u0005מתחילה]\u0006 שהנימוק הוא \u0003דאתי\u0004 \u0005[שבאה]\u0006 מצות \u0003עשה ודחי\u0004 \u0005[ודוחה]\u0006 \u0003לא תעשה, מאי\u0004 \u0005[מה]\u0006 עניינו ומה תוכנו של \u0003\"או אינו\" דקאמר\u0004 \u0005[שאומר]\u0006 התנא?","ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 זו היתה הכוונה: שאפשר היה לומר \u0003מה אני מקיים\u0004 את דברי הכתוב \u0003\"מחלליה מות יומת\"\u0004 (שם לא, יד) — \u0003בשאר מלאכות, חוץ ממיתת בית דין. אבל מיתת בית דין דחי\u0004 \u0005[דוחה]\u0006 את ה\u0003שבת,\u0004 משום \u0003דאתי\u0004 \u0005[שבאה]\u0006 מצות \u0003עשה ודחי\u0004 \u0005[ודוחה]\u0006 \u0003לא תעשה.\u0004","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר\u0004 כנגד טענה זאת טענה אחרת: \u0003אימר דאמרינן\u0004 \u0005[אמור שאנו אומרים]\u0006 בכלל \u0003דאתי\u0004 \u0005[שבאה]\u0006 מצות \u0003עשה ודחי\u0004 \u0005[ודוחה]\u0006 את \u0003לא תעשה,\u0004 הרי זה דווקא \u0003לא תעשה גרידא\u0004 \u0005[סתם],\u0006 אבל \u0003לא תעשה שיש בו כרת — מי שמעת ליה דדחי\u0004 \u0005[האם שמעת אותו ש\u0006הוא \u0005דוחה]?\u0006 \u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר\u0004 התנא, ורמז לנימוק נגדי: \u0003אטו\u0004 \u0005[וכי]\u0006 כלל זה ש\u0003\"עשה דוחה את לא תעשה\", לאו\u0004 \u0005[האם לא]\u0006 ה\u0003לא תעשה חמור מיניה\u0004 \u0005[ממנו,\u0006 מן העשה\u0005]?\u0006 שהרי על מצוות לא תעשה יש עונש מלקות בית דין, מה שאין במצוות עשה, \u0003ו\u0004בכל זאת, \u0003קאתי\u0004 \u0005[באה]\u0006 מצות \u0003עשה ודחי ליה\u0004 \u0005[ודוחה אותו],\u0006 שגזירת הכתוב היא שעשה דוחה את לא תעשה, ואם כן","\u0003מה לי חומרא זוטא\u0004 \u0005[קטנה]\u0006 \u0003ומה לי חומרא רבה\u0004 \u0005[גדולה],\u0006 שכיון שאמרה התורה שמצות עשה דוחה את מצות לא תעשה אין כבר הבדל אם זו מצות לא תעשה חמורה או קלה, לכן \u0003תלמוד לומר \"לא תבערו\".\u0004 ואם כן, בסופו של דבר לא הבאנו עדיין מקור ברור לסברה שעשה דוחה לא תעשה שיש בו כרת.","ולכן באים לדון באופן אחר: ייתור המלה \"עליה\" באה ללמד שלא ידחה הייבום את איסורי העריות, \u0003אלא אצטריך\u0004 \u0005[הוצרכה]\u0006 המלה \"עליה\", כי \u0003סלקא דעתך אמינא\u0004 \u0005[עולה על דעתך לומר]\u0006 כך: \u0003תיהוי האי\u0004 \u0005[תהיה זאת]\u0006 \u0003אשת אח\u0004 שעליה חלה מצות הייבום, \u0003דבר שהיה בכלל ויצא מן הכלל\u0004 כדי \u0003ללמד,\u0004 ונדון ממנה לפי כלל זה של מדרש ההלכה האומר כי דבר שהיה בתוך כלל מסויים, ונאמר בו דין מסויים, \u0003לא ללמד על עצמו\u0004 בלבד \u0003יצא אלא ללמד על הכלל כולו יצא.\u0004 וכיון שאיסור אשת אח הוא בכלל איסורי העריות (\"כי כל העושה מכל התועבות האלה ונכרתו הנפשות העושות מקרב עמם\". ויקרא יח, כט), נאמר אם כן כי דין הייבום מתיר לא רק איסור ערוות אשת אחיו שאין לו בנים, אלא גם את שאר העריות.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בהסבר עיקרה של מידה זו שהתורה נדרשת בה: \u0003דבר שהיה בכלל ויצא מן הכלל\u0004 כדי ללמד — לא ללמד על עצמו בלבד יצא, אלא ללמד על הכלל כולו יצא. \u0003כיצד?\u0004","דוגמה ללימוד זה, ממה שנאמר: \u0003\"והנפש אשר תאכל בשר מזבח השלמים\u0004 אשר לה' \u0003וטמאתו עליו\u0004 ונכרתה הנפש ההיא מעמיה\u0003\"\u0004 (ויקרא ז, כ). ולכאורה נשאלת השאלה: \u0003והלא שלמים בכלל\u0004 כל \u0003קדשים היו, ולמה יצאו\u0004 מן הכלל ונתפרטו במיוחד — \u0003להקיש\u0004 (להשוות) \u0003אליהן, ולומר לך: מה שלמים מיוחדים\u0004 שהם \u0003קדשי מזבח — אף כל קדשי מזבח\u0004 יש בהם דין זה, שהאוכל מהם בטומאה חייב כרת. ולמדנו מכאן ש\u0003יצאו קדשי בדק הבית\u0004 שהם מוקדשים לצורך המקדש אבל אינם קרבנות, שבהם אין חיוב אם אוכלם או נוגע בהם בטומאה.","\u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אפשר לומר כך: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אשת אח בכלל כל העריות היתה, ולמה יצתה\u0004 מכללן — \u0003להקיש אליה, ולומר לך: מה אשת אח שריא\u0004 \u0005[מותרת]\u0006 במקום שאין לו בנים, \u0003אף כל עריות\u0004 כולן \u0003נמי שריין\u0004 \u0005[גם כן מותרות].\u0006","ודוחים: \u0003מי דמי\u0004 \u0005[האם\u0006 זה \u0005דומה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 במקרה שהובא כדוגמה למידה זו, ה\u0003כלל,\u0004 כל הקרבנות כולם, הם \u0003באיסור\u0004 טומאה, \u0003ו\u0004אף ה\u0003פרט,\u0004 השלמים, הם \u0003באיסור,\u0004 ולכן אפשר לומר שהפרט יצא ונתפרט כדי ללמד על הכלל כולו. אבל \u0003הכא\u0004 \u0005[כאן]\u0006 לגבי ייבום בעריות, הלא ה\u0003כלל\u0004 הוא \u0003באיסור\u0004 ערוה, \u0003ו\u0004ה\u0003פרט\u0004 הוא \u0003בהיתר.\u0004","והפרט איננו יוצא איפוא לפרש את הכלל, אלא הוא כנגד הכלל, \u0003הא לא דמי\u0004 \u0005[הרי\u0006 מקרה \u0005זה איננו דומה]\u0006 \u0003אלא\u0004 למידה אחרת שהתורה נדרשת בה: \u0003לדבר שהיה בכלל ויצא לידון בדבר החדש,\u0004 שאם יש פרט מתוך כלל גדול יותר, שנתפרשה בו מצוה חדשה, או דין חדש מיוחד — \u0003שאי אתה יכול להחזירו לכללו\u0004 אף לשאר עניינים, ואפשר לומר שבעצם אינו שייך לכלל זה, \u0003עד שיחזירנו לך הכתוב בפירוש\u0004 לגבי שאר דינים. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 באותו ענין: \u0003דבר שהיה בכלל ויצא לידון בדבר החדש — אי אתה רשאי להחזירו לכללו, עד שיחזירנו לך הכתוב בפירוש.\u0004","\u0003כיצד?\u0004 דוגמא לדבר ממה שנאמר בדין אשם המצורע: \u0003\"ושחט את הכבש במקום אשר ישחט את החטאת ואת העלה במקום הקדש כי כחטאת האשם הוא לכהן\"\u0004 (שם יד, יג), \u0003שאין תלמוד לומר \"כחטאת האשם\",\u0004 שלכאורה אין דימוי זה לחטאת מלמדנו דבר, שהרי דיני האשם כולם נתפרשו לנו במקומם (שם ז, א-י) \u0003ומה תלמוד לומר,\u0004 מה הלימוד במילים \u0003\"כחטאת האשם\"?\u0004","\u0003לפי שיצא אשם מצורע\u0004 מכלל כל הקרבנות (ומכלל האשמות) \u0003לידון בדבר החדש,\u0004 שנותנים את דמו על \u0003בהן יד ובהן רגל הימנית\u0004 של המצורע. אם כן, \u0003יכול לא יהא\u0004 אשם זה \u0003טעון מתן דמים\u0004 (זריקת דם על המזבח) \u0003ו\u0004מתן \u0003אימורים\u0004 (חלב ושאר החלקים המוקרבים) \u0003לגבי מזבח,\u0004 ונאמר שדי באשם זה רק במתן הדם על בהונות המצורע בלבד —"],["\u0003תלמוד לומר: \"כי כחטאת האשם הוא\"\u0004 (ויקרא יד, יג), ללמד: \u0003מה חטאת טעונה מתן דמים ואימורים לגבי מזבח — אף אשם\u0004 מצורע \u0003טעון מתן דמים ואימורים לגבי מזבח.\u0004","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא אהדריה קרא\u0004 \u0005[\u0006היה \u0005מחזיר אותו הכתוב],\u0006 כלומר, אם לא היה לימוד מיוחד שיחזיר את האשם לכללו — \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003למאי דנפק\u0004 \u0005[למה שיצא\u0006 וחודש בו\u0005] —\u0006 \u0003נפק\u0004 \u0005[יצא],\u0006 \u0003ולמאי דלא נפק\u0004 \u0005[ולמה שלא יצא] —\u0006 \u0003לא נפק\u0004 \u0005[יצא]\u0006 והיה דינו שונה. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003אשת אח דאישתרא\u0004 \u0005[שהותרה] —\u0006 \u0003אישתראי\u0004 \u0005[הותרה],\u0006 אולם \u0003שאר עריות לא\u0004 הותרו כלל. ואם כן, אין להביא מכאן כל ראיה להיתר כללי.","\u0003אלא\u0004 יש לומר באופן אחר, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כך: \u0003תיתי\u0004 \u0005[תבוא,\u0006 תילמד\u0005]\u0006 סברה זו \u0003ב\u0004דרך הלימוד של \u0003\"מה מצינו\"\u0004 (שהוא לימוד בדרך השוואה של פרט אחד לפרט אחר הדומה לו), \u0003מאשת אח.\u0004 ונאמר: \u0003מה אשת אח מייבמה\u0004 \u0005[מתייבמת]\u0006 \u0003אף אחות אשה\u0004 שהיתה נשואה לאחיו, \u0003תתייבם\u0004 לו.","ותוהים: \u0003מי דמי\u0004 \u0005[האם דומה\u0006 הדבר\u0005]?\u0006 איך אפשר ללמוד זה מזה? \u0003התם\u0004 \u0005[שם]\u0006 בהיתר היבמה \u0003חד איסורא\u0004 \u0005[איסור אחד]\u0006 בלבד הוא שהותר — איסור אשת אח, \u0003הכא\u0004 \u0005[כאן]\u0006 באחות אשתו \u0003תרי איסורי\u0004 \u0005[שני איסורים]\u0006 הם, גם איסור אשת אח, וגם איסור אחות אשה! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הואיל ואישתרי\u0004 \u0005[והותר]\u0006 \u0003— אישתרי\u0004 \u0005[הותר],\u0006 שכיון שהתירה התורה איסור אשת אח כשיש ייבום, הותר הדבר גם אם היה שם נוסף לכך גם איסור אחות אשה.","\u0003ומנא תימרא דאמרינן\u0004 \u0005[ומנין תאמר שאנו אומרים]\u0006 נימוק זה של \u0003הואיל ואישתרי\u0004 \u0005[והותר]\u0006 \u0003אישתרי\u0004 \u0005[הותר] —\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מצורע שחל\u0004 יום \u0003שמיני שלו,\u0004 שבו הוא נטהר מצרעתו, ומביא את קרבנותיו האחרונים למקדש, \u0003בערב פסח, ו\u0004אירע לו ש\u0003ראה קרי בו ביום,\u0004 ביום השמיני, \u0003וטבל, אמרו חכמים: אף על פי שאין טבול יום אחר\u0004 (מי שטבל כדי להיטהר מטומאתו ועדיין לא העריבה השמש) \u0003נכנס\u0004 למקדש להקריב, אבל \u0003זה\u0004 המצורע שראה קרי וטבל — \u0003נכנס\u0004.","והטעם: \u0003מוטב שיבא עשה שיש בו כרת\u0004 של הקרבת קרבן פסח בזמנו, \u0003וידחה עשה שאין בו כרת\u0004 של כניסת טמא למקדש. שאם לא יטהר מצרעתו לא יוכל להקריבו. \u0003ואמר ר' יוחנן:\u0004 לאמיתו של דבר, לפי \u0003דבר תורה אפילו\u0004 איסור \u0003עשה לית ביה\u0004 \u0005[אין בו]\u0006 בטבול יום שנכנס למקדש,","\u0003שנאמר: \"ויעמד יהושפט בקהל יהודה\u0004 וירושלים בבית ה' \u0003לפני החצר החדשה\"\u0004 (דברי הימים ב' כ, ב). ואמרו: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"חצר החדשה\"? אמר ר' יוחנן: שחדשו בה דברים, ואמרו\u0004 גזירה חדשה: \u0003טבול יום לא יכנס למחנה לויה\u0004 שבארץ ישראל, הוא הר הבית (אף שמדין תורה אין איסור בדבר).","\u0003ו\u0004לגופה של הלכה זו שמצורע שראה קרי ביום השמיני לטהרתו שהוא ערב פסח יכול מיד לאחר שטובל להקריב את קרבן פסח ואינו צריך להמתין להערב שמש, \u0003אמר עולא: מה טעם\u0004 התירו לו — \u0003הואיל והותר לצרעתו,\u0004 שהרי התורה התירה לו להיכנס להר הבית ולמקדש בעודו מצורע, שהרי לא נטהר לגמרי עד לאחר הבאת הקרבן, והתורה התירה לו לבוא למקדש ולהיטהר — \u0003הותר\u0004 גם כן \u0003לקרויו\u0004 (לכאשר הוא בעל קרי). הרי שאנו אומרים: הואיל והותר איסור אחד, אפשר להתיר לו גם שני איסורים. את הראיה הזו דוחים: \u0003מי דמי\u0004 \u0005[האם דומה]\u0006 הנחה זו שהנחנו \u0003ל\u0004דבריו של \u0003עולא\u0004"],["\u0003תינח\u0004 \u0005[נניח]\u0006 \u0003היכא\u0004 \u0005[היכן,\u0006 כאשר\u0005]\u0006 \u0003נשא מת ואחר כך נשא חי,\u0004 שהאח שמת נשא קודם אחת מן האחיות ונאסרה על אחיו (היבם) איפוא משום אשת אח, ואחר כך נשא אחיו את אחותה, וחזרה ונאסרה משום אחות אשה. ואז אפשר לומר \u0003דמגו דאישתרי\u0004 \u0005[שמתוך שהותר]\u0006 ה\u0003איסור\u0004 הראשון של \u0003אשת אח\u0004 בשל מצות הייבום — \u0003אישתרי נמי\u0004 \u0005[הותר גם כן]\u0006 \u0003איסור אחות אשה.\u0004","\u0003אלא,\u0004 אם היה זה מקרה אחר, שקודם \u0003נשא\u0004 האח ה\u0003חי\u0004 את אשתו, \u0003ואחר כך נשא\u0004 האח ש\u0003מת\u0004 את אחותה, נמצא ש\u0003איסור אחות אשה קדים\u0004 \u0005[קדם]\u0006 וחל עליו, שהרי תחילה היתה אותה אשה אסורה עליו משום שהיא אחות אשתו, וכשנשאה אחיו חל עליה איסור נוסף, שהיא גם אשת האח, ואז, גם כאשר הותר האיסור השני במות האח בלי בנים, האיסור הראשון נשאר במקומו.","\u0003ו\u0004עוד: \u0003אפילו\u0004 במקרה ש\u0003נשא\u0004 האח ה\u0003מת\u0004 תחילה את אחת האחיות \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003תינח היכא\u0004 \u0005[נניח, היכן\u0006 כאשר\u0005]\u0006 \u0003נשא\u0004 האח ש\u0003מת\u0004 את האשה \u0003ומת, ואחר כך נשא חי\u0004 את אחותה, שאפשר היה לומר שאשת האח המת \u0003חזיא ליה דביני ביני\u0004 \u0005[ראויה לו בינתים],\u0006 שהרי לפני שנשא את אחותה, היתה אשת אחיו המת מותרת לו משום מצות ייבום, ואז אפשר היה לומר שלא יחול עליו גם האיסור השני. \u0003אלא\u0004 אם \u0003נשא\u0004 האח ש\u0003מת\u0004 תחילה, \u0003ולא מת\u0004 עדיין, \u0003ואחר כך\u0004 עוד בחייו \u0003נשא\u0004 האח ה\u0003חי\u0004 את אחותה, אם כן \u0003לא איחזיא\u0004 \u0005[נראתה],\u0006 לא נעשתה ראויה \u0003ליה\u0004 \u0005[לו]\u0006 \u0003כלל,\u0004 שהרי לא היה פרק זמן כלשהו שבו היתה מותרת לו, וראיה לשיקול זה:","\u0003מי\u0004 \u0005[האם]\u0006 \u0003לא מודי\u0004 \u0005[מודה]\u0006 \u0003עולא שאם ראה\u0004 המצורע \u0003קרי בליל שמיני,\u0004 לא ביום השמיני עצמו אלא בלילה שלפניו, \u0003שאין מכניס ידיו לבהונות,\u0004 שצריך להכניסן כדי שיתנו עליהם דם ושמן ויטהרו אותו, ואינו מכניסן משום שהוא טמא טומאת קרי, \u0003שלא יצא\u0004 עדיין מטומאת הצרעת \u0003בשעה שהיא ראויה להביא בה קרבן,\u0004 שהרי לא היה עדיין זמן שהיה אותו אדם ראוי להביא קרבן ולצאת מצרעתו, משום שעוד בליל שמיני, לפני שהגיע הזמן להקריב קרבן (בשעות היום ביום השמיני), היה כבר טמא טומאה אחרת, וכיון שלא הותר לו להיכנס למקדש בטומאה אפילו שעה אחת, אין אומרים שיקול זה של \"הואיל והותר הותר\". ואם כן, אף כאן אין חיזוק לסברה להתיר איסור ערוה ליבם.","\u0003אלא\u0004 יש לתקן מעט את הדברים שאמרנו, ולהבינם כך: \u0003כי איצטריך\u0004 \u0005[כאשר נצרכה]\u0006 המלה \u0003\"עליה\"\u0004 שממנה למדנו איסור אחות אשתו בייבום — הרי זה \u0003היכא\u0004 \u0005[היכן,\u0006 כאשר\u0005]\u0006 \u0003נשא\u0004 תחילה האח ש\u0003מת, ומת, ואחר כך נשא\u0004 האח ה\u0003חי\u0004 את אחותה, שאז היתה אשת אחיו מותרת לו שעה אחת, ואפשר היה לומר כיון שהותרה הותרה, ולכן צריך היה לכתוב \"עליה\" כדי לאוסרה.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שההנחה שאפשר לייבם גם כשיש איסור ערוה \u0003אתיא בהיקישא\u0004 \u0005[\u0006היתה \u0005באה\u0006 מכוח \u0005ההיקש]\u0006 של \u0003ר' יונה.\u0004 ש\u0003אמר ר' יונה, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כי כל אשר יעשה מכל התועבת האלה ונכרתו\"\u0004 (ויקרא יח, כט), באותו פסוק \u0003הוקשו\u0004 (הושוו) \u0003כל העריות כולן לאשת אח,\u0004 ולכן היינו יכולים לומר: \u0003מה אשת אח שריא\u0004 \u0005[מותרת]\u0006 לייבום, \u0003אף כל עריות נמי שריין\u0004 \u0005[גם כן מותרות],\u0006 על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"עליה\".\u0004","כנגד ראיה זו \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא: מכדי\u0004 \u0005[הרי]\u0006 \u0003כל\u0004 ה\u0003עריות איכא לאקושינהו\u0004 \u0005[יש\u0006 מקום \u0005להשוות אותן]\u0006 \u0003לאשת אח\u0004 ולהתירן לייבום \u0003ואיכא לאקושינהו\u0004 \u0005[ויש\u0006 מקום \u0005להשוות אותן]\u0006 \u0003לאחות אשה\u0004 ולאסור, \u0003מאי חזית דאקשת\u0004 \u0005[מה ראית שהקשת,\u0006 השווית אותן\u0005]\u0006 \u0003לאחות אשה? אקשינהו\u0004 \u0005[הקש אותן]\u0006 \u0003לאשת אח!\u0004 ושמא נאמר שמן ההדגשה \"עליה\" לא נלמד מאחות אשה ולאסור בכל מקרה, אלא להיפך: מ\"עליה\" שנאמר בייבום נלמד שהייבום מותר אפילו באחות אשה, וכן בכל העריות!","ומתרצים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 טעם זה: אם יש לבחור בין שתי אפשרויות להבין משמעותו של היקש האחת \u0003לקולא\u0004 \u0005[להקל]\u0006 והאחרת \u0003לחומרא\u0004 \u0005[להחמיר] —\u0006 \u0003לחומרא מקשינן\u0004 \u0005[להחמיר אנחנו משווים]\u0006 ולא להקל. \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 טעם זה: \u0003הכא תרי איסורי\u0004 \u0005[כאן\u0006 יש \u0005שני איסורים],\u0006 איסור אשת אח ואיסור אחות אשה, \u0003והכא תרי איסורי\u0004 \u0005[וכאן\u0006 בשאר עריות יש \u0005שני איסורים]\u0006 \u0003ותרי מתרי ילפינן\u0004 \u0005[ושנים משנים אנו למדים]\u0006 \u0003אבל הכא חדא איסורא\u0004 \u0005[כאן,\u0006 בייבום רגיל, יש רק \u0005איסור אחד]\u0006 של אשת אח, \u0003ותרי מחדא לא ילפינן\u0004 \u0005[ושנים מאחד אין אנו למדים].\u0006","\u0003רבא אמר:\u0004 מעיקרו של דבר יש לפרש את מדרש ההלכה בדרך אחרת: \u0003ערוה\u0004 עצמה \u0003לא צריכא קרא\u0004 \u0005[אינה צריכה כתוב]\u0006 כדי ללמד שאין לייבם אותה, משום \u0003שאין\u0004 מצות \u0003עשה דוחה\u0004 את \u0003לא תעשה שיש בו כרת.\u0004 אלא, \u0003כי איצטריך קרא\u0004 \u0005[כאשר נצרך הכתוב]\u0006 הרי זה \u0003למיסר\u0004 \u0005[לאסור]\u0006 את ה\u0003צרה,\u0004 מאחר שהצרה איננה אסורה על היבם משום ערוה, והייתור \"עליה\" לא נאמר אלא כדי לאסור את הצרה.","ושואלים: \u0003ו\u0004כי סבור התנא כי \u0003ערוה לא צריכא קרא\u0004 \u0005[איננה צריכה כתוב]?\u0006 \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 באותה ברייתא\u0005]:\u0006 \u0003אין לי אלא היא,\u0004 צרתה מניין? ומשמע שגם לגבי הערוה עצמה צריך לימוד!","ומשיבים: \u0003משום צרתה,\u0004 מה שאמרו \"אין לי אלא היא\" לא נלמד ממקרא זה, ולא נאמר אלא כדי לקשור לאותו ענין את הצרה.","ומקשים עוד: \u0003והא קתני\u0004 \u0005[והרי שנה]\u0006 בברייתא: \u0003אין לי אלא הן\u0004 האחיות הפטורות מן הייבום, משמע שהלימוד הוא ביחס להן! ודוחים שוב: אף כאן לא אמרו זאת אלא \u0003משום צרותיהן.\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה לסתור את דברי רבא מברייתא אחרת: \u0003רבי אומר\u0004 ראיה אחרת לענין זה של איסור ערוה וצרה, נאמר בכתוב: \"ולקחה לו לאשה וייבמה\" (דברים כה, ה), כיון שלא נאמר \u0003\"ולקח\"\u0004 אלא \u0003\"ולקחה\"\u0004 משמע לקח אותה דווקא, לצמצם: זו ולא אחרת שיש בה איסור, וכן לא נאמר \u0003\"ויבם\"\u0004 סתם אלא \u0003\"ויבמה\"\u0004 = ייבם אותה, לומר: את זו ולא אחרת, הרי זה בא \u0003לאסור צרות ועריות.\u0004 ומכאן אנו למדים שאף איסור עריות צריך לימוד מיוחד!","ומתרצים: \u0003אימא\u0004 \u0005[אמור]\u0006 בתיקון לשון קצת: \u0003לאסור צרות של עריות,\u0004 ולא עריות עצמן. ומקשים: \u0003והא תרי קראי קנסיב ליה\u0004 \u0005[והרי שני פסוקים הביא לו]\u0006 לראיה, \"ולקחה\" \"ויבמה\", \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 משום שצריך \u0003חד\u0004 \u0005[\u0006פסוק \u0005אחד]\u0006 ללמד \u0003ל\u0004גבי \u0003ערוה וחד\u0004 \u0005[\u0006ופסוק \u0005אחד]\u0006 ללמד \u0003ל\u0004גבי \u0003צרה?\u0004","ודוחים: \u0003לא, אידי ואידי\u0004 \u0005[זה וזה],\u0006 שני הפסוקים ללמד \u0003ל\u0004גבי \u0003צרה\u0004 באו, וצריכים שני פסוקים מטעם זה: \u0003חד למיסר\u0004 \u0005[אחד\u0006 מהם בא \u0005לאסור]\u0006 \u0003צרה במקום מצוה,\u0004 לומר שצרת ערוה במקום שבו קיימת מצות ייבום — אסורה עליו. \u0003וחד למישרי\u0004 \u0005[ואחד להתיר]\u0006 \u0003צרה שלא במקום מצוה.\u0004 שאם אשה היא צרה לאחת העריות האסורות על אדם — רשאי הוא לשאת אותה לאחר מות בעלה, שאין איסור זה של צרת ערוה אלא במקום שחלה מצות ייבום, כלומר, באשת אח.","\u0003מאי טעמא\u0004 \u0005[\u0006ו\u0005מה טעם\u0006 הדבר\u0005] —\u0006 כך הוא דקדוק לשון הפסוק, שהיה יכול לכתוב: \u0003\"ויבם\"\u0004 וכתב בהדגשה \u0003\"ויבמה\"\u0004 — משמע: \u0003במקום ייבום הוא דאסירא\u0004 \u0005[שאסורה]\u0006 \u0003צרה, שלא במקום ייבום — שריא\u0004 \u0005[מותרת]\u0006 \u0003צרה.\u0004","\u0003אמר רב אשי: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת],\u0006 אם מדקדקים בלשונה, כשיטה זו של רבא. \u0003דקתני\u0004 \u0005[ששנה]\u0006 בה: \u0003חמש עשרה נשים פוטרות צרותיהן. ואילו \"פטורות ופוטרות\" לא קתני\u0004 \u0005[שנה],\u0006 משמע שעצם פטורן של הנשים שהן עריות אינו צריך ללימוד מיוחד, כי אין בו חידוש, ועיקר החידוש הוא בכך שהן פוטרות את צרותיהן, ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ושואלים: אם כך, \u0003ומאי שנא\u0004 \u0005[ומה שונה,\u0006 מדוע דווקא\u0005]\u0006 \u0003ערוה דלא צריכא קרא\u0004 \u0005[שאיננה צריכה כתוב\u0006 מיוחד\u0005] —\u0006 משום הנימוק שאמרת ש\u0003אין עשה דוחה\u0004 את \u0003לא תעשה שיש בו כרת,\u0004 אם כן \u0003צרה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא תיבעי קרא\u0004 \u0005[תצטרך כתוב]\u0006 נוסף \u0003משום\u0004 אותו טעם — ש\u0003אין עשה דוחה\u0004 את \u0003לא תעשה שיש בו כרת,\u0004 שהרי מלשון הכתוב \"לצרור\" למדים אנחנו שצרת אחות אשה אסורה כמו אחות אשה עצמה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בר ביבי מר לרבינא: הכי קאמרינן משמיה\u0004 \u0005[כך אומרים אנחנו משמו]\u0006 של \u0003רבא:\u0004 בשביל \u0003צרה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא איצטריך קרא\u0004 \u0005[נצרך כתוב]\u0006 וכפי שאמרנו בערוה עצמה, שהרי גם בה יש כרת, ואין עשה של ייבום דוחה אותה. \u0003כי איצטריך קרא\u0004 \u0005[כאשר נצרך הכתוב]\u0006"],["\u0003למישרי\u0004 \u0005[להתיר]\u0006 \u0003צרה שלא במקום מצוה. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר, כלומר, איך אנחנו לומדים דבר זה — \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"עליה\",\u0004 לומר: \u0003במקום \"עליה\",\u0004 במקום שחל חיוב של \"יבמה יבוא עליה\", \u0003הוא דאסירא\u0004 \u0005[שאסורה]\u0006 הצרה, אבל \u0003שלא במקום \"עליה\",\u0004 כשאין מצות \"יבמה יבא עליה\" — \u0003שריא\u0004 \u0005[מותרת]\u0006 הצרה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רמי בר חמא לרבא:\u0004 אם מפרשים את \"עליה\", הכתוב בדין אחות אשה, רק במקום ייבום, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003ערוה גופה\u0004 \u0005[עצמה]\u0006 \u0003שלא במקום מצוה תישתרי\u0004 \u0005[תהיה מותרת],\u0006 ונפרש שכל איסורי העריות נאמרו רק במקום ייבום! אמר לו רבא: \u0003ולאו\u0004 \u0005[והאם לא]\u0006 \u0003קל וחומר הוא?\u0004 אם \u0003במקום מצוה אסירא\u0004 \u0005[אסורה]\u0006 הערוה — \u0003שלא במקום מצוה שריא\u0004 \u0005[\u0006תהיה \u0005מותרת]?!\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 זו איננה הוכחה, שהרי \u0003צרה\u0004 עצמה \u0003תוכיח,\u0004 שאין משתמשים בקל וחומר זה, שהרי \u0003במקום מצוה אסירא\u0004 \u0005[\u0006היא \u0005אסורה]\u0006 \u0003ושלא במקום מצוה שריא\u0004 \u0005[\u0006היא \u0005מותרת]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לרמי בר חמא: \u0003עליך\u0004 כלומר, כנגד טענה זו \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"\u0004לגלות ערותה עליה \u0003בחייה\"\u0004 (ויקרא יח, יח), לומר: \u0003כל שבחייה\u0004 היא ערוה לו — הריהי אסורה, גם שלא במקום מצוה.","ומקשים: \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"בחייה\" מיבעי ליה למעוטי\u0004 \u0005[צריך אותו\u0006 כפשוטו \u0005למעט]\u0006 \u0003לאחר מיתה,\u0004 שאחות אשה אסורה רק כאשר האחות שהיתה נשואה לו חיה עדיין, אבל לאחר מיתתה מותרת לו האחות! ומשיבים: ההלכה \u0003ההיא\u0004 שמותרת לאחר מיתה \u0003מ\"ואשה אל אחתה\u0004 לא תקח\u0003\"\u0004 (שם) \u0003נפקא\u0004 \u0005[יוצא]\u0006 הדבר, כי כאשר אחת מהן מתה שוב אין כאן \"אשה אל אחותה\".","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003מ\"ואשה אל אחתה\" הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 אף אם \u0003נתגרשה שריא\u0004 \u0005[מותרת],\u0006 על כן \u0003תלמוד לומר: \"בחייה\" — כל שבחייה, דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003נתגרשה,\u0004 היא \u0003לא\u0004 מותרת כל זמן שהיא בחייה!","\u0003אלא אמר רב הונא בר תחליפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא,\u0004 יש לומר באופן שונה: \u0003תרי קראי כתיבי\u0004 \u0005[שני כתובים נאמרו],\u0006 כלומר, בכתוב נזכרים שני עניינים נבדלים: \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"אשה אל אחתה לא תקח לצרר\"\u0004 (שם), ומלשון הכתוב יוצא ששתי הנשים (הצרות) אסורות, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"לגלות ערותה\",\u0004 בלשון יחיד \u0003דחדא\u0004 \u0005[ש\u0006ב\u0005אחת]\u0006 \u0003משמע\u0004 שדיבר הכתוב, ולא בשתיהן. \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 ניישב סתירה זו? — \u0003במקום מצוה\u0004 של ייבום \u0003שתיהן אסורות\u0004 גם הערוה וגם הצרה, ו\u0003שלא במקום מצוה — היא אסורה וצרתה מותרת.\u0004","ומקשים: \u0003איפוך אנא\u0004 \u0005[אהפוך אני]\u0006 ואומר להיפך: \u0003במקום מצוה — היא אסורה וצרתה מותרת, ושלא במקום מצוה שתיהן אסורות.\u0004 ומשיבים: \u0003אם כן לא יאמר\u0004 כלל \u0003\"עליה\",\u0004 שהמלה היתירה \"עליה\" באה ללמד כי האיסור של צרה הוא רק במקום של \"יבמה יבוא עליה\".","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב כהנא: ממאי דהאי\u0004 \u0005[ממה,\u0006 מניין, יודעים אנו שמלה \u0005זו]\u0006 \u0003\"עליה\"\u0004 באה \u0003לאיסורא\u0004 \u0005[לאיסור]\u0006 וכוונתה אף על פי שיש חובה של \"יבמה יבוא עליה\" מכל מקום אחות אשה אסורה, \u0003דלמא להתירא\u0004 \u0005[שמא להיתר]\u0006 היא באה, \u0003והכי קאמר רחמנא\u0004 \u0005[וכך אמרה,\u0006 נתכוונה, \u0005התורה]:\u0006 \u0003\"אשה אל אחתה לא תקח לצרר\"\u0004 משמע: \u0003לא היא ולא צרתה,\u0004 אימתי — \u0003שלא במקום \"עליה\",\u0004 כאשר אין חיוב של \"יבמה יבוא עליה\", \u0003אבל במקום \"עליה\"\u0004 שיש חובת ייבום — \u0003שתיהן מותרות.\u0004","אמר לו: \u0003אם כן \"לגלות ערוה\" דחדא היכי משכחת לה\u0004 \u0005[של אחת\u0006 מהן \u0005איך אתה מוצא]?\u0006 שהרי ממה שדיבר הכתוב בלשון יחיד נלמד שיש מקרה שרק אחת מהן אסורה, ולפי הנחה זו, \u0003אי\u0004 \u0005[אם]\u0006 \u0003במקום מצוה — הלא שתיהן מותרות, אי\u0004 \u0005[אם]\u0006 \u0003שלא במקום מצוה — הלא שתיהן אסורות?!\u0004 ועל כן יש לומר כפי שאמרנו, שצרה אסורה רק במקום מצות ייבום.","תוך בירור מדרש הכתוב מלשון \"עליה\" הוזכרה גם שיטת המדרש האחרת, של רבי, ועכשיו באים לדון בה ל\u0003גופא. רבי אומר:\u0004 לא נאמר \u0003\"ולקח\"\u0004 אלא \u0003\"ולקחה\",\u0004 לא נאמר \u0003\"ויבם\"\u0004 אלא \u0003\"ויבמה\",\u0004 הרי זה בא \u0003לאסור צרות ועריות.\u0004 ותוהים: \u0003מידי\u0004 \u0005[וכי]\u0006 \u0003\"צרות\" כתיבא הכא\u0004 \u0005[כתובות כאן]?\u0006 כלומר, מה קשר בין לשון הכתוב הזה לענין הצרות, שהרי הפסוק איננו נוגע כלל בנושא זה! \u0003ועוד:\u0004 איסור \u0003צרות מ\u0004המלה \u0003\"לצרור\" נפקא\u0004 \u0005[\u0006הוא \u0005יוצא,\u0006 נלמד\u0005]\u0006 ולא ממה שנאמר כאן!","ומשיבים: המלה \u0003\"לצרור\" מפיק ליה\u0004 \u0005[מוציא אותה]\u0006 \u0003רבי\u0004 ללמוד דבר אחר, \u0003לכ\u0004 מו שאמר \u0003ר' שמעון.\u0004 שלדעת ר' שמעון פטור שתי אחיות מייבום הוא לא רק כאשר אחת מהן נשואה לו, אלא גם אם נפלו לפניו לייבום שתי אחיות שהיו נשואות קודם לשני אחיו. שאף הזיקה לייבום מחשיבתן כאילו היו כבר צרות זו לזו. ואיסור זה נלמד מהמלה \"לצרור\", לומר שהן צרות זו לזו, אף בזיקה בלבד,","ומה ששאלנו וכי \u0003צרה הכא כתיב\u0004 \u0005[כאן כתובה]?\u0006 יש לומר שיש רמז לדבר במקרא, ו\u0003הכי קאמר\u0004 \u0005[\u0006ו\u0005כך אמר]:\u0006 \u0003אם כן\u0004 שלא לפטור את הצרות בא הכתוב, \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 רק \u0003\"ולקח\", מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ולקחה\"\u0004 — למעט: אחת ולא שתים, וכך יש להבין: ב\u0003כל\u0004 מקרה, \u0003היכא דאיכא תרי\u0004 \u0005[היכן שיש שני]\u0006 \u0003לקוחין,\u0004 כלומר, שיש לו ברירה לשאת אחת משתי הנשים שנפלו לפניו, ובאופן \u0003דאי בעי נסיב האי ואי בעי נסיב האי\u0004 \u0005[שאם רוצה נושא\u0006 את \u0005זו ואם רוצה נושא\u0006 את \u0005זו],\u0006 הרי \u0003שריא\u0004 \u0005[מותרת]\u0006 כל אחת מהן. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא,\u0004 שאין לו ברירה ויכול לשאת רק את אחת מהן, כגון שאחת מהן ערוה עליו — \u0003תרוייהו אסירין\u0004 \u0005[שתיהן אסורות],\u0006 שגם צרתה אסורה.","ומה שנאמר \u0003\"ויבמה\",\u0004 בא ללמד: \u0003במקום ייבום הוא דאסירא\u0004 \u0005[שאסורה]\u0006 \u0003צרה, שלא במקום ייבום שריא\u0004 \u0005[מותרת]\u0006 \u0003צרה.\u0004 ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שאינם דורשים מלה זו, \u0003האי\u0004 \u0005[\u0006ההדגשה \u0005הזו]\u0006 של \u0003\"ולקחה\" מאי עבדי ליה\u0004 \u0005[מה הם עושים בה]?\u0006 שהלא היה יכול לכתוב רק \"ולקח\"!","ומשיבים: \u0003מיבעי להו\u0004 \u0005[צריכים הם\u0006 אותה\u0005]\u0006 \u0003לכ\u0004 מו שאמר \u0003ר' יוסי בר חנינא.\u0004 ש\u0003אמר ר' יוסי בר חנינא:\u0004 נאמר \u0003\"ולקחה\",\u0004 ומשמעו, שלוקח, נושא, אותה והריהי מאז אשתו לכל דבר, \u0003מלמד שמגרשה בגט\u0004 אחרי שייבם אותה ואינו פוטרה על ידי חליצה, \u0003ו\u0004אף \u0003מחזירה\u0004 ונושא אותה שוב אם רצה. שנוהג בה כאשתו לכל דבר, ואין חלה עוד עליה חובת הייבום, ולא איסור אשת אח. ומה שנאמר \u0003\"ויבמה\"\u0004 פירושו לדעת חכמים: \u0003על כרחה.\u0004 כי קידושין בכלל אינם תופסים אלא מדעתה של האשה, אבל הייבום יכול להיות בעל כרחה.","ושואלים: \u0003ורבי,\u0004 מהיכן למד הוא הלכות מקובלות אלה? ומשיבים: אותה הלכה של \u0003ר' יוסי בר חנינא\u0004 כי היבמה היא כאשתו, ויכול לגרשה ולהחזירה — \u0003מ\"לאשה\" נפקא\u0004 \u0005[יוצאת]\u0006 לו, שנאמר: \"ולקחה לו לאשה\", משמע שתהיה לו לאשה לכל דבר, ככל אשה אחרת. וההלכה שיכול ליבמה \u0003על כרחה — מ\"יבמה יבא עליה\" נפקא\u0004 \u0005[יוצאת,\u0006 נלמדת לו\u0005],\u0006 שמשמעו: בכל דרך ובכל אופן.","ושואלים: \u0003ורבי, האי\u0004 \u0005[\u0006הייתור \u0005הזה]\u0006 \u0003\"עליה\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006 ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[צריך הוא לו לכפי ששנינו\u0006 בברייתא\u0005]\u0006 בענין אחר: שאמרו חכמים \u0003אין חייבין בית דין\u0004 להביא פר חטאת (פר העלם דבר של ציבור) על מה שהורו בטעות ועשו הציבור כהוראתם, \u0003אלא על\u0004 שהתירו בטעות \u0003דבר\u0004 שחייבים על \u0003זדונו\u0004 (אם עשו אותו בזדון) \u0003כרת, ו\u0004על \u0003שגגתו\u0004 (אם עשו אותו בשגגה) חייבים קרבן \u0003חטאת. וכן המשיח\u0004 (הכהן הגדול) שגם הוא מביא פר העלם דבר, אינו מביא אלא אם כן נעלם ממנו דבר שזדונו כרת ושגגתו חטאת."],["\u0003ולא\u0004 חייבים הציבור להביא פר העלם דבר על שגגתם \u0003בעבודה זרה, אלא על דבר\u0004 מעשה של עבודה זרה \u0003שחייבין על זדונו כרת ושגגתו חטאת,\u0004 כגון: זביחה, הקטרה, ניסוך והשתחוויה לעבודה זרה, אבל חיבוק ונישוק עבודה זרה אינו בכלל זה. \u0003ותנן נמי\u0004 \u0005[ושנינו גם כן\u0006 במשנה\u0005]\u0006 כעין זה: \u0003כל מצוה שבתורה,\u0004 אם עבר עליה בשגגה, על דבר \u0003שחייבין על זדונו כרת ועל שגגתו חטאת,\u0004 אם היה זה \u0003יחיד\u0004 ששגג בכך — \u0003מביא כשבה או שעירה\u0004 (עז), ואם \u0003נשיא\u0004 (מלך) — \u0003מביא\u0004 על חטא כזה \u0003שעיר,\u0004 ואם \u0003משיח\u0004 (כהן גדול) \u0003ובית דין — מביאין פר.\u0004","\u0003ו\u0004אם חטאו \u0003בעבודה זרה\u0004 בשגגה כזו, \u0003יחיד\u0004 ו\u0003נשיא ומשיח\u0004 — \u0003מביאין שעירה,\u0004 ואילו ה\u0003צבור מביאים פר ושעיר, פר לעולה ושעיר לחטאת.\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין דברים אלה]\u0006 שרק על עבירה כגון זו מביאים קרבן חטאת?","ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים],\u0006 נאמר בפר העלם דבר של ציבור: \u0003\"ונודעה החטאת אשר חטאו עליה\"\u0004 (ויקרא ד, יד), \u0003רבי אומר: נאמר כאן\u0004 בחטאת \u0003\"עליה\", ונאמר להלן\u0004 באיסור אחות אשה \u0003\"עליה\",\u0004 ואנו למדים בגזירה שווה: \u0003מה להלן\u0004 באחות אשה הרי זה \u0003דבר שחייבים על זדונו כרת ועל שגגתו חטאת, אף כאן\u0004 קרבן זה שמביאים אינו אלא על \u0003דבר שחייבין על זדונו כרת ועל שגגתו חטאת.\u0004","וממשיכים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא הוכחה על מה מביאים ה\u0003צבור\u0004 קרבן חטאת, \u0003משיח מנלן\u0004 \u0005[מניין לנו]\u0006 שגם הוא מביא חטאת על חטא כזה בלבד? \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003במשיח\u0004 (בכהן גדול): \u0003\"\u0004אם הכהן המשיח יחטא \u0003לאשמת העם\"\u0004 (שם ג), \u0003הרי\u0004 שה\u0003משיח\u0004 מביא קרבן על חטא \u0003כצבור.\u0004","\u0003יחיד ונשיא\u0004 מניין שמביאים קרבן חטאת רק על חטאים בדרגת חומרה זו — \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה של המילים \u0003\"מצות\" \"מצות\"\u0004 שנאמר, הן בחטא העם, הן בחטא היחיד, והן בחטא הנשיא: \"מכל מצות ה' אשר לא תעשינה\" (שם ב. שם יג. שם כב).","\u0003ו\u0004ההלכה היא כי \u0003לא בעבודה זרה אלא על דבר שחייבין על זדונו כרת ועל שגגתו חטאת. צבור בעבודה זרה — יליף\u0004 \u0005[לומד]\u0006 בגזירה שווה של \u0003\"מעיני\" \"מעיני\",\u0004 שנאמר בפר העלם דבר של ציבור: \"מעיני הקהל\" (שם יג), ובשגגת עבודה זרה נאמר: \"מעיני העדה\" (במדבר טו, כד), ללמד שהעדה מביאה קרבן על שגגת עבודה זרה רק כאשר היתה העבירה כזו שיש בזדונה כרת.","\u0003יחיד, נשיא ומשיח\u0004 למדים \u0003מ\u0004מה שנאמר בשגגת עבודה זרה: \u0003\"ואם נפש אחת\u0004 תחטא\u0003\"\u0004 (שם כז) — \u0003אחד יחיד, ואחד נשיא, ואחד משיח במשמע.\u0004 וה\u0003וי\"ו\u0004 שבמלת \"ואם\" שבתחילת הפסוק \u0003מוסיף על ענין ראשון,\u0004 של שגגת העדה כולה, ללמדנו ששתי ההלכות הללו קשורות זו בזו,","\u0003וילמד תחתון\u0004 הנושא השני, המדבר ביחיד, \u0003מן העליון\u0004 המדבר בציבור. וכיון שבציבור אינו מביא קרבן זה אלא על דבר שזדונו כרת — אף יחיד דינו כך, ואם כן, יש לרבי לימוד מן המלה \"עליה\".","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 שדורשים \"עליה\" לענין צרות, \u0003האי סברא מנא להו\u0004 \u0005[סברה זו מניין להם]?\u0006 ומשיבים: \u0003נפקא להו\u0004 \u0005[יוצא,\u0006 נלמד \u0005להם]\u0006 הדבר ממקור אחר, \u0003מדמקרי ליה\u0004 \u0005[מ\u0006מה \u0005ש\u0006היה \u0005מקריא,\u0006 מלמד \u0005לו]\u0006 \u0003ר' יהושע\u0004 בן לוי \u0003לבריה\u0004 \u0005[לבנו]\u0006 בפסוק המסכם דין עבודה זרה בשוגג: \u0003\"\u0004האזרח בבני ישראל ולגר הגר בתוכם \u0003תורה אחת יהיה לכם לעשה בשגגה\"\u0004 (שם כט), וסמוך לו \u0003\"והנפש אשר תעשה ביד רמה\u0004 מן האזרח ומן הגר את ה' הוא מגדף ונכרתה הנפש ההיא מקרב עמה (שם ל),","\u0003הוקשה\u0004 \u0005[הושוותה]\u0006 \u0003כל התורה כולה\u0004 (\"תורה אחת\") \u0003לעבודה זרה, מה עבודה זרה\u0004 אין חייבים קרבן אלא על \u0003דבר שחייבין על זדונו כרת ועל שגגתו חטאת\u0004 (\"ונכרתה הנפש ההיא\") — \u0003אף כל דבר\u0004 אין חייבים קרבן אלא על דבר \u0003שחייבין על זדונו כרת ועל שגגתו חטאת.\u0004","ומעירים: \u0003אשכחן\u0004 \u0005[מצאנו\u0006 איפוא\u0005]\u0006 לפי זה מקור עבור \u0003יחיד ונשיא ומשיח, בין בעבודה זרה ובין בשאר מצות. צבור בעבודה זרה מניין\u0004 שחייב רק על שגגה כזו? \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ואם נפש\u0004 אחת תחטא\u0003\"\u0004 (שם כז) בוי\"ו החיבור, ללמד ששני הדינים קשורים זה לזה, \u0003וילמד עליון,\u0004 הקטע הראשון המדבר בציבור \u0003מתחתון\u0004 מן השני, המדבר ביחיד.","\u0003אלא, צבור בשאר מצות מנלן\u0004 \u0005[מניין לנו]\u0006 שאינו מביא אלא על דבר שזדונו כרת? ומשיבים: \u0003יליף\u0004 \u0005[לומד]\u0006 בגזירה שווה \u0003\"מעיני\" \"מעיני\",\u0004 שנאמר בעבודה זרה, \"מעיני העדה\", ובשאר מצוות \"מעיני הקהל\", ושואלים: \u0003ורבי, האי\u0004 \u0005[\u0006הפסוק \u0005הזה]\u0006 \u0003\"תורה אחת\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005לו],\u0006 מה הוא למד ממנו? ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[נצרך לו\u0006 הפסוק \u0005לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003לפי שמצינו שחלק הכתוב בין יחידים\u0004 שחטאו \u0003למרובים\u0004 שחטאו בעבודה זרה. כיצד?","שכן \u0003יחידים\u0004 שעבדו עבודה זרה נידונים \u0003בסקילה, לפיכך ממונן פלט\u0004 (ניצול מהחרמה), שאמנם ממיתים את החוטא, אבל אין מחרימים את רכושו, ואילו \u0003מרובין\u0004 נידונים במיתה קלה יותר, \u0003בסייף.\u0004 שכך דינה של עיר הנדחת שכל אנשיה עבדו עבודה זרה, \u0003לפיכך ממונן אבד,\u0004 שכך מצות התורה לשרוף את כל הרכוש של בני העיר.","\u0003יכול נחלוק\u0004 גם \u0003בקרבנותיהן,\u0004 אם שגגו בעבודה זרה, שלא יביאו כולם אותו קרבן — \u0003תלמוד לומר: \"תורה אחת יהיה לכם\"\u0004 (שם כט), ליחיד שעבד ולרבים שעבדו.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב חלקיה מ\u0004המקום \u0003הגרוניא: טעמא דכתב רחמנא\u0004 \u0005[הטעם,\u0006 דווקא, \u0005שכתבה התורה]\u0006 \u0003\"תורה אחת יהיה לכם\", הא לאו הכי, הוה אמינא\u0004 \u0005[הרי לולא כן, הייתי אומר]\u0006 ש\u0003נחלק\u0004 בקרבנותיהם, והרי יש לשאול: \u0003מאי לייתו\u0004 \u0005[מה יביאו],\u0006 איזה קרבן היו צריכים להביא, אם היינו מחלקים? אם תאמר \u0003לייתו\u0004 \u0005[יביאו]\u0006 \u0003פר\u0004 בלבד, הלא \u0003צבור\u0004 ששגגו \u0003בשאר מצות הוא דמייתו\u0004 \u0005[שמביאים]\u0006 פר, וכיון שנכתב הדבר לעצמו — משמע שאין דינם דומה.","ואם תאמר שיביאו \u0003כשבה\u0004 — הלא \u0003יחיד בשאר מצות הוא דמייתי\u0004 \u0005[שמביא],\u0006 ואם יביאו \u0003שעיר\u0004 לכפרה הלא \u0003נשיא בשאר מצות הוא דמייתי\u0004 \u0005[שמביא].\u0006 ואם תאמר שיביאו \u0003פר לעולה ושעיר לחטאת\u0004 — הרי \u0003צבור,\u0004 כלומר, רוב ישראל, \u0003בעבודה זרה הוא דמייתו\u0004 \u0005[שמביאים],\u0006 \u0003ואלא מאי\u0004 \u0005[מה]\u0006 יביאו, \u0003שעירה — יחיד נמי היינו\u0004 \u0005[גם כן זהו]\u0006 \u0003קרבנו,\u0004 שהרי היחיד יכול להביא לקרבן חטאת כשבה או שעירה, ולכאורה אין צורך בלימוד מיוחד בענין זה, שהרי אין אפשרות נוספת!","ומשיבים: \u0003איצטריך, סלקא דעתך אמינא\u0004 \u0005[נצרך\u0006 הדבר, כי \u0005יעלה על דעתך לומר]\u0006 \u0003הואיל וצבור בהוראה\u0004 כאשר הורה בית דין בטעות לציבור שמותר לו לעבוד עבודה זרה שאז \u0003מייתו\u0004 \u0005[מביאים]\u0006 בית הדין \u0003פר לעולה ושעיר לחטאת, אינהו נמי ניתו איפכא\u0004 \u0005[הם גם כן שיביאו,\u0006 אבל \u0005להיפך]\u0006 פר לחטאת ושעיר לעולה.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 נאמר, שמא היה \u0003צריך\u0004 להביא כפרה שונה מיחיד \u0003ו\u0004רק \u0003אין לו תקנה,\u0004 שלא נאמרה בתורה תקנה לכפר על חטא זה של רבים, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \"תורה אחת יהיה לכם\" שגם לרבים שעבדו עבודה זרה יש כפרה בקרבן.","עד כאן עסקנו במדרשי המקראות, ומעכשיו באים לדקדק בגופי ההלכות שבמשנה. וקודם כל בתפיסת המכלול, במספרים שדיברנו בהם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 החכם \u0003לוי לרבי: מאי איריא דתני\u0004 \u0005[מה שייך,\u0006 מדוע, \u0005שנה]\u0006 \u0003חמש עשרה\u0004 נשים? \u0003ליתני\u0004 \u0005[שישנה]\u0006 \u0003שש עשרה,\u0004 שהרי אפשר למצוא גם מקרה נוסף של צרת ערוה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי: \u0003כמדומה לי שאין לו מוח בקדקדו\u0004 לשואל זה.","והוא עצמו פירש את השאלה ותשובתה: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003דעתך,\u0004 שאפשר להוסיף עוד \u0003אמו אנוסת אביו,\u0004 שאם אמו היתה רק אנוסת אביו ולא היתה נשואה לאב, ולפי דעת חכמים שאנוסת האב מותרת לבניו מאשה אחרת, יכול להיות שהאב יאנוס אשה ויוליד ממנה בן, ואותה אשה עצמה תינשא אחר כך לאחד הבנים של האונס, ואם זה שנשאה ימות בלא בנים — נמצא שהאם נופלת לייבום לפני אחי המת, שהוא בנה. ואם כן יש כאן בסך הכל שש עשרה עריות!","אולם, אי אפשר לומר כך, כי דין \u0003אמו אנוסת אביו\u0004 הלא \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 בין \u0003ר' יהודה ורבנן\u0004 \u0005[וחכמים]\u0006 היא, שלדעת ר' יהודה לא יתכן שאנוסת אביו תיפול לפניו לייבום, כיון שאסורה לאחיו משום אנוסת אביו, \u0003ובפלוגתא לא קא מיירי\u0004 \u0005[וב\u0006דבר שיש בו \u0005מחלוקת לא עסק]\u0006 במשנה זו, שנמנו במשנה רק דברים המקובלים על הכל, ולא דברים שיש בהם מחלוקת.","ושואלים: \u0003ו\u0004האם \u0003לא\u0004 נמנו במשנה דברים שיש בהם מחלוקת? \u0003והרי איסור מצוה ואיסור קדושה,\u0004 אם נופלת לייבום אשה שאסורה עליו משום גזירת חכמים שאסרו לשאתה (כגון קרובה רחוקה יותר שהיא \"שניה\" לעריות), או שהיא אסורה בלאו בלבד משום קדושת ישראל או קדושת הכהונה, כגון ממזרת או נתינה,","\u0003דפליגי\u0004 \u0005[שנחלקו]\u0006 בכך \u0003ר' עקיבא ורבנן\u0004 \u0005[וחכמים]\u0006 אם אשה כזו פטורה לגמרי מן הייבום ומן החליצה, כערוה, או שחלה עליה מצות ייבום, וכיון שאינו רשאי לשאת אותה — צריך לחלוץ לה, \u0003ו\u0004בכל זאת \u0003קתני\u0004 \u0005[שנה]\u0006 הלכה זו השנויה במחלוקת (להלן יבמות כא, א)!","ומשיבים: \u0003בפרקין קא אמרינן\u0004 \u0005[בפרקנו אמרנו],\u0006 כלומר, אמרנו שבפרק זה נשנו רק הלכות מוסכמות ומחלוקת ר' עקיבא וחכמים נאמרה בפרק שני. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 בפרקנו זה שנינו ש\u0003בית שמאי מתירין את הצרות לאחין,\u0004 שלדעתם אין איסור בצרת ערוה \u0003ובית הלל אוסרין,\u0004 והרי שגם בפרקנו שנויה הלכה שהיא בעיקרה במחלוקת!","ומשיבים: דעת \u0003בית שמאי, במקום\u0004 שחולקים עליהם \u0003בית הלל — אינה משנה.\u0004 כלומר, דעתם דחויה מן ההלכה ואין זה נחשב למחלוקת. ומקשים עוד: \u0003והרי אשת אחיו שלא היה\u0004 (חי) \u0003בעולמו\u0004 (בזמן חייו) של היבם, שכשמת אחיו עדיין לא נולד,"],["\u0003דפליגי\u0004 \u0005[שחלוקים]\u0006 בכך \u0003ר' שמעון ורבנן, וקתני\u0004 \u0005[ושנה]\u0006 את ההלכה הזו, הרי שגם משנתנו עוסקת בדברים שעיקרם במחלוקת!","ומשיבים: גם ר' שמעון לא נחלק בכל מקרה של \"אשת אחיו שלא היה בעולמו\", שכן \u0003ב\u0004מקרה הפשוט של אח ש\u0003נולד\u0004 אחר מיתת אחיו שלא היה בעולמו, שלא חלה על תינוק זה מצות ייבום והאשה אסורה עליו משום אשת אח, \u0003ולבסוף,\u0004 לאחר שנולד \u0003ייבם\u0004 אח אחר את האשה ומת גם הוא ונפלה שוב לפני אותו אח קטן שלא היה בעולמו של אחיו, בעלה הראשון — במקרה כזה \u0003לא פליג\u0004 \u0005[חלק]\u0006 \u0003ר' שמעון,\u0004 ומודה שאשה זו אסורה על הילד לעולם, כיון שנאסרה עליו שעה אחת כאשר נולד והיא היתה אשת אחיו שלא היה בעולמו. ולא נחלק ר' שמעון אלא במקרה אחר, כאשר היו שני אחים, ומת אחד מהם וייבם השני את אשתו, ואחר כך נולד האח השלישי, ומת האח השני. שלדעת ר' שמעון יכולה אשה זו להתייבם לאח הקטן, שמעולם לא היתה אסורה עליו, כיון שבשעה שנולד היתה זו אשת אחיו שהיה בעולמו, ומה שהיה לפני לידתו איננו נחשב. ומאחר שגם לר' שמעון יש צד איסור של אשת אחיו שלא היה בעולמו, אפשר היה לשנות זאת במשנה לכל הדעות.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אושעיא: חלוק היה ר' שמעון אף בראשונה,\u0004 שלדעתו ר' שמעון חלוק לא רק במקרה של \"ייבם ואחר כך נולד\" אלא גם במקרה של \"נולד ולבסוף ייבם\" ולדעתו אף במקרה כזה יכולה היא להתייבם לאח הקטן!","ודוחים: \u0003הא איתותב\u0004 \u0005[הרי\u0006 כבר \u0005הושב,\u0006 נדחה\u0005]\u0006 \u0003ר' אושעיא\u0004 ובטילה שיטה זו (להלן יבמות יח, ב), ולכן אפשר לומר שמשנתנו איננה עוסקת במחלוקת.","ומקשים מצד אחר: בפרק השלישי במסכת יבמות מדובר במקרה כשהיו ארבעה אחים, שנים מהם היו נשואים לשתי אחיות, ומתו שני האחים בעלי האחיות. ונמצא שלפני כל אחד מן האחים החיים נופלות (לחלוץ או לייבם) שתי אחיות כאחת. ואמרו חכמים שבמקרה כזה אין מייבמים, לפי שמחשיבים זאת כאילו נפלו לפני כל אחד שתי אחיות כאחת, ובגלל זיקות הקשר של הייבום הרי זה כאילו כל אחת מהן היתה נשואה לו במידה מסויימת ונמצא שהיא כעין אחות אשתו, וכיון שהדבר חל על שתיהן בשווה — שתיהן אסורות בייבום. ואמרו, שאם אחת מן האחיות הללו היתה אסורה על אחד מן האחים שנשארו בחיים בגלל היותה ערוה לו, כגון שהוא נשא את בתה או קרובה אחרת שלה, במקרה זה האחות השניה (שאין בה קירבה כזו) מותרת לו לגמרי. ואם היה קיים הקשר הזה בין האח האחר באחות השניה, יכול להיווצר מצב ששני האחים יחלצו או ייבמו את שתי האחיות. \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר רב, וכן תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא\u0004 ברייתא: \u0003בכולן,\u0004 בכל חמש עשרה הנשים המנויות במשנתנו, יכול \u0003אני\u0004 לדמות מצב שאני \u0003קורא בהן האסורה ל\u0004אח \u0003זה — מותרת ל\u0004אח \u0003זה, והאסורה ל\u0004אח \u0003זה מותרת ל\u0004אח \u0003זה,\u0004 ויכול אז להיות ש\u0003אחותה שהיא יבמתה\u0004 (גיסתה) \u0003חולצת או מתייבמת.\u0004 שדבר זה אפשר למנות בכל אחת מן המנויות במשנה, כגון שאחות אחת היא חמותו של אח זה, ואחות שניה היא חמותו של האח השני. וכיוצא באלה.","\u0003ורב יהודה\u0004 היה \u0003מתרגם,\u0004 כלומר, מסביר, מיישב דברים אלה, כי לא בכל הנשים האמורות ברשימה שלנו, אלא \u0003מחמותו ואילך,\u0004 שמחמותו עד סוף הרשימה יכול להיות שאחות אחת תהיה לגבי אח אחד איסור ערוה והאחות האחרת לא תהיה אסורה עליו כלל. \u0003אבל שיתא בבי דרישא\u0004 \u0005[\u0006ב\u0005ששת השערים,\u0006 המקרים, \u0005ש\u0006ב\u0005התחלה]\u0006 — \u0003לא\u0004 היה גורס דבר זה. \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006","משום המקרה של \u0003בתו,\u0004 למשל, כי יתכן שאחת מן האחיות תהיה בתו של אחד האחים. אבל אז אסורה אמה לכל האחים (משום אשת אח) ולא יתכן שתהיה לה בת מאח אחר. ודבר כזה יתכן רק אם אח אחד אנס אשה והוליד ממנה בת, וכיון שאיסור אשת אח הוא רק מן הנישואין, הרי אין אותה אשה אסורה על אחיו, ואם חזר אחיו ואנס את האשה והוליד ממנה בת, ושתי בנות אלה נישאו לשני האחים האחרים, הרי אז יווצר המצב שכל אחת מהאחיות היבמות הללו אסורה לאח אחד ומותרת לאח השני.","ובכן, \u0003ב\u0004מקרה של \u0003אונסין משכחת\u0004 \u0005[יכול אתה למצוא],\u0006 אבל \u0003ב\u0004מקרה של \u0003נשואין לא משכחת לה\u0004 \u0005[אין אתה יכול למצוא אותה],\u0006 כאמור, על כן אין לפרש את משנתנו בדרך זו כי משנתנו \u0003בנשואין קמיירי\u0004 \u0005[עוסקת],\u0006 \u0003באונסין לא קא מיירי\u0004 \u0005[איננה עוסקת].\u0006","\u0003ואביי מתרגם\u0004 היה שונה וכולל כאן \u0003אף\u0004 את \u0003בתו מאנוסתו,\u0004 ומדוע — \u0003כיון דאשכוחי משכחת לה\u0004 \u0005[שאתה מוצא אותה\u0006 אפשרות\u0005]\u0006 בין \u0003אי בעיא\u0004 \u0005[אם תרצה]\u0006 \u0003מן האונסין תהוי\u0004 \u0005[תהיה],\u0006 \u0003ואי בעיא\u0004 \u0005[ואם תרצה]\u0006 \u0003מן הנשואין תהוי\u0004 \u0005[תהיה],\u0006 שיש בכל זאת מקרה שאפשר שיווצר מצב כזה. \u0003אבל\u0004 את המקרה האחרון של \u0003אשת אחיו שלא היה בעולמו — לא\u0004 היה מונה. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר?","\u0003כיון\u0004 שרק \u0003ל\u0004פי דעת \u0003ר' שמעון הוא דמשכחת לה\u0004 \u0005[שאתה מוצא אותה]\u0006 שיכול להיות דבר כזה, שכיון שהוא מתיר במקרה של \"ייבם ולבסוף נולד\", הרי יתכן שאחות אחת תהיה אסורה לאח אחד משום שנולד לפני שאחיו ייבם אותה, וכן האחות השניה תהיה אסורה לאח האחר מאותו טעם, אף שהראשונה מותרת לו (לפי שבחייו לא היתה אשת אחיו שלא היה בעולמו), ואילו \u0003לרבנן לא משכחת לה\u0004 \u0005[ל\u0006דעת \u0005חכמים אין אתה\u0006 יכול \u0005למצוא אותה] —\u0006 \u0003בפלוגתא לא קא מיירי\u0004 \u0005[במחלוקת איננו עוסק]\u0006 אלא רק בדברים המוסכמים על הכל.","\u0003ו\u0004אילו \u0003רב ספרא מתרגם\u0004 היה שונה כאן \u0003אף אשת אחיו שלא היה בעולמו, ומשכחת לה\u0004 \u0005[ו\u0006יכול אתה \u0005למצוא אותה]\u0006 \u0003בשיתא\u0004 \u0005[בשישה]\u0006 \u0003אחים\u0004 שהיו שם \u0003ואליבא\u0004 \u0005[ועל פי שיטתו]\u0006 של \u0003ר' שמעון\u0004"],["\u0003וסימניך,\u0004 כיצד יתכן הדבר: אם היו כמה אחים, \u0003מת\u0004 אחד מהם (\"ראובן\"), ואחר כך \u0003נולד\u0004 אח אחר (\"יששכר\") \u0003ויבם\u0004 האח השני (\"שמעון\") את אשת המת כדין. ולאחר מכן \u0003מת\u0004 אח אחר (\"לוי\"), ולאחר שמת \u0003נולד\u0004 להם אח נוסף (\"זבולון\") \u0003ויבם\u0004 אח אחר (\"יהודה\") את אשתו של לוי. ואם מתו גם שני אלה (\"שמעון\" ו\"יהודה\") בלא בנים נופלות אותן יבמות לפני האחים הנותרים (\"יששכר\" ו\"זבולון\") שעבור אחד מהם (\"יששכר\") אשת האח הראשון (\"ראובן\") אסורה, שהרי כשמת בעלה הוא עדיין לא נולד, ועבור השני (\"זבולון\") אסורה אשתו של האח השני (\"לוי\") מאותו טעם, וכפי שמפורש המקרה בכל פרטיו בפרק שלישי, שהאסורה לזה מותרת לזה, והאסורה לזה מותרת לזה. ומכל מקום לענייננו למדנו שבתוך הכללים כלל ר' חייא גם את שיטתו של ר' שמעון, שהרי אמר ר' חייא שבכולן אני קורא האסורה לזה מותרת לזה. ואם כן נמצא שמשנתנו עוסקת בדינים השנויים במחלוקת, וכיצד אמר רבי שהכל מוסכם בה?","ומשיבים: \u0003אלא, לרבי — הני כללי לית ליה\u0004 \u0005[\u0006את \u0005הכללים הללו\u0006 שקבע ר' חייא \u0005אין לו,\u0006 אין רבי מקבל\u0005]\u0006 ואיננו סבור שהם נכונים, ולדעתו כל דבר שיש בו מחלוקת — לא שנו במשנתנו. \u0003רב אדא קרחינא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב כהנא אמר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: לעולם\u0004 יכול אתה לפרש ש\u0003אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 \u0003רבי הני כללי\u0004 \u0005[\u0006את \u0005הכללים הללו]\u0006 של ר' חייא. \u0003והכי קאמר ליה\u0004 \u0005[וכך אמר לו]\u0006 ללוי: \u0003אמו אנוסת אביו\u0004 שתוכל להחיל עליה את הכללים של ר' חייא, רק \u0003בחדא משכחת לה\u0004 \u0005[ב\u0006מקרה של אשה \u0005אחת\u0006 יכול \u0005אתה למצוא אותה],\u0006 כלומר, יכול אתה למצוא רק חלק אחד מן המקרה המסובך הזה. אבל \u0003בתרתי לא קמשכחת לה\u0004 \u0005[בשתים אין אתה מוצא אותה]\u0006","ומבארים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003יעקב,\u0004 כלומר, האב, \u0003שתי אחיות אנס\u0004 והוליד מהן שני בנים, והיו לו שני בנים אחרים שנשאו את שתי האחיות האנוסות הללו, ומתו, ואז אפשרות שיש בו \u0003אחותה שהיא יבמתה משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 שהרי יש אשה הנופלת לייבום ואסורה משום ערוה, והיא גם אחותה וגם גיסתה של היבמה האחרת. אבל \u0003\"האסורה לזה מותרת לזה\" לא משכחת\u0004 לה \u0005[אין אתה מוצא].\u0006 אמנם, יתכן שאשת אחיו שהיא אמו תיפול לפניו לייבום, אבל כשם שהוא אסור באמו כך הוא אסור גם באחות אמו, ונמצא שאין כאן \"האסורה לזה מותרת לזה\".","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003שתי\u0004 נשים \u0003נכריות\u0004 (זרות) זו לזו \u0003אנס\u0004 האב והוליד מהן שני בנים, ושתי הנשים הללו נישאו אחר כך לשנים מבניו, ומתו, אם כן, \u0003\"האסורה לזה מותרת לזה\" משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 שכל אחד משתי האנוסות תיפול לייבום לפני אח אחד, בעוד שהיא אסורה לאחיו משום שהיא אמו. אבל \u0003\"אחותה שהיא יבמתה\" לא משכחת לה\u0004 \u0005[אינך מוצא אותה],\u0006 ולכן אי אפשר למנות במשנה את אמו שהיא אנוסת אביו, משום שהכללים שקבע ר' חייא לא יחולו על כך.","\u0003רב אשי אמר\u0004 הסבר אחר: \u0003לעולם\u0004 תפרש כי \u0003לית ליה לרבי הני כללי\u0004 \u0005[אין לו,\u0006 אין \u0005רבי\u0006 מקבל את \u0005הכללים הללו]\u0006 של ר' חייא \u0003ובפלוגתא קמיירי\u0004 \u0005[ו\u0006גם בדברים השנויים \u0005במחלוקת עוסקת\u0006 המשנה\u0005],\u0006 ולפי זה, \u0003ומאי\u0004 \u0005[ומה]\u0006 פירוש הדברים \u0003\"כמדומה אני שאין לו מוח בקדקדו\" דקאמר ליה\u0004 \u0005[שאמר לו]\u0006 רבי ללוי — לא מהטעמים האלו אמר לו, אלא","\u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו]:\u0006 \u0003מאי טעמא לא דייקת מתניתין\u0004 \u0005[מה טעם אין אתה מדייק במשנתנו]?\u0006 \u0003דמתניתין\u0004 \u0005[שמשנתנו\u0006 זו\u0005]\u0006 כשיטת \u0003ר' יהודה היא,\u0004 והרי הוא ש\u0003אסר באנוסת אביו.\u0004 ואי אפשר להכניס למשנה זו, שהיא כדעת ר' יהודה, שיטה השונה מדעתו.","ומהי ההוכחה שמשנתנו היא כר' יהודה — \u0003דקתני\u0004 \u0005[ששנה\u0006 במשנה הבאה\u0005]:\u0006 \u0003שש עריות חמורות מאלו\u0004 שמנינו, \u0003מפני שהן נשואות לאחרים צרותיהן מותרות,\u0004 כיון שאינן יכולות לעולם להיות נשואות לאחד מן האחים, ואלו הן: \u0003אמו, ואשת אביו, ואחות אביו.\u0004 ונדייק: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אמו? אילימא\u0004 \u0005[אם תאמר]\u0006 שזו אמו \u0003נשואת אביו — היינו\u0004 \u0005[הרי זו]\u0006 \u0003אשת אביו,\u0004 ואם כן אין כאן שש, אלא רק חמש!","\u0003אלא לאו\u0004 \u0005[האם אין]\u0006 הכוונה אמו — \u0003אנוסת אביו. וקתני\u0004 \u0005[ושנה]\u0006 שם: \u0003מפני שהן נשואות לאחרים\u0004 ולכן אין דין ייבום חל עליהן, ומשמע: \u0003לאחרים — אין\u0004 \u0005[כן],\u0006 \u0003לאחין — לא,\u0004 כיון שכל אחד מן האחים בני אותו אב אסור לו לשאת את אמו של אחד האחים האחרים, שאם אינה אשת אביו הריהי לפחות אנוסת אביו, ואסור לאדם לשאת את אנוסת אביו. \u0003מאן שמעת ליה דאית ליה האי סברא\u0004 \u0005[מי שמעת אותו שיש לו סברה זו]\u0006 שאנוסת האב אסורה לבניו — \u0003ר' יהודה,\u0004 ש\u0003אסר באנוסת אביו. משום הכי\u0004 \u0005[כך]\u0006 \u0003לא תני ליה\u0004 \u0005[שנה אותה]\u0006 בחלקה הראשון של המשנה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי:\u0004 אפילו \u0003לר' יהודה נמי משכחת לה\u0004 \u0005[גם כן מוצא אתה אותה\u0006 אפשרות\u0005] —\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003עבר\u0004 אחד האחים \u0003ונסיב\u0004 \u0005[ונשא]\u0006 את אנוסת אביו, שהרי גם לדעת ר' יהודה אין זה איסור כרת שמבטל את הנישואין אלא רק איסור לאו, והנישואין חלים, ואם ימות אח זה תיפול היבמה לפני אביה. ודוחים: \u0003\"דאי\"\u0004 \u0005[\"שאם\"]\u0006 \u0003לא קתני\u0004 \u0005[שנה],\u0006 כלומר, אין אנחנו מביאים במשנה דוגמה לדבר שיכול להיות רק על ידי עבירה בלבד.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב כהנא: בלא \"דאי\"\u0004 \u0005[\"שאם\"]\u0006 \u0003נמי משכחת לה\u0004 \u0005[גם כן\u0006 יכול \u0005אתה למצוא אותה],\u0006 כלומר, אפשר למצוא אפשרות של אשה אנוסת האב שבכל זאת לא יהיה איסור בכך שאחד הבנים נשא אותה לאשה, כיצד? \u0003יעקב,\u0004 כלומר, אב, \u0003אנס\u0004 את \u0003כלתו והוליד ממנה בן, ומת ראובן\u0004 הבן, בעל הכלה, \u0003בלא בנים.\u0004 וכיון שהיו ליעקב זה שני בנים, בנו ראובן שמת, והבן שנולד לו מאשת ראובן שאנס, נמצא שאשת ראובן \u0003נפלה לה קמי ברה\u0004 \u0005[נופלת\u0006 לייבום \u0005לפני בנה],\u0006 \u0003ומיגו דאיהי אסירה\u0004 \u0005[ומתוך שהיא אסורה]\u0006 \u0003צרתה נמי אסירה\u0004 \u0005[גם כן אסורה],\u0006 ואם כן יש אפשרות כגון זו בלא נישואין שלא כדין.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003באחותה דהתירא קמיירי, באחותה דאיסורא לא קמיירי\u0004 \u0005[ב\u0006קשר \u0005אחווה של היתר הוא עוסק, ב\u0006קשר \u0005אחווה של איסור אינו עוסק],\u0006 שכן האיש שאנס את כלתו הוליד ממזר, ובכך אין הוא עוסק. ומעירים: \u0003ואף על פי כן,\u0004 למרות שגער רבי בלוי, \u0003בדקה\u0004 \u0005[קבע אותה]\u0006 \u0003לוי במתניתיה\u0004 \u0005[במשניות שלו],\u0006 שערך לוי קובץ ברייתות ובקובץ זה מנה גם את האפשרות הנוספת.","\u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003לוי\u0004 בברייתא שלו: \u0003אמו, פעמים פוטרת צרתה ופעמים אינה פוטרת צרתה. כיצד? היתה אמו נשואת אביו ונשאת\u0004 באיסור \u0003לאחיו מאביו, ומת — זו היא אמו שאין פוטרת צרתה,\u0004 שכן הנישואין שלה לאח לא תפסו כלל, שהרי היה בהם איסור כרת, וכיון שכן, לא חלו הנישואין, ורק האשה האחרת, הצרה, היא הנחשבת אשת האח, ואותה הוא יכול לייבם."],["\u0003היתה אמו אנוסת אביו, ונשאת לאחיו מאביו ומת — זו היא אמו שפוטרת צרתה.\u0004 שהרי לדעת חכמים נישואין אלה מותרים, ואפילו לר' יהודה אף על פי שאלו נישואין אסורים, מכל מקום אם עבר ונשאה קידושין תופסין בה, ונמצא שהאם וצרתה נופלות לפני הבן לייבום. וכיון שהאם היא ערוה עליו — הריהי פוטרת צרתה.","\u0003ואף על פי ששנו חכמים במשנתנו \"חמש עשרה\", יש לנו להוסיף שש עשרה כגון זו. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש לר' יוחנן: ל\u0004פי שיטת \u0003לוי\u0004 זו ש\u0003אמר\u0004 כי \u0003\"דאי\"\u0004 \u0005[\"שאם\"]\u0006 \u0003נמי קתני\u0004 \u0005[גם כן שונה],\u0006 כלומר, שהכניס במשנה גם מקרים שאינם לכתחילה, אלא נוצרו על ידי מעשה איסור, שאם שיטת המשנה היא כר' יהודה שאסור באנוסת אביו, ושנה דין העוסק במקרה שהאח עבר ונשא אשה זו האסורה לו — אם כן \u0003לתני\u0004 \u0005[שישנה]\u0006 עוד מקרה: \u0003החולץ ליבמתו וחזר וקדשה,\u0004 שאמנם עבר בכך על איסור, שלאחר שחלץ לה אסור בה לעולם, אבל מאחר שתופסים בה הקידושין, כיון שאינו אלא איסור לאו, \u0003ומת בלא בנים, דמיגו דאיהי\u0004 \u0005[שמתוך שהיא]\u0006 \u0003אסורה,\u0004 שהרי אסורה היא על כל האחים לאחר שחלץ לה האח שמת ואין הקידושין תופסים בה שהרי היא עליהם באיסור כרת — \u0003צרתה נמי אסירא\u0004 \u0005[גם כן אסורה],\u0006 ולפי זה יהיה לנו מקרה נוסף!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003לפי שאינה בצרת צרה.\u0004 כלומר, מקרה זה לעצמו אפשר היה לשנות, ולא מנו אותו במשנה משום שאיננו נכנס לתוך כללי הדברים ששנינו במשנתנו, שהרי במשנתנו מדובר על צרותיהן וצרות צרותיהן, ובמקרה זה אי אפשר שיהיה כך, שהרי אותו איסור חל בשווה על כל האחים, וכיון שאף אחד מהם אינו יכול לשאתה, שכן עליהם היא באיסור כרת, שוב אין שייכת כאן צרת צרה.","ושואלים על דברי ר' יוחנן: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 ר' יוחנן טעם אחר, שבכלל אין מקום לשאלתו, שהרי הנושא את חלוצתו לא עבר על איסור שיש בו כרת ואף האחים אינם חייבים לשיטתו כרת אלא לדעתו רק \u0003חייבי לאוין הן,\u0004 שעברו על לא תעשה בלבד, \u0003וחייבי לאוין — בני חליצה ויבום נינהו\u0004 \u0005[הם],\u0006 שמצות ייבום חלה עליהם, ואף שלמעשה יש לחלוץ לאשה — אינה פטורה לגמרי מן הייבום ואינה פוטרת את צרתה.","ומשיבים: \u0003לדבריו\u0004 ולשיטתו של ריש לקיש \u0003קאמר ליה\u0004 \u0005[אמר לו],\u0006 וכך אמר: \u0003לדידי\u0004 \u0005[ל\u0006שיטתי \u0005שלי]\u0006 \u0003חייבי לאוין הם, ו\u0004ממילא \u0003חייבי לאוין בני חליצה ויבום נינהו\u0004 \u0005[הם],\u0006 ולכן אין מקום לשאלתך, \u0003אלא לדידך\u0004 \u0005[ל\u0006שיטתך \u0005שלך]\u0006 ש\u0003חייבי כריתות נינהו\u0004 \u0005[הם]\u0006 שלשיטתך החלוצה יש בנישואיה לאחי החולץ איסור כרת, הרי יש לתרץ לשיטתך: \u0003לפי שאינן בצרת צרה.\u0004","ולגופה של אותה מחלוקת שהוזכרה קודם ברמז \u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003החולץ ליבמתו וחזר וקדשה, אמר ריש לקיש: הוא,\u0004 החולץ עצמו, \u0003אין חייב על החלוצה כרת\u0004 משום אשת אח, שלגביו אין בה איסור אשת אח, אף שאסורה עליו ב\"לא תעשה\".","\u0003והאחין\u0004 שלא חלצו לה — \u0003חייבין על החלוצה כרת,\u0004 שלגביהם לאחר חליצה אין בה היתר יבמה, ונשארה באיסור אשת אח. \u0003על הצרה\u0004 של האשה שנחלצה, שנפטרה מזיקת הייבום בחליצת חברתה, כיון שלא נעשה בה אפילו מעשה חליצה, \u0003בין הוא\u0004 (החולץ) \u0003ובין האחים — חייבין על הצרה כרת,\u0004 שהיא אסורה עליהם באיסור אשת אח.","\u0003ור' יוחנן אמר: בין הוא ובין האחין אינן חייבין לא על החלוצה כרת, ולא על הצרה כרת.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 דברי \u0003ריש לקיש? אמר קרא\u0004 \u0005[הכתוב]\u0006 שעל החולץ ליבמתו אומרים: \u0003\"אשר לא יבנה\u0004 את בית אחיו\u0003\"\u0004 (דברים כה, ט), ואנחנו למדים מכאן \u0003כיון שלא בנה\u0004 (לא ייבם) וחלץ לה — \u0003שוב לא יבנה.\u0004 ומבינים את הכתוב לא רק כביטוי של שלילה אלא גם מניעה ואיסור, שאסור לו לבנות שוב, כלומר, אשה זו אסורה עליו.","אולם, \u0003איהו הוא דקאי\u0004 \u0005[שעומד]\u0006 עכשיו \u0003ב\u0004איסור של \u0003\"לא יבנה\"\u0004 שאיסור הכרת בטל ממנו, וחל עליו האיסור של \"לא יבנה\". \u0003אבל אחיו — כדקיימי קיימי\u0004 \u0005[כמו שעמדו\u0006 קודם — \u0005עומדים\u0006 עתה\u0005],\u0006 שכשם שאשה זו היתה אסורה עליהם משום אשת אח לולא מצות הייבום, כיון שבטל חיוב הייבום, עומדים גם עכשיו באותו איסור, ולכן לגבי האחים יש כאן חיוב כרת.","ועוד: \u0003ו\u0004כמו כן \u0003עלה דידה\u0004 \u0005[ועליה עצמה],\u0006 על החלוצה, \u0003הוא דקאי\u0004 \u0005[שעומד]\u0006 רק \u0003ב\u0004איסור של \u0003\"לא יבנה\", הא\u0004 \u0005[הרי]\u0006 ה\u0003צרה\u0004 שלא חלץ לה — \u0003כדקיימי קיימי\u0004 \u0005[כמו שעומדים\u0006 עליה קודם באיסור כרת, עדיין \u0005עומדים\u0006 באיסור כרת\u0005]\u0006 לאחר חליצת צרתה ואין החולץ נבדל בזה משאר האחים.","\u0003ור' יוחנן\u0004 טוען: \u0003מי איכא מידי\u0004 \u0005[האם יש דבר]\u0006 בהלכה \u0003דמעיקרא\u0004 \u0005[שמתחילה]\u0006 לפני החליצה \u0003אי בעי האי\u0004 \u0005[אם\u0006 היה \u0005רוצה\u0006 אח \u0005זה] —\u0006 \u0003חליץ\u0004 \u0005[\u0006היה \u0005חולץ],\u0006 \u0003ואי בעי האי\u0004 \u0005[ואם\u0006 היה \u0005רוצה\u0006 אח \u0005זה] —\u0006 \u0003חליץ\u0004 \u0005[\u0006היה \u0005חולץ],\u0006 \u0003ואי בעי\u0004 \u0005[ואם\u0006 היה \u0005רוצה] —\u0006 \u0003להאי חליץ\u0004 \u0005[ל\u0006אשה \u0005זו\u0006 היה \u0005חולץ],\u0006 \u0003ואי בעי\u0004 \u0005[ואם\u0006 היה \u0005רוצה] —\u0006 \u0003להאי חליץ\u0004 \u0005[לזו\u0006 היה \u0005חולץ],\u0006 ואם כן יוצא שכל נשי האח המת היו עבור כל האחים בנות חליצה וייבום ובטל לגביהן איסור כרת של אשת אח, \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 לאחר החליצה \u0003קאי עלה\u0004 \u0005[יעמדו עליה]\u0006 \u0003בכרת?\u0004 שכיון שאיסור אשת אח בטל עם מות האח בלי בנים — כיצד יכול לחזור שוב איסור זה?","\u0003אלא, איהו שליחותא דאחים קעביד\u0004 \u0005[הוא,\u0006 החולץ, \u0005שליחות האחים עושה]\u0006 וכשחולץ לה פוטר אותה מזיקת ייבום גם משאר האחים, וכן \u0003איהי שליחותא\u0004 \u0005[היא\u0006 את \u0005השליחות]\u0006 של ה\u0003צרה קעבדה\u0004 \u0005[היא עושה],\u0006 שבחליצתה של האחת נפטרת גם האחרת. והרי זה כאילו חלצו כל האחים לכל הנשים, ושוב אין כאן חיוב כרת.","ומביאים את המשא ומתן בין החכמים: \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 מברייתא: \u0003החולץ ליבמתו וחזר וקדשה ומת — צריכה חליצה מן האחין.\u0004 ומעתה, \u0003בשלמא לדידי\u0004 \u0005[נניח לפי שיטתי]\u0006 \u0003דאמינא\u0004 \u0005[שאני אומר]\u0006 כי רק \u0003חייבי לאוין נינהו\u0004 \u0005[הם],\u0006 שיש רק איסור לאו על כל האחים לגבי החלוצה, \u0003היינו\u0004 \u0005[זהו]\u0006 הטעם לכך שהיא \u0003צריכה חליצה מן האחין,\u0004 שלפי הכללים, אשה שיש לגביה איסור לא תעשה שאין בו כרת איננה מתייבמת, אבל חייבת בחליצה.","\u0003אלא לדידך\u0004 \u0005[לשיטתך]\u0006 שיש כאן חיוב כרת, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003צריכה חליצה\u0004 כלל?","ענה לו ריש לקיש: \u0003ולטעמיך, אימא סיפא\u0004 \u0005[ולטעמך,\u0006 לשיטתך שכך אתה מבין את הברייתא, \u0005אמור את סופה],\u0006 ששנינו בה: \u0003עמד אחד מן האחין וקדשה, אין לה עליו כלום.\u0004 כלומר, הקידושין אינם תופסים בה כלל. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003חייבי לאוין\u0004 בלבד \u0003נינהו\u0004 \u0005[הם]\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 אם כן \u0003אין לה עליו כלום?\u0004 הלא באיסורי לאו הקידושין חלים, ואילו לשיטתי שיש בכך חיוב כרת — הדבר מובן, שאין קידושין חלים במקום איסור כרת. מכל מקום יש סתירה בין ראשיתה של הברייתא לסופה! וכיצד אפשר להביא ראיה מברייתא הנראית משובשת בנוסחה?","\u0003אמר רב ששת\u0004 בתירוץ סתירה זו: \u0003סיפא אתאן\u0004 \u0005[\u0006ב\u0005סופה\u0006 של הברייתא \u0005הגענו]\u0006 \u0003ל\u0004שיטה אחרת, שיטת \u0003ר' עקיבא.\u0004 ש\u0003אמר: אין קידושין תופסין בחייבי לאוין.\u0004 שלדעת ר' עקיבא אין הבדל כזה בין איסור לא תעשה ואיסור כרת, שבשניהם אין הקידושין תופסים. ומקשים: אם כך הוא, שבתחילה מדובר לשיטת חכמים ובסוף לשיטה אחרת, \u0003וליתני\u0004 \u0005[ושישנה]\u0006 במשנה במפורש: \u0003לדברי ר' עקיבא אין לו עליו כלום,\u0004 שכן שיטה אחרת היא!"],["\u0003קשיא\u0004 \u0005[קשה]\u0006 על תירוץ זה של רב ששת. את הסתירה בין תחילתה וסופה של ברייתא זו מתרצים בצורות אחרות. \u0003רב אשי סבר לה\u0004 \u0005[סבור\u0006 היה \u0005בה],\u0006 בהלכה זו, \u0003כ\u0004דעת \u0003ריש לקיש,\u0004 שהמקדש את חלוצת אחיו הריהו בכרת, \u0003ומתרץ לה\u0004 \u0005[ו\u0006היה \u0005מיישב אותה]\u0006 את הברייתא \u0003כ\u0004דעת \u0003ר' שמעון.\u0004 ואילו \u0003רבינא סבר לה\u0004 \u0005[סבור\u0006 היה \u0005בה]\u0006 בהלכה זו, \u0003כר' יוחנן,\u0004 שהמקדש את חלוצת אחיו הריהו בלאו, \u0003ומתרץ\u0004 אותה כולה \u0003כ\u0004דעת \u0003רבנן\u0004 \u0005[חכמים].\u0006","ומפרטים: \u0003רב אשי סבר לה כריש לקיש ומתרץ לה כר' שמעון,\u0004 וכך פירש: \u0003החולץ ליבמתו וחזר וקדשה\u0004 — \u0003צריכה חליצה מן האחין; מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003אחין\u0004 אלה —","\u0003אחין הילודים,\u0004 כלומר, אותם אחים שנולדו לאחר שאותו אח חזר וקידש. שכיון שכאשר נולדו היתה האשה הזו אשתו של אח חי, ועליהם לא חל האיסור (כיון שעדיין לא נולדו כשהיתה אשה זו אשת האח הראשון), לכן משמת אותו אח צריכה חליצה מהם. \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי] —\u0006 \u0003כר' שמעון\u0004 הסבור שכל שנולדו לאחר שכבר נתייבמה אשת אחיהם או חלצה, כגון זה אינו קרוי \"שלא היה בעולמו\".","בסיפא מדובר ש\u0003עמד אחד מן\u0004 האחים \u0003הנולדים\u0004 מאלה שנולדו עוד בחיי אחיהם הראשון \u0003וקדשה\u0004 לאחר שאחד האחים חלץ לה — \u0003אין לה עליו כלום, כמאן\u0004 \u0005[כ\u0006דעת \u0005מי] —\u0006 \u0003כ\u0004דעת \u0003ריש לקיש\u0004 שאמר שיש בקידושין לאחר חליצה איסור כרת, וממילא אין הקידושין תופסים.","ואילו \u0003רבינא סבר לה\u0004 \u0005[סבור היה בה],\u0006 בענין זה, \u0003כר' יוחנן, ומתרץ לה אליבא דרבנן\u0004 \u0005[על פי\u0006 שיטת \u0005חכמים].\u0006 וכיצד? \u0003החולץ ליבמתו וחזר וקדשה — צריכה חליצה מן האחין; מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003אחין\u0004 הללו — \u0003אחין הנולדים\u0004 עוד בחיי האח הראשון, \u0003כמאן\u0004 \u0005[\u0006ו\u0005כ\u0006דעת \u0005מי]\u0006 \u0003כ\u0004דעת \u0003ר' יוחנן,\u0004 שיש בקידושין הללו איסור לאו בלבד, ולכן במות האח המקדש לא נפטרה האשה לגמרי מחובת החליצה.","\u0003עמד אחד מן\u0004 האחים \u0003הילודים\u0004 שנולדו לאחר מות האח הראשון \u0003וקדשה — אין לה עליו כלום,\u0004 שכיון שהוא בכלל \"אחיו שלא היה בעולמו\" אסורה היא עליו משום אשת אח באיסור כרת, ואין הקידושין תופסים במקום איסור כרת, ואפילו נולד לאחר שקידשה האח הראשון. \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 — \u0003כ\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 הסוברים שאיסור \"אשת אחיו שלא היה בעולמו\" חל גם על אשת אח שמת, שחזרה ונתייבמה לפני שנולד האח הצעיר.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שיש מחלוקת בנושא דומה: \u0003הבא על יבמה\u0004 וקיים בה כראוי מצות ייבום \u0003ובא אחד מן האחין על צרתה, פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב אחא ורבינא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 השני הבא עליה עונשו \u0003בכרת. וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 עובר רק \u0003ב\u0004מצות \u0003עשה.\u0004","ומסבירים: \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שעונשו \u0003בכרת\u0004 הרי זה \u0003כ\u0004דעת \u0003ריש לקיש,\u0004 הסבור שלאחר שנעשתה המצוה באחת מן הנשים הזקוקות לייבום חל על צרתה שוב איסור אשת אח בכל תוקפו. \u0003ומאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שעובר רק \u0003בעשה,\u0004 הרי זה \u0003כ\u0004דעת \u0003ר' יוחנן\u0004.","ועוד לענין מניין הנשים הפטורות מן הייבום. \u0003אמר רב יהודה אמר רב: צרת סוטה אסורה.\u0004 כלומר, מי שהיה נשוי לשתי נשים, וזנתה (סטתה) אחת מהם, והיתה עדות על כך, ובינתיים הוא מת, היא וצרתה פטורות לגמרי מן החליצה ומן הייבום.","ומדוע — \u0003טומאה כתיב\u0004 \u0005[כתוב]\u0006 \u0003בה\u0004 בסוטה (\"ונסתרה והיא נטמאה\". במדבר ה, יג), \u0003כ\u0004מו שכתובה טומאה ב\u0003עריות\u0004 (שלאחר שנתפרשו כל העריות אמר הכתוב: \"אל תיטמאו בכל אלה\". ויקרא יח, כד), ולכן דין הסוטה כדין ערוה, והיא וצרתה פטורות מייבום ומחליצה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב חסדא\u0004 ממה ששנינו: אשה ששמעה שמת בעלה ונישאה, ואחר כך נודע שבאותו זמן היה עדיין חי ורק לאחר מכן מת, מה דינה? \u0003ר' שמעון אומר: ביאתה או חליצתה מאחיו של\u0004 הבעל ה\u0003ראשון פוטרת צרתה.\u0004 ומכאן שחל חיוב ייבום על אשה זו. והרי אשה זו נטמאה תחת אישה, שהרי היתה נשואה לאדם אחר בחיי בעלה, ובכל זאת אומר ר' שמעון שיש בביאתה או חליצתה משום קיום מצות הייבום עד כדי שהיא פוטרת צרתה, הרי שצרת סוטה חייבת בייבום!","ומשיבים: \u0003אמר לך רב\u0004 \u0005[\u0006יכול היה \u0005רב לומר לך]\u0006 ולהשיב: \u0003אמינא לך אנא\u0004 \u0005[אמרתי לך אני]\u0006 דין \u0003סוטה דאורייתא\u0004 \u0005[שמן התורה],\u0006 כלומר, אשה שזנתה בזדון תחת בעלה, \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003לי\u0004 דין \u0003סוטה דרבנן\u0004 \u0005[ש\u0006מדברי \u0005חכמים]?!\u0006 כיון שהעידו לה שבעלה מת ונישאה לאחר, אין לראות בכך אלא אונס. שכן מה שאסרו אותה חכמים גם לבעלה הראשון וגם לשני, הרי זה רק בתור קנס, כדי שיקפידו נשים לבדוק יפה יפה בעדויות כאלה. אבל כיון שאין זו סוטה מדין תורה, שהרי לא יצאה מבעלה בזדון לזנות עם אחר, ודאי שמצות ייבום חלה עליה.","כיון שתירוץ זה ברור כל כך, שואלים: \u0003ודקארי לה מאי קארי לה\u0004 \u0005[ומי שהקשה אותה\u0006 את הקושיה הזו \u0005מה הקשה אותה]?\u0006 הרי באמת אין מקום כלל לקושיה! ומשיבים: \u0003קסבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 \u0003כל\u0004 מה \u0003דתקון רבנן\u0004 \u0005[שתיקנו חכמים]\u0006 \u0003כעין דאורייתא תקון\u0004 \u0005[של תורה תיקנו]\u0006 ואם סוטה (מדין תורה) פטורה ופוטרת צרתה מן הייבום כערוה — אף סוטה דרבנן, היו צריכים חכמים לתקן בה כך.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב אשי\u0004 על רב ממה ששנינו: אשה שהזהיר אותה בעלה שלא תיסתר עם אדם מסויים, ו\u0003נכנסה עמו\u0004 בכל זאת \u0003לסתר, ושהתה עמו\u0004 זמן \u0003כדי טומאה\u0004 (ביאה) — \u0003אסורה לביתה,\u0004 כלומר, אסורה היא מאז על בעלה עד שתיבדק, \u0003ו\u0004אם היא בת ישראל הנשואה לכהן — \u0003אסורה לאכול בתרומה,\u0004 שמא זנתה ונפסלה. \u0003ואם מת — חולצת\u0004"],["\u0003ולא מתייבמת.\u0004 ומכאן שיש עליה זיקת ייבום, ושלא כדברי רב! ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006היה יכול \u0005לומר לך]\u0006 \u0003רב: אמינא לך אנא\u0004 \u0005[אומר לך אני]\u0006 מה שאמרתי ב\u0003סוטה\u0004 שזנתה \u0003ודאי, ואמרת לי את\u0004 \u0005[ואתה אומר לי]\u0006 ב\u0003סוטה\u0004 מ\u0003ספק!\u0004 שהרי זו שנכנסה לבית הסתר אין הוכחה שבאמת זנתה, וכיון שהיא רק ספק סוטה — לכן היא חולצת. ומקשים: \u0003ומאי שנא\u0004 \u0005[ו\u0006במה \u0005שונה]\u0006 \u0003סוטה ודאי מאי טעמא\u0004 \u0005[מה טעם] —\u0006 \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה\u0004 לשון \u0003\"טומאה\",\u0004","הלא \u0003סוטה\u0004 מ\u0003ספק נמי\u0004 \u0005[גם כן]\u0006 לשון \u0003\"טומאה\" כתיבא\u0004 \u0005[נאמרה]\u0006 \u0003בה! דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יוסי בן כיפר אומר משום\u0004 (בשם) \u0003ר' אלעזר: המחזיר גרושתו מן הנישואין,\u0004 לאחר שכבר נישאה לאחר ונתגרשה או נתאלמנה ממנו, כיון שאסרה התורה לאדם לשאת שוב את גרושתו לאחר שנישאה לאחר — \u0003אסורה\u0004 לבעלה, אולם אם היתה זו \u0003מן האירוסין\u0004 שרק נתארסה לאחר ומת — \u0003מותרת, משום שנאמר: \"\u0004לא יוכל בעלה הראשון אשר שלחה לשוב לקחתה להיות לו לאשה \u0003אחרי אשר הטמאה\"\u0004 (דברים כד, ד), וזו שרק נתארסה, הרי לא נטמאה, שכן לא היה ביניהם יחסי אישות.","\u0003וחכמים אומרים: אחת זו ואחת זו,\u0004 בין שנישאה ובין שנתארסה לאחר — \u0003אסורה\u0004 לבעלה הראשון. \u0003אלא מה אני מקיים\u0004 את דברי הכתוב \u0003\"אחרי\u0004 אשר \u0003הטמאה\" —\u0004 אין כתוב זה מדבר בעניינו, בדין אשה הנישאת לאחר כדין, שבזו אין להשתמש בלשון טומאה, אלא בא כתוב זה \u0003לרבות סוטה שנסתרה,\u0004 שעל זו נאמר שהיא אסורה לבעלה, מחשש ביאה של ניאוף. ומכל מקום נלמד מכאן לענייננו כי סוטה שנסתרה, קרויה לשיטה זו, \"טמאה\"!","ודוחים: \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"נסתרה\"\u0004 האמור כאן — כוונתו \u0003נבעלה\u0004 ודאי. \u0003ואמאי קרי ליה\u0004 \u0005[ומדוע קורא לה]\u0006 \u0003\"נסתרה\"\u0004 ולא אמר נבעלה — \u0003לישנא מעליא נקט\u0004 \u0005[לשון מעולה,\u0006 נקיה, \u0005תפס]\u0006 והכוונה היא לזו שנבעלה ממש. ותוהים: אם באשה ש\u0003נבעלה —\u0004 הלא לשון \u0003\"טומאה\" בהדיא כתיב\u0004 \u0005[במפורש נאמר]\u0006 \u0003בה,\u0004 בפרשת סוטה, ומדוע צריך ללמוד ממקור רחוק שהיא קרויה \"טמאה\", שהרי נאמר בהקשר זה \u0003\"ונסתרה והיא נטמאה\"\u0004 (במדבר ה, יג)?","ומשיבים: לימוד זה מן הכתוב \"לא יוכל... לשוב לקחתה\" אינו כדי להודיענו שהדבר קרוי \"טומאה\", אלא ללמוד מכאן הלכה \u0003למיקם עלה בלאו\u0004 \u0005[לעמוד,\u0006 לעבור, \u0005עליה ב\u0006איסור \u0005לא\u0006 תעשה\u0005],\u0006 שאם בעל בא על אשתו אחרי שנבעלה לאחר — הריהו עובר עליה בלאו. ומעירים: \u0003ור' יוסי בן כיפר\u0004 המעמיד את הפסוק במחזיר גרושתו — איסור \u0003לאו בסוטה לית ליה\u0004 \u0005[אין לו]\u0006 בכלל, שלדעתו אין הבעל עובר אם בא על אשתו שסטתה בעודה נשואה לו, \u0003ואפילו זנאי\u0004 \u0005[זנתה]\u0006 ודאי, \u0003נמי\u0004 \u0005[גם כן].\u0006","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — מפני שלדעתו הכתוב שהזכיר \"אחרי אשר הוטמאה\" אינו מדבר בסוטה, אלא באשה שנתגרשה כדין מבעלה הראשון ונישאה כדין לבעל אחר. וראיה לדבר, כי \u0003\"הויה\" ו\"אישות\" כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה,\u0004 שנאמר: \"והיתה לאיש אחר\" (דברים כד, ב), ונאמר: \"כי ימות האיש האחרון אשר לקחה לו לאשה\" (שם ג), משמע שמדובר שם ביחסים של נישואין כהלכתם. ואילו הסוטה מעולם לא \"היתה\" (כלומר, לא נישאה), שאינה יכולה להיות נשואה לאיש אחר בעודה אשת איש.","באותו נושא דנים לענייננו, \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב יהודה מרב ששת: המחזיר גרושתו משניסת\u0004 (משנישאת) לאחר \u0003ומת\u0004 בלא בנים, \u0003צרתה, מהו\u0004 לענין ייבום? \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' יוסי בן כיפר — לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 שאלה זו, \u0003כיון\u0004 ש\u0003אמר ר' יוסי בן כיפר\u0004 כי כיון ש\u0003\"טומאה\" במחזיר גרושתו הוא דכתיבא\u0004 \u0005[שנאמרה]\u0006 — הרי דין \u0003צרתה כמותה.\u0004","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה \"תועבה היא\"\u0004 (שם כד, ד) וההדגשה \"היא\" באה לצמצם את תחום האיסור ואפשר היה לפרש דווקא היא ולא צרתה, והרי מהמלה \"היא\" כבר דרשו: \u0003היא תועבה ואין בניה תועבין,\u0004 שאם בכל זאת עבר וחזר ונשאה — אין הבנים שיוולדו ממנה פסולים. אבל אין \"היא\" מצמצם את הדין מן הצרה, ומכאן: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003צרתה תועבה\u0004 היא כמותה לענין ייבום, ולכן בודאי פטורה מן הייבום.","\u0003כי תיבעי לך אליבא דרבנן\u0004 \u0005[כאשר יסתפק לך\u0006 הדבר, הרי זה \u0005על פי שיטת חכמים],\u0006 האם נאמר: \u0003אף על גב דאמור רבנן\u0004 \u0005[אף על פי שאמרו חכמים]\u0006 \u0003\"טומאה\" בסוטה הוא דכתיב\u0004 \u0005[שנאמר],\u0006 האם נאמר כי בכל זאת \u0003אין מקרא יוצא מידי פשוטו,\u0004 ואף שאמרו חכמים שההלכה בפסוק מתייחסת לענין סוטה, מכל מקום אין לעקור את פשט הכתוב לגמרי, וכיון שמדובר שם בענין מחזיר גרושתו, נלמד מכאן שיש בה טומאה,","\u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דאיעקר\u0004 \u0005[שנעקר]\u0006 הדין ממקומו — \u0003איעקר\u0004 \u0005[נעקר]\u0006 לגמרי, ואין עוד לפרשו כקשור לענין שהוא כתוב בו, אלא לענין סוטה בלבד. \u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שלא כך היתה השאלה, אלא היא נוסחה בצורה הפוכה: \u0003אליבא דרבנן\u0004 \u0005[על פי\u0006 שיטת \u0005חכמים]\u0006 \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 שאלה זו, \u0003כיון דאיתעקר\u0004 \u0005[שנעקר]\u0006 דבר ממשמעו — \u0003איעקר\u0004 \u0005[נעקר],\u0006 ולכן אין במחזיר גרושתו טומאה, לא בה ולא בצרתה.","\u0003כי תיבעי לך\u0004 \u0005[כאשר תישאל לך]\u0006 שאלה זו — הרי זה \u0003אליבא\u0004 \u0005[על פי שיטת]\u0006 \u0003ר' יוסי בן כיפר, מאי\u0004 \u0005[מה]\u0006 הדין? האם נאמר \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003אמר ר' יוסי בן כיפר\u0004 כי \u0003\"טומאה\" במחזיר גרושתו הוא דכתיבא\u0004 \u0005[שנאמרה],\u0006 יש לשאול: האם כאשר כתבה התורה \"היא\", \u0003מיעט רחמנא\u0004 \u0005[מיעטה התורה]\u0006 את צרתה, ומשמעות הכתוב: \u0003היא תועבה ואין צרתה תועבה, או דלמא\u0004 \u0005[שמא]\u0006 בא הכתוב להשמיענו כי \u0003היא תועבה ואין בניה תועבין,\u0004 ולצד הזה נדייק: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003צרתה,\u0004 בניגוד לבניה, \u0003תועבה\u0004 היא?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת: \u0003תניתוה\u0004 \u0005[למדתם אותה],\u0006 שיש לנו ראיה לדבר מן הברייתא, ששנינו בה: אם נפלו לפני אדם שתי יבמות, ו\u0003היתה אחת כשרה ואחת פסולה, אם היה חולץ — חולץ לפסולה, ואם היה מייבם — מייבם לכשרה.\u0004","ונברר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כשרה\" ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"פסולה\"\u0004 כאן? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי \u0003\"כשרה\"\u0004 כוונתו \u0003כשרה לעלמא\u0004 \u0005[בכלל]\u0006 שכשרה לכל אדם, וכן \u0003\"פסולה\" — פסולה לעלמא\u0004 \u0005[בכלל],\u0006 כגון שהיתה כבר גרושה או חללה, ואסורה לכהן, הלא אם נפרש כך שהדבר נוגע לאחרים, ולעצמו שתיהן כשרות, \u0003כיון דלדידיה חזיא\u0004 \u0005[שלעצמו,\u0006 עבורו היא \u0005ראויה] —\u0006 \u0003מאי נפקא ליה מינה\u0004 \u0005[מה יוצא לו מזה\u0006 ומה איכפת \u0005ממנה] —\u0006 אם פסולה היא או ראויה עבור אחרים?","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 צריך לפרש כך: \u0003\"כשרה\"\u0004 כוונתו — \u0003כשרה ליה\u0004 \u0005[לו,\u0006 עבורו\u0005],\u0006 \u0003\"פסולה\"\u0004 פירושו — \u0003פסולה\u0004 רק \u0003ליה\u0004 \u0005[לו,\u0006 עבורו\u0005],\u0006 \u0003ומאי ניהו\u0004 \u0005[ומה הוא],\u0006 כלומר, כיצד יכול להיות מקרה כזה שאשה תהיה כשרה או פסולה רק לו ולא לאדם אחר — הרי זה יכול להיות \u0003מחזיר גרושתו,\u0004 שאותו אח שמת החזיר את גרושתו אחרי שנישאה לאחר, ואז היא אסורה רק לייבום, אבל אין זה אוסרה על אחרים, \u0003וקתני\u0004 \u0005[ושנה]\u0006 שם: \u0003ואם היה מייבם — מייבם לכשרה.\u0004 משמע שהכשרה, שהיתה צרת גרושה שהוחזרה, ראויה אפילו לייבום!","את ההוכחה הזו דוחים: \u0003לא, לעולם\u0004 הכוונה היא \u0003\"כשרה\" — כשרה לעלמא\u0004 \u0005[בכלל],\u0006 \u0003\"פסולה\" — פסולה לעלמא\u0004 \u0005[בכלל],\u0006 כגון שהיתה גרושה. \u0003ודקאמרת\u0004 \u0005[ו\u0006מה \u0005שאמרת]\u0006 \u0003כיון דלדידיה חזיא\u0004 \u0005[שלו\u0006 עצמו היא \u0005ראויה]\u0006 כיון שהוא ישראל ואינה אסורה אלא לכהן, \u0003מאי נפקא ליה מינה\u0004 \u0005[מה יוצא לו מזה]\u0006 — הרי זה \u0003משום\u0004 מה שאמר \u0003רב יוסף.\u0004","ש\u0003אמר רב יוסף: כאן שנה,\u0004 כלומר, בהלכה זו שאמר במשנה שחולץ לפסולה, לימדנו \u0003רבי\u0004 כלל מוסרי גדול: \u0003לא ישפוך אדם מי בורו ואחרים צריכים להם.\u0004 שאל לו לאדם לקלקל דבר — אפילו הוא שלו וברשותו — אם זה עשוי להביא תועלת לאחרים. וכך גם כאן, שאם הוא חולץ אין חשיבות עבורו למי מהן הוא חולץ, אבל אם יחלוץ לכשרה נמצא שפסלה לכהונה (שדין חלוצה כדין גרושה). ומוטב שיחלוץ לזו שהיתה פסולה לכהונה בין כה וכה, ולא יקלקל את סיכויי הנישואין של האחרת.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מברייתא אחרת, ששנינו: \u0003המחזיר גרושתו משנשאת\u0004 ומת — \u0003היא וצרתה חולצת.\u0004 וקודם יש לתקן את הלשון: \u0003היא וצרתה סלקא דעתך\u0004 \u0005[עולה על דעתך]?\u0006 שהרי חולצים רק לאחת מן הנשים ולא לשתיהן! \u0003אלא אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]:\u0006 \u0003או היא או צרתה.\u0004 משמע ששתיהן אינן ראויות לייבום!","ודוחים: \u0003ולאו תרוצי קמתרצת לה\u0004 \u0005[ו\u0006כי \u0005אין אתה מיישב\u0006 ומתקן \u0005אותה]\u0006 את לשון הברייתא ואינך גורס אותה כפי שהיא?! ואם כן אין מכאן ראיה, ו\u0003תריץ הכי\u0004 \u0005[\u0006ו\u0005תקן\u0006 אותה גירסה \u0005כך]:\u0006 \u0003היא\u0004 — \u0003חולצת, צרתה — או חולצת או מתייבמת.\u0004 ואם כן, אין מכאן ראייה לפתור את בעייתו של רב יהודה.","ובאותו ענין מסופר: \u0003אמר ר' חייא בר אבא, ר' יוחנן בעי\u0004 \u0005[שאל]:\u0006 \u0003המחזיר גרושתו משניסת\u0004 (משנישאת) לאחר ומת, \u0003צרתה מהו\u0004 הדין בייבום? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אמי: ותיבעי\u0004 \u0005[ותישאל,\u0006 תסתפק\u0005]\u0006 \u0003לך היא גופה\u0004 \u0005[עצמה]!\u0006 האם היא עצמה חייבת בייבום? השיב לו: \u0003היא גופה\u0004 \u0005[עצמה]\u0006 \u0003לא קמיבעיא\u0004 \u0005[מסופקת]\u0006 \u0003לי\u0004 שודאי אסורה,","משום \u0003דאמרינן\u0004 \u0005[שאומרים אנו]\u0006 \u0003קל וחומר\u0004 כך: \u0003במותר לה,\u0004 כלומר, בעלה הראשון שהיה מותר בה עד שנישאת לאחר — \u0003אסורה\u0004 לו משום שנישאה לאחר, \u0003באסור לה,\u0004 באחי בעלה — \u0003לא כל שכן\u0004 שתהא אסורה?! \u0003כי קא מיבעיא\u0004 \u0005[כאשר נשאלה]\u0006 \u0003לי\u0004 שאלה זו, הרי זה ביחס ל\u0003צרתה, מאי\u0004 \u0005[מה]\u0006 הדין? ומה הבעיה: \u0003מי אלים\u0004 \u0005[האם תקיף,\u0006 חזק\u0005]\u0006 \u0003קל וחומר\u0004 זה שאמרנו עד כדי \u0003למידחי\u0004 \u0005[לדחות]\u0006 את ה\u0003צרה או לא?\u0004 שהרי היא עצמה נדחית מן הייבום על ידי קל וחומר! והשאלה היא, האם דחיה זו יפה כוחה עד כדי כך שתדחה גם את צרתה כמו צרת ערוה?","\u0003רב נחמן בר יצחק מתני הכי\u0004 \u0005[\u0006היה \u0005שונה\u0006 מסורת זו \u0005כך]:\u0006 \u0003אמר ר' חייא בר אבא, בעי ר' יוחנן: המחזיר גרושתו משניסת\u0004 (משנישאת) לאחר ומת, \u0003מהו\u0004 דינה בייבום? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אמי: ותיבעי\u0004 \u0005[ותישאל,\u0006 תסתפק\u0005]\u0006 \u0003לך\u0004 גם מה הדין ב\u0003צרתה?\u0004 והשיב: \u0003צרתה לא קמיבעיא\u0004 \u0005[מסופקת]\u0006 \u0003לי דלא אלים\u0004 \u0005[שאין תקיף,\u0006 חזק\u0005]\u0006 ה\u0003קל וחומר\u0004 שאמרנו \u0003למידחי\u0004 לדחות \u0003צרה\u0004 מייבום, \u0003אלא כי קמיבעיא\u0004 \u0005[כאשר נשאלה]\u0006 \u0003לי,\u0004 לא נשאלה לי אלא השאלה, \u0003היא גופה\u0004 \u0005[עצמה]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 דינה\u0005],\u0006 \u0003מי אלים\u0004 \u0005[האם תקיף,\u0006 חזק\u0005]\u0006 \u0003קל וחומר\u0004 וסומכים עליו גם \u0003במקום מצוה\u0004 של ייבום, \u0003או לא?\u0004"],["\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תניתוה\u0004 \u0005[שניתם,\u0006 למדתם, \u0005אותה\u0006 כבר\u0005]\u0006 באותה ברייתא: \u0003היתה אחת כשרה ואחת פסולה, אם היה חולץ — חולץ לפסולה, ואם היה מייבם — מייבם לכשרה.\u0004 ונברר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כשרה\" ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"פסולה\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003\"כשרה\" — כשרה לעלמא\u0004 \u0005[לעולם,\u0006 לכול\u0005],\u0006 שכשרה גם לכהן, \u0003\"פסולה\" — פסולה לעלמא\u0004 \u0005[לעולם,\u0006 לכול\u0005],\u0006 אולם \u0003כיון דלדידיה חזיא\u0004 \u0005[שלו\u0006 עצמו היא \u0005ראויה] —\u0006 \u0003מאי נפקא ליה מינה\u0004 \u0005[מה יוצא לו מזה]?\u0006 ומה איכפת לו?","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003\"כשרה\" —\u0004 שהיא \u0003כשרה ליה\u0004 \u0005[לו],\u0006 \u0003\"פסולה\" — פסולה ליה\u0004 \u0005[לו].\u0006 \u0003ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 מקרה זה שתהא אחת הנשים פסולה לו בלבד — \u0003מחזיר גרושתו. וקתני\u0004 \u0005[ושנה]:\u0006 \u0003אם היה מייבם — מייבם ל\u0004צרתה ה\u0003כשרה,\u0004 ואם כן נפתרה שאלתו של ר' יוחנן.","ודוחים: \u0003לא,\u0004 הכוונה היא: \u0003כשרה — לעלמא\u0004 \u0005[לעולם,\u0006 לכול\u0005],\u0006 \u0003פסולה — לעלמא\u0004 \u0005[לעולם,\u0006 לכול\u0005],\u0006 כגון שהיתה גרושה או חללה. \u0003ודקאמרת\u0004 \u0005[ו\u0006מה \u0005שאמרת]\u0006 \u0003כיון דלדידיה חזיא\u0004 \u0005[שלו\u0006 עצמו היא \u0005ראויה],\u0006 \u0003מאי נפקא ליה מינה\u0004 \u0005[מה יוצא לו מזה]\u0006 — יש ליישב את הדבר \u0003משום\u0004 מה שאמר \u0003רב יוסף,\u0004 ש\u0003אמר רב יוסף: כאן שנה רבי\u0004 ורמז בדברים: \u0003לא ישפוך אדם מי בורו ואחרים צריכים להם.\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מברייתא אחרת, ששנינו: \u0003המחזיר גרושתו משניסת\u0004 (משנישאת) לאחר — \u0003היא וצרתה חולצת.\u0004 וקודם נתקן את הלשון: \u0003היא וצרתה סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר? הלא ידוע וברור שאין חולצים לשתים! \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003או היא או צרתה\u0004 חולצת ולא מתייבמת, והרי זה פתרון לשאלת ר' יוחנן! ודוחים: \u0003ולאו תרוצי קא מתרצת לה\u0004 \u0005[ו\u0006כי \u0005אין אתה מיישב\u0006 ומתקן \u0005אותה]?\u0006 את לשון הברייתא? \u0003תריץ הכי\u0004 \u0005[ישב,\u0006 תקן אותה \u0005כך]:\u0006 \u0003היא\u0004 עצמה — \u0003חולצת, צרתה — או חולצת או מתייבמת.\u0004 ובאופן כזה אין מכאן ראיה לפתור את בעייתו של ר' יוחנן בשלימות.","ועוד בענין נשים הפטורות ואסורות בייבום. \u0003אמר רב לילי בר ממל, אמר מר עוקבא, אמר שמואל: צרת ממאנת אסורה.\u0004 שאם היו לאח המת שתי נשים, ואחת מהן היתה יתומה שהשיאוה אימה ואחיה בעודה קטנה ומיאנה ביבם זה, לא רק שאותה עצמה אין מייבמים, אלא אף לא את צרתה. ושואלים: \u0003למאן\u0004 \u0005[למי]\u0006 היא אסורה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיא אסורה \u0003ל\u0004שאר ה\u0003אחים\u0004 בהם לא מיאנה, \u0003השתא היא גופה שריא\u0004 \u0005[עכשיו\u0006 הרי, \u0005היא עצמה\u0006 הממאנת הזו \u0005מותרת\u0006 להם\u0005],\u0006 שהרי \u0003אמר שמואל:\u0004 יבמה קטנה ש\u0003מיאנה ב\u0004יבם \u0003זה — מותרת בזה,\u0004 באח אחר של בעלה — אם כן \u0003צרתה מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שהיא מותרת?","\u0003אלא\u0004 מה תאמר — שאסורה \u0003לדידיה\u0004 \u0005[לו],\u0006 שכיון שמיאנה בו אסורה גם היא וגם צרתה, ונברר: \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 ה\u0003ממאנת דשריא\u0004 \u0005[ש\u0006היא \u0005מותרת]\u0006 \u0003לאחין\u0004 האחרים — משום ש\u0003לא עבדא בהו\u0004 \u0005[עשתה בהם]\u0006 שום \u0003מעשה,\u0004 שהרי לא בהם מיאנה ולא בטל ממנה הייבום — \u0003צרה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא עבדא בהו\u0004 \u0005[עשתה בהם]\u0006 \u0003מעשה,\u0004 ותהא מותרת לכולם!","ומשיבים: \u0003גזרה\u0004 היא \u0003משום צרת בתו ממאנת,\u0004 שנפלה בתו לפניו לייבום בעודה קטנה ומיאנה בו, ומכיון שצרתה אסורה משום צרת בתו, אסרו גם צרה אחרת של ממאנת. ותוהים: \u0003ו\u0004בדין זה עצמו \u0003צרת בתו ממאנת מי אסירא\u0004 \u0005[האם היא אסורה]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003וכולן, אם מתו או מיאנו — צרותיהן מותרות!\u0004","ומעתה נברר: ש\u0003מיאנה במאן\u0004 \u0005[במי]\u0006 אותה קטנה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003מיאנה בבעל,\u0004 באח שמת, בעודו חי, \u0003היינו\u0004 \u0005[הרי הוא]\u0006 בדיוק כמו \u0003גרושה,\u0004 והרי למדנו באותה משנה שאם מתו או מיאנו או נתגרשו קרובותיו שהן נשואות לאח שמת — אין עוד איסור על הצרה. ומה ההבדל איפוא בין מיאון וגירושין? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה שמיאנה \u0003ביבם.\u0004 ומכאן, שאם מיאנה ביבם בטל קשר זיקת הייבום, וצרתה אינה נחשבת כצרת ערוה ויכולה להתייבם, ונמצא שאין קיים כלל איסור של צרת בתו ממאנת!","ומשיבים: \u0003לא, לעולם\u0004 תפרש שמיאנה \u0003בבעל,\u0004 אלא \u0003ותרי גווני\u0004 \u0005[ושני מיני]\u0006 \u0003גירושין\u0004 הזכירו כאן, האחד — גירושין מן התורה, והשני — מיאון שהוא מעין גירושין מדברי סופרים. ושואלים: \u0003ומאי שנא כי\u0004 \u0005[ומה שונה כאשר]\u0006 \u0003מיאנה בבעל — דעקרינהו\u0004 \u0005[שעוקרים]\u0006 בכך את ה\u0003נשואין,\u0004 שהרי המיאון איננו כגירושין שהם רק הפסקת הנישואין, אלא הוא עקירה וביטול גמור של הנישואין מתחילתם ולכן צרתה מותרת,","אם כן, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003מיאנה ביבם נמי\u0004 \u0005[גם כן]\u0006 נאמר כי ה\u0003נשואין קמאי\u0004 \u0005[הראשונים]\u0006 \u0003קא עקרא\u0004 \u0005[היא עוקרת],\u0006 שהרי אינה יכולה למאן ביבם ממש שעדיין לא נישאה לו, אלא יש לפרשו שהיא מבטלת את נישואיה הראשונים, וממילא בטל גם הקשר עם היבם, וכיון שכך, הרי זה כאילו לא היתה נשואה מעולם, ואין כאן צרה כלל!","ומסבירים: הטעם לדברי שמואל הוא \u0003משום\u0004 אותו ענין \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רמי בר\u0004 \u0005[בנו]\u0006 של \u0003יחזקאל\u0004 ברייתא, ובה מתבאר הדבר. \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רמי בר יחזקאל:\u0004 אם \u0003מיאנה בבעל — מותרת\u0004 להינשא אפילו \u0003לאביו,\u0004 שכן המיאון עוקר לגמרי את הנישואין וכאילו לא היה כל קשר קודם ביניהם. אבל אם מיאנה \u0003ביבם\u0004 ולא בבעל — \u0003אסורה לאביו.\u0004","ואנו מבינים \u0003אלמא\u0004 \u0005[מכאן],\u0006 ש\u0003משעת נפילה,\u0004 כאשר נזקקת לייבום, \u0003נראית ככלתו.\u0004 שהרי בזמן שמת הבעל עדיין לא מיאנה, והיתה נראית בעיני הכל ככלתו של האב ואף שהנישואין הללו לא היו נישואין גמורים מן התורה, אבל כך נראים הדברים בעיני הבריות, ואסרו חכמים לזו שמיאנה ביבם שלא יבואו לזלזל באיסור ערוה.","\u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 קיים טעם זה, ש\u0003משעת נפילה נראית כצרת בתו,\u0004 ולכן אסרוה, אף שהיא מותרת מעיקר הדין. וזה שאמר שמואל שצרת ממאנת אסורה, גזירה משום צרת בתו שמיאנה.","ועוד בענין נשים האסורות לשיטות שונות. \u0003אמר רב אסי: צרת אילונית אסורה.\u0004 כלומר, אם היתה אחת מן הנשים של האח שמת אילונית, אשה שאינה מסוגלת כלל ללדת, אין בה כלל דין ייבום, \u0003שנאמר\u0004 ביבמה: \u0003\"והיה הבכור אשר תלד\"\u0004 (דברים כה, ו), וממשמעות הכתוב נלמד — \u0003פרט לאילונית שאינה יולדת.\u0004 וכיון שהאילונית אינה בדין ייבום, נמצא שהיא אשת אח שאין לה היתר, האסורה משום ערוה, ולכן אף צרתה פטורה מן הייבום.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב ששת,\u0004 ממה ששנינו במשנה: \u0003שלשה אחין נשואין שלש נשים נכריות\u0004 (נשים שאינן קרובות זו לזו) \u0003ומת אחד מהם, ועשה בה\u0004 האח ה\u0003שני מאמר,\u0004 כלומר, קידש אותה לאשה. שקידושין שמקדש היבם את היבמה נקראים \"מאמר\", שאין להם תוקף קידושין גמורים (משום שהקשר בין היבם ליבמתו איננו תלוי בקידושין, אלא הוא כעין המשך של קידושיה לבעלה, ואין נישואין גמורים חלים ביבמה אלא על ידי ביאה בלבד), אלא שתיקנו חכמים משום צניעות שיעשו קידושין גם ביבמה ולא יבוא עליה בלא קידושין.","\u0003ומת\u0004 אח זה שעשה מאמר לפני שבא עליה — \u0003הרי אלו,\u0004 גם היבמה אשת האח הראשון, וגם אשתו של האח השני — שתיהן \u0003חולצות ולא מתייבמות, שנאמר: \"ומת אחד מהם יבמה יבא עליה\"\u0004 (שם ה), ואנו למדים מכאן: \u0003מי שעליה זיקת יבם אחד,\u0004 זו שחלה עליה חובת ייבום רק משום יבם אחד שמת, \u0003ולא זיקת שני יבמין.\u0004 שהרי כל עוד לא נתייבמה כדין, לא פקעה ממנה זיקתה הראשונה ומכיון שנתקדשה לשני ומת, נוספה עליה בכך זיקה נוספת והרי זה כאילו שני יבמים שצריכים תיקון, ולכן אין מייבמים אותה ואת צרתה כלל.","\u0003וקתני עלה\u0004 \u0005[ושנינו עליה]\u0006 תוספת זו: \u0003אמר רב יוסף: זו היא\u0004 דוגמה של \u0003צרת אשת אח מאב,\u0004 כלומר, יבמה גמורה שמעיקר הדין יש בה את כל הצדדים של מצות ייבום, \u0003שאיסור נפילה גרם לה.\u0004 שמה שגרם לה להיאסר איננו תלוי באיסור עצמי, אלא רק בזה שנפלה לייבום פעמיים מזיקה אחת, \u0003שלא מצינו בכל התורה כולה כגון זאת,\u0004 שמפני שחלה עליה מצוה שאינה יכולה לבוא לידי קיום ויש איסור לא רק עליה אלא גם על צרתה, ואין זאת אלא מדברי סופרים.","ונדייק בדברי רב יוסף: \u0003\"זו היא\"\u0004 ולא אחרת שאמר — \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה],\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003צרת אילונית דשריא\u0004 \u0005[ש\u0006היא \u0005מותרת],\u0006 שהרי גם האילונית כשלעצמה מותרת להינשא לכל אדם, אלא שאינה ראויה לייבום, ומדיוק הדברים נלמד שרק זו שיש עליה זיקות משני יבמים, היא שאוסרת צרתה, ואין עוד כיוצא בה.","ודוחים: \u0003לא,\u0004 הכוונה במאמרו זה של רב יוסף היתה \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003צרת אילונית דאסירא\u0004 \u0005[ש\u0006היא \u0005אסורה],\u0006 \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"זו היא\" —\u0004 כך יש לדייק: \u0003זו היא\u0004 ש\u0003איסור נפילה\u0004 בלבד הוא \u0003שגרם לה\u0004 להיאסר ולכן \u0003צרתה בעיא\u0004 \u0005[צריכה]\u0006 על כל פנים \u0003חליצה\u0004 ואיננה נפטרת לגמרי, מה שאין כן צרת \u0003אילונית,\u0004 ש\u0003אפילו חליצה לא בעיא\u0004 \u0005[אינה צריכה].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל ביניהם — \u0003הא\u0004 \u0005[זו],\u0006 האילונית פטורה מייבום \u0003דאורייתא\u0004 \u0005[\u0006מן \u0005התורה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 שעשה בה אח אחר מאמר אסורה רק \u0003דרבנן\u0004 \u0005[\u0006מדברי \u0005סופרים]\u0006 ומשום כך חולצת.","ומנסים להביא ראיה אחרת, לסתור: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003וכולן,\u0004 כל אותן עריות, \u0003אם מתו או מיאנו, או נתגרשו, או שנמצאו אילונית — צרותיהן מותרות.\u0004 ולכאורה זה היפך דברי רב אסי שאמר שצרת האילונית אסורה! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן,\u0004 בדברי רב אסי, מדובר \u0003שהכיר בה\u0004 בעלה כשנשא אותה וידע שהיא אילונית, וכיון שנשא אותה למרות זאת, היו נישואיה נישואין גמורים. והואיל שמצות ייבום לא חלה עליה משום שאינה מסוגלת ללדת — לכן גם צרתה פטורה.","ו\u0003כאן\u0004 במשנתנו מדובר \u0003שלא הכיר בה\u0004 בשעת נישואין אלא נתברר לאחר מכן שהיא אילונית, ואפשר לומר שמתוך שאין אדם רוצה לשאת אשה אילונית, היו הקידושין איפוא קידושי טעות, ובטלים מעיקרם, לכן צרתה מותרת.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 לפרש כך מלשון המשנה, \u0003דקתני\u0004 \u0005[ששנה\u0006 בה\u0005]\u0006 \u0003\"שנמצאו\u0004 אילונית\u0003\", ולא קתני\u0004 \u0005[שנה]\u0006 \u0003\"שהיו\u0004 אילוניות\u0003\",\u0004 משמע שהדבר לא היה ידוע בשעת נישואין, אלא נודע לאחר מכן. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך צריך להבין את משנתנו. ומכל מקום אין כאן סתירה לדברי רב אסי. \u0003אמר רבא:\u0004"],["\u0003הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 \u0003צרת אילונית מותרת, ואפילו הכיר בה\u0004 בעלה הראשון לפני שנשאה שהיא אילונית וקידושיו היו קידושין גמורים, מכל מקום אין מצות ייבום באילונית, אבל על צרתה אין איסור. \u0003ואפילו צרת בתו אילונית\u0004 שהכיר בה, ואין אנחנו חוששים כאן משום צרת ערוה.","ושואלים: \u0003ואלא הא דקתני\u0004 \u0005[זו ששנה]\u0006 \u0003\"שנמצאו\u0004 אילונית\u0003\",\u0004 ומכאן דייקנו שיש הבדל בין הכיר בה ובין לא הכיר בה — \u0003תני\u0004 \u0005[שנה]\u0006 ותקן \u0003\"שהיו\"\u0004 ולא \"שנמצאו\". \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: אחת צרת ממאנת, ואחת צרת אילונית, ואחת צרת מחזיר גרושתו — כולן מותרות\u0004 ובניגוד לשיטות אלה שאסרו אותן.","אגב הדיון במשנתנו במיאון, מביאים הלכה הנוגעת לענין זה מצד אחר. \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב ביבי קמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן\u0004 ברייתא זו: \u0003שלש נשים משמשות במוך\u0004 (אריג רך) שהן מכניסות בצוואר הרחם, כדי שלא תתעברנה, ואף שבדרך כלל דבר זה אסור, התירו במקרים אלה, ואלו הן: \u0003קטנה, מעוברת, ומניקה.\u0004 וטעמם של הדברים: \u0003קטנה — שמא תתעבר ושמא תמות\u0004 בהריון או בלידה. \u0003מעוברת — שמא\u0004 תגיע להריון שני ו\u0003תעשה עוברה סנדל,\u0004 שעובר אחד יפריע לשני וימעך אותו. \u0003מניקה — שמא\u0004 תתעבר ואז ייפסק אצלה החלב, ו\u0003תגמול\u0004 את \u0003בנה\u0004 מלינוק לפני זמנו, \u0003וימות.\u0004","\u0003ואיזו היא קטנה — מבת אחת עשרה שנה ויום אחד עד שתים עשרה שנה ויום אחד,\u0004 שיש לחשוש שמא תתעבר ותסתכן. \u0003פחות מכאן\u0004 (מגיל זה) \u0003ויתר על כן — משמשת כדרכה והולכת\u0004 (בלא מוך), שכן בפחות מגיל אחת עשרה ודאי לא תתעבר וביותר מגיל שתים עשרה אין בכך סיכון בריאותי, אלו \u0003דברי ר' מאיר. וחכמים אומרים: אחת זו ואחת זו משמשת כדרכה והולכת, ומן השמים ירחמו\u0004 שלא יקרה אסון בדבר, \u0003משום שנאמר: \"שמר פתאים ה'\"\u0004 (תהלים קטז, ב).","ומדייקים בלשון, \u0003מדקאמר\u0004 \u0005[מ\u0006מה \u0005שאמר]\u0006 בברייתא \u0003שמא תתעבר ושמא תמות, מכלל\u0004 הדברים אתה למד \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003קטנה דמיעברא\u0004 \u0005[שמתעברת]\u0006 \u0003ולא מתה\u0004 אף שדבר זה אינו ברור, ויש חשש סכנה. ו\u0003אם כן,\u0004 כיון שיש אפשרות שקטנה תתעבר ותלד, \u0003מצינו חמותו ממאנת.\u0004 שהרי אפשר שאשה תלד בת בקטנותה, ואביה יקדש את הבת הזאת לאחר בעודה תינוקת ובתוך כך תמאן האם בבעלה, וייתכן איפוא מצב של \"חמות ממאנת\",","\u0003ותנן\u0004 \u0005[ו\u0006הרי \u0005שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003אי אתה יכול לומר בחמותו ואם חמותו ואם חמיו שנמצאו אילונית או שמיאנו,\u0004 שכן ממאנת היא קטנה שאינה יכולה ללדת, ואם כן יש סתירה בין הברייתא למשנה! ומתרצים: \u0003אימא\u0004 \u0005[אמור\u0006 כך\u0005]:\u0006 לא \"שמא תתעבר ושמא תמות\", שמלשון זו מובן לא ברור אם תמות כתוצאה מעיבורה, אלא: \u0003שמא תתעבר ותמות,\u0004 שאמנם ספק אם תתעבר, אבל אם תתעבר ודאי תמות ואין איפוא במציאות קטנה יולדת.","ש\u0003אמר רבה בר ליואי: גבול יש לה\u0004 לילדה לענין הריון, \u0003קודם הזמן הזה\u0004 לפני גיל אחת עשרה — \u0003אינה מתעברת כל עיקר, תוך הזמן הזה\u0004 מגיל אחת עשרה עד שתים עשרה — \u0003היא מתה ועוברה מת, לאחר הזמן הזה\u0004 משתים עשרה ומעלה — \u0003היא חיה ועוברה חי.\u0004","ומקשים: \u0003איני\u0004 \u0005[האמנם כן הוא]?\u0006 \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003רבה בר שמואל: אי אתה יכול לומר בחמותו ואם חמותו ואם חמיו שנמצאו אילונית או שמיאנו — שכבר ילדו.\u0004 משמע שקטנה מסוגלת ללדת, שאם לא כן לא היה צריך לומר \"שכבר ילדו\", אלא לומר \"שכבר גדלו\"! \u0003אלא לעולם\u0004 יש לחזור לגירסת הברייתא המקורית: \u0003שמא תתעבר ושמא תמות. ואלא קשיא הך\u0004 \u0005[קשה זו]\u0006 משנתנו, שלכאורה משמע מלשונה שאין דבר כזה אפשרי!","\u0003אמר רב ספרא:\u0004 צריך לומר, \u0003בנים הרי הם כסימנים.\u0004 כלומר, אשה שכבר ילדה אי אפשר לדונה עוד כקטנה, שהרי הגדרת הבוגרת נקבעת בדרך כלל על פי \"סימנים\" (שערות במקום הערוה), אבל אם ילדה בנים — הרי הם הוכחה לבגרות כמו הסימנים. \u0003ואית דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003בנים עדיפי\u0004 \u0005[עדיפים]\u0006 \u0003מסימנים\u0004 של בגרות. ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 אם הם כמו סימנים או עדיפים מסימנים? ומשיבים: ההבדל הוא ש\u0003אפילו ל\u0004שיטת \u0003ר' יהודה\u0004 ש\u0003אמר\u0004 שלא רק קטנה ממש ממאנת, אלא גם משהביאה שתי שערות, יש עוד זמן מסויים \u0003עד\u0004 הזמן שירבו כל כך השערות, \u0003שירבה\u0004 השער \u0003השחור\u0004 על העור הלבן, מכל מקום \u0003בבנים מודה,\u0004 שהם עדיפים מסימנים, ואם ילדה הריהי נחשבת גדולה, ואיננה יכולה עוד למאן."],["\u0003ורב זביד אמר,\u0004 כך צריך לומר: \u0003אין בנים בלא סימנים.\u0004 שאם יש לאשה בנים — ודאי היו לה כבר סימנים. ושואלים: אם כן, \u0003ונבדוק\u0004 אם יש סימנים ולא נזדקק לחזקה זו! ומשיבים: \u0003חיישינן שמא נשרו\u0004 הסימנים (השערות) הללו. ומעירים: \u0003הניחא למאן\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי]\u0006 ש\u0003אמר\u0004 כי \u0003חוששין\u0004 שמא נשרו הסימנים, שיש מקרים שאנחנו חוששים שמא כבר גדולה היא, אלא שהסימנים — השערות — נשרו.","\u0003אלא למאן\u0004 \u0005[ל\u0006שיטת \u0005מי]\u0006 ש\u0003אמר\u0004 כי \u0003אין חוששין\u0004 ואם יש בה שערות ודאי יימצאו, ולא נשרו. \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003אפילו למאן\u0004 \u0005[ל\u0006שיטת \u0005מי]\u0006 ש\u0003אמר\u0004 שכרגיל \u0003אין חוששין\u0004 שנשרו שערות אלה — \u0003משום צער\u0004 ה\u0003לידה\u0004 וכל הכרוך בכך \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 שנשרו, ואי אפשר לבדוק את הדבר היטב.","וחוזרים לביאור משנתנו. שנינו במשנה: \u0003כיצד פוטרות צרותיהן\u0004 וצרות צרותיהן. ושואלים: \u0003מנהני מילי\u0004 \u0005[מניין הדברים הללו]\u0006 שלא רק הצרה נפטרת אלא גם צרת צרה? \u0003אמר רב יהודה:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004ואשה אל אחותה לא תקח \u0003לצרר\"\u0004 (ויקרא יח, יח), ולשון \"לצרור\" (ולא \"לצור\") מלמדת על כך ש\u0003התורה ריבתה צרות הרבה.\u0004 כלומר, לא רק את צרתה של האסורה משום ערוה אלא גם צרה של צרה.","\u0003רב אשי אמר: סברא היא\u0004 זו, ואין צורך לכך בלימוד מן הכתוב, וכך יש לומר: \u0003צרה\u0004 של ערוה \u0003מאי טעמא אסירא\u0004 \u0005[מה טעם אסורה]\u0006 — כיון ש\u0003במקום ערוה קיימא\u0004 \u0005[\u0006היא \u0005עומדת],\u0006 שכיון שהערוה פטרה אותה מן הייבום ואף אסרה אותה על היבם, הרי גם היא נעשית ערוה באיסור אשת אח, ולכן \u0003צרת צרה נמי\u0004 \u0005[גם כן]\u0006 \u0003במקום ערוה קיימא\u0004 \u0005[\u0006היא \u0005עומדת],\u0006 שאף היא כצרת ערוה, ונאסרת.","שנינו במשנה: \u0003כיצד,\u0004 באיזה אופן, תהיינה צרות ערוה מותרות — \u0003אם מתו הן\u0004 הקרובות, או אם מיאנו או אם נתגרשו, מאותה שעה ואילך שוב אין הצרה נחשבת כצרת ערוה. ומעירים: דין זה נאמר בהכללה, \u0003ואפילו\u0004 במקרה כאשר \u0003כנס\u0004 האח שמת את הצרה בעוד קרובת אחיו נשואה לו, \u0003ולבסוף גירש\u0004 את הקרובה, שבמשך זמן מסויים היו שתי הנשים בפועל צרות זו לזו — גם במקרה זה בטל איסור צרת ערוה, ומותרת הצרה להתייבם.","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו במשנה אחרת: \u0003שלשה אחים, שנים מהן נשואים שתי אחיות, ואחד נשוי נכרית\u0004 (אשה זרה להן), \u0003גירש אחד מבעלי אחיות\u0004 את \u0003אשתו, ומת הנשוי נכרית ו\u0004אחר כך \u0003כנסה המגרש\u0004 את הנכרית על ידי ייבום, \u0003ו\u0004אחר כך \u0003מת\u0004 גם הוא, ונופלת האשה שוב לייבום לפני האח הנותר, הנשוי לאחת האחיות, \u0003זו היא שאמרו: \"שאם מתו או נתגרשו\" — צרותיהן מותרות.\u0004","ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום ש\u0003גירש\u0004 אותו יבם קודם את האחות, \u0003ואחר כך כנס\u0004 את הנכרית, ונמצא שנכרית זו מעולם לא היתה בפועל צרתה של האחות (אף ששתיהן היו, בזמנים שונים, נשואות לאותו אדם), \u0003אבל\u0004 אם \u0003כנס\u0004 היבם את הנכרית \u0003ואחר כך גירש\u0004 את האחות, ונמצא שבזמן מסויים היו הנכרית והאחות צרות — \u0003לא\u0004 תהא ראויה לייבום, משום שהיתה במשך זמן מסויים צרת ערוה. והרי מזה סתירה למה שמובן ממשנתנו!","\u0003אמר ר' ירמיה: תברא\u0004 \u0005[שבורה],\u0006 יש שבר, חוסר התאמה, בין המשניות, ויש לומר ש\u0003מי ששנה\u0004 משנה \u0003זו לא שנה\u0004 משנה \u0003זו,\u0004 שהמשנה שלנו והמשנה שציטטנו לגבי שלושה אחים אינן לפי אותה שיטה. וטעם ההבדל בשיטות הוא — כי \u0003האי תנא סבר\u0004 \u0005[תנא זה\u0006 של משנתנו \u0005סבור]\u0006 כי \u0003מיתה מפלת,\u0004 כלומר, הזמן הקובע לגבי קשר הייבום, הן לחיוב והן לפטור, הוא זמן מיתתו של האח בלא בנים. ובמקרה של משנתנו, כיון שבזמן מותו לא היתה אשתו צרתה של ערוה — ממילא לא חל עליה איסור אף שבזמן מסויים אכן היו הן צרות.","\u0003והאי תנא סבר\u0004 \u0005[ותנא זה\u0006 של שלושה אחים \u0005סבור]\u0006 כי \u0003נשואין הראשונים מפילים,\u0004 כלומר, זמן הנישואים — הוא היוצר את זיקת הייבום, וכיון שהאשה השניה היתה בזמן מסויים צרת ערוה, הרי נוצר אז פטור מהייבום.","\u0003רבא אמר: לעולם\u0004 אפשר לומר כי שתי המשניות, שיטת \u0003חד תנא\u0004 \u0005[תנא אחד]\u0006 \u0003הוא,\u0004 וסברה אחת היא. אלא שהתנא שבמשנה בסגנון של \u0003\"זו ואין צריך לומר זו\" קתני\u0004 \u0005[שנה\u0006 אותה\u0005],\u0006 כלומר, משנתנו מדברת במקרה של כנס ואחר כך גירש, ובמשנה של שלושה אחים, שזה המקרה הפשוט יותר (\"אין צריך לומר\"), מדובר כאשר גירש ואחר כך כנס, שהיא בודאי מותרת, ואין כאן סתירה, אלא סגנונות שונים.","שנינו במשנתנו: \u0003וכל\u0004 יבמה שהיתה ערוה עליו והיא קטנה \u0003שיכולה למאן\u0004 ולא מיאנה — צרתה חולצת ולא מתייבמת. ושואלים: \u0003ותמאן\u0004 הקטנה \u0003השתא\u0004 \u0005[עכשיו]\u0006 לאחר מות הבעל ויופקע קשר הנישואין מעיקרו \u0003ותתייבם\u0004 הצרה! וכיון שאין עושים כן \u0003לימא מסייעא ליה\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005מסייע לו\u0006 הדבר\u0005]\u0006 \u0003לר' אושעיא.\u0004","ש\u0003אמר ר' אושעיא: ממאנת\u0004 יבמה קטנה \u0003למאמרו\u0004 (קידושי כסף) של היבם, שאם קידשה היבם יכולה היא לומר שאיננה רוצה בו, ועל ידי זה מופקע הקשר שביניהם, \u0003ואינה ממאנת לזיקתו,\u0004 שכל עוד לא עשה בה מאמר, אין היבמה הקטנה יכולה לבטל את הקשר ביניהם במיאון, לפי שהקשר ביניהם איננו כקשר נישואין, ומיאון לא הותקן אלא לבטל קשר נישואין בלבד, ולכן איננה יכולה לבטלו. ולפי שיטה זו מובן מדוע היבמה, שהיא ערוה וקטנה, אינה יכולה למאן כדי שיוכלו לייבם את צרתה.","ודוחים: \u0003לא,\u0004 אפשר לומר שיבמה יכולה למאן גם לזיקה, אלא \u0003צרת ערוה שאני\u0004 \u0005[שונה]\u0006 שאין מתירים אותה גם אם היתה יכולה הערוה למאן, ומדוע? \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רמי בר יחזקאל\u0004 ברייתא זו: אם \u0003מיאנה בבעל\u0004 ועקרה על ידי כך את הנישואין — \u0003מותרת לאביו,\u0004 שהרי הופקע קשר הנישואין מעיקרו, ואיננה נחשבת כלתו כלל. אבל אם \u0003מיאנה\u0004 רק \u0003ביבם — אסורה לאביו.\u0004","וטעמו של דבר, \u0003אלמא\u0004 \u0005[מכאן],\u0006 ש\u0003משעת נפילה נראית ככלתו.\u0004 שמאותה שעה שבה נפלה לייבום נחשבת היא כקשורה בדרך זיקה לבן, ונראית בעיני הכל ככלתו של האב, ולכן אסרוה לאביו. \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 בצרת ערוה, יש לומר: \u0003משעת נפילה נראית כצרת בתו,\u0004 וכיון שהדבר נראה כך בעיני הבריות שוב לא התירו אותה חכמים על ידי מיאון שלאחר מעשה.","\u0003שש עריות\u0004 שלא נמנו במשנה הראשונה הן \u0003חמורות מאלו\u0004 שמנינו כבר, \u0003מפני שנשואות לאחרים\u0004 ולא לאחים, שהן בדרגת קירבה כזו שלעולם לא יתכן שתהיינה נשואות לאחד מן האחים מן האב. אלא שבעקבות חומרה זו באה גם הקלה, שכיון שאין דין ייבום חל עליהן כלל, משום כך \u0003צרותיהן מותרות.\u0004 שאין צרת ערוה אסורה אלא במקום מצוה של ייבום, ושלא במקום מצוה לא חל כלל איסור צרת ערוה.","ואלו הן: \u0003אמו,\u0004 שאסורה לא רק עליו, אלא גם על כל אחד מבני אביו אף שאינם בניה, \u0003ואשת אביו, ואחות אביו\u0004 שאסורה לכל הבנים מאותה סיבה, וכן \u0003אחותו מאביו\u0004 שהיא אחות מאב גם לשאר אחיו מן האב, \u0003ואשת אחי אביו, ו\u0004כן \u0003אשת אחיו מאביו\u0004 כשלאותו אח יש בנים, שאיסורן של כל אלה שווה לגבי כל האחים, ואין כאן דין ייבום, ולכן הצרה מותרת. עד כאן היתה במשנה (ובגמרא) ההנחה, שלא רק הערוה איננה יכולה להתייבם אלא גם צרתה פטורה מן הייבום.","ולאמיתו של דבר יש בכך מחלוקת קדומה, ש\u0003בית שמאי מתירין הצרות לאחים.\u0004 כיון שאינם דורשים כלל אותן דרשות שעל פיהן נאסרו הצרות. \u0003ובית הלל אוסרים,\u0004 כפי ששנינו במשניות הקודמות, שהן לדעת בית הלל."],["\u0003חלצו\u0004 הצרות מן האחים — \u0003בית שמאי פוסלין מן הכהונה,\u0004 כיון שלדעתם הצרות ראויות לייבום, ועל כן חליצתן היתה חליצה גמורה, וככל שאר החלוצות הרי הן פסולות לכהונה כגרושות. \u0003ובית הלל מכשירין,\u0004 שלדעתם לא היתה כאן חליצה בעלת משמעות וכאילו לא נחלצו כלל. אם \u0003נתייבמו\u0004 הצרות — \u0003בית שמאי מכשירין\u0004 אותן לכהונה, שלדעתם הרי זה ייבום כדינו. \u0003ובית הלל פוסלין,\u0004 משום ביאת איסור של צרת ערוה.","ומעירים: \u0003אף על פי שאלו אוסרים ואלו מתירין, אלו פוסלין ואלו מכשירין — לא נמנעו בית שמאי מלישא נשים מבית הלל, ולא בית הלל מבית שמאי,\u0004 אף על פי שלשיטת בית הלל, בני צרות ערוה שנתייבמו, ממזרים הם. ועוד: \u0003כל הטהרות והטמאות\u0004 שנחלקו ביחס להם בית שמאי ובית הלל בהלכה, \u0003שהיו אלו מטהרין ואלו מטמאין — לא נמנעו\u0004 מלהיות \u0003עושין טהרות אלו על גבי\u0004 (על ידי, בעזרת) \u0003אלו,\u0004 שהיו שואלים כלים אלו מאלו.","\u0003אמר ר' שמעון בן פזי: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003בית שמאי — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא תהיה אשת המת החוצה לאיש זר\"\u0004 (דברים כה, ה), וכיון שנאמר \u0003\"חוצה\",\u0004 יש להבינה במשמעות: החיצונה, ולדייק: \u0003מכלל\u0004 הדברים אתה למד \u0003דאיכא\u0004 \u0005[שיש]\u0006 גם אחת מנשי האח המת שהיא \u0003פנימית,\u0004 כלומר, קרובת משפחה של היבם, שהיא מתוך משפחתו \u0003ואמר רחמנא\u0004 \u0005[ואמרה התורה]\u0006 \u0003\"לא תהיה...\u0004 לאיש זר\u0003\".\u0004 כלומר, שזו שהיא \"חוצה\" ליבם, שאינה מתוך משפחתו, חייבת בייבום.","\u0003ו\u0004אילו \u0003בית הלל — מיבעי להו\u0004 \u0005[צריך להם]\u0006 כתוב זה \u0003לכ\u0004 מו שאמר \u0003רב יהודה אמר רב.\u0004 ש\u0003אמר רב יהודה אמר רב: מנין שאין קידושין תופסין ביבמה\u0004 שלא חלצה, שאם קידש אותה אחר (שאינו היבם שלה), אין הקידושין תופסים כלל — \u0003שנאמר: \"לא תהיה אשת המת החוצה לאיש זר\",\u0004 לומר: \u0003לא תהיה בה הויה לזר,\u0004 שההויה, הקידושין, לא יחולו כלל כאשר מקדשה איש זר.","\u0003ובית שמאי\u0004 טוענים כנגד זה: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"לחוץ\",\u0004 שמשמעו לאיש זר? \u0003\"חוצה\" כתיב\u0004 \u0005[נאמר],\u0006 והוא שם תואר שפירושו כמו חיצונה. \u0003ובית הלל\u0004 סבורים: \u0003כיון דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"חוצה\"\u0004 הרי זה \u0003כמאן דכתיב\u0004 \u0005[כמו שנאמר]\u0006 \u0003\"לחוץ\" דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' נחמיה אומר\u0004 כלל: \u0003כל תיבה\u0004 (מלה) \u0003שצריכה\u0004 להבנת משמעותה שתהיה האות \u0003למ\"ד בתחלתה,\u0004 לפעמים \u0003הטיל לה הכתוב\u0004 במקום זה את האות \u0003ה\"א בסופה,\u0004 ומשמעותן שווה לגמרי. \u0003ותנא דבי\u0004 \u0005[ושנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: כגון\u0004 המלה \u0003\"אלים\"\u0004 (שמות טז, א) שנקט הכתוב מאוחר יותר בלשון \u0003\"אילמה\"\u0004 (שם טו, כז), וכן \u0003\"מחנים\"\u0004 (מלכים א' ב, ח) — \u0003\"מחנימה\"\u0004 (שמואל ב' יז, כד), \u0003\"מצרים\"\u0004 — \u0003\"מצרימה\"\u0004 (בראשית יב, י), \"דבלתיים\" — \u0003\"דבלתימה\"\u0004 (במדבר לג, מו), \"ירושלים\" — \u0003\"ירושלימה\"\u0004 (יחזקאל ח, ג), \"מדבר\" — \u0003\"מדברה\"\u0004 (יהושע יח, יב), שכל אלה מילים שה\"א בסופן פירושן כאילו היתה למ\"ד בתחילתן.","ושואלים: \u0003ובית שמאי,\u0004 הלכה זו של \u0003רב יהודה אמר רב\u0004 שאין קידושי זר תופסים ביבמה לפני שחלצה, \u0003מנא להו\u0004 \u0005[מניין להם]?\u0006 ומשיבים: \u0003מ\"לאיש זר\" נפקא\u0004 \u0005[יוצא]\u0006 הדבר, שמשמעות הדברים לשיטה זו, שאין הוויה של נישואין חלה לגבי איש זר, ומן המלה \"החוצה\" למדים הם דבר אחר.","ושואלים: אם כן, \u0003ובית הלל נמי תיפוק להו\u0004 \u0005[גם כן תצא להם]\u0006 הלכה זו \u0003מ\"לאיש זר\"?\u0004 ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן\u0006 הוא \u0005גם כן]\u0006 ואף הם למדים מכאן. אלא אם כן המלה \u0003\"חוצה\" למה לי,\u0004 ולמה נאמרה — \u0003לרבות\u0004 את \u0003הארוסה.\u0004 שאף הארוסה שעדיין לא נישאה לאח שמת והיא עדיין מחוץ לביתו — גם היא חייבת בייבום.","\u0003ואידך\u0004 \u0005[והאחר,\u0006 בית שמאי\u0005]\u0006 — למדים הם הלכה זו מייתור האות, \u0003מ\u0004מה שנאמר במקום \u0003\"חוצה\" — \"החוצה\". ואידך\u0004 \u0005[והאחר,\u0006 בית הלל\u0005] —\u0006 ההבדל בין \u0003\"חוצה\"\u0004 ל\u0003\"החוצה\" לא משמע להו\u0004 \u0005[אינו משמיע,\u0006 מלמד, \u0005להם],\u0006 אינם סבורים שאפשר ללמוד מצורה לשונית זו.","\u0003רבא אמר: טעמייהו\u0004 \u0005[טעמם]\u0006 של \u0003בית שמאי\u0004 אינו מן הכתוב, אלא על סמך הנחה הלכתית ידועה: ש\u0003אין איסור חל על איסור,\u0004 שכיון שאשה זו נאסרה על היבם עוד בחיי אחיו מדין אשת אח, לא יחול עליה עוד איסור אחות אשה או כל איסור ערוה אחר, ומתוך שאין כאן איסור ערוה, אין לפטור את צרתה.","ומקשים: \u0003תינח היכא\u0004 \u0005[נניח\u0006 שדבר זה נכון \u0005במקום]\u0006 ש\u0003נשא\u0004 קודם האח ה\u0003מת\u0004 אחות אחת, \u0003ואחר כך נשא\u0004 האח ה\u0003חי\u0004 את אחותה, שאז אפשר לומר כי \u0003לא אתי\u0004 \u0005[בא]\u0006 \u0003איסור אחות אשה וחייל\u0004 \u0005[וחל]\u0006 על \u0003איסור אשת אח. אלא\u0004 כאשר \u0003נשא\u0004 האח ה\u0003חי\u0004 אחות אחת \u0003ואחר כך נשא\u0004 זה ש\u0003מת\u0004 אחות אחרת, הלא איסור \u0003אחות אשה קדים\u0004 \u0005[קדם,\u0006 הקדים\u0005]!\u0006 ואם כן יש בה רק איסור זה, ולא איסור אשת אח, ותפטור איפוא את צרתה?","ומשיבים: \u0003כיון\u0004 שכך, ש\u0003לא אתי\u0004 \u0005[בא]\u0006 \u0003איסור אשת אח וחייל\u0004 \u0005[וחל]\u0006 על \u0003איסור אחות אשה,\u0004 יש לומר שלא חל עליה כלל דין אשת אחיו, ואינה נחשבת כלל כיבמתו, \u0003והויא לה\u0004 \u0005[והרי היא]\u0006 הצרה, לפי זה, \u0003צרת ערוה שלא במקום מצוה, ו\u0004צרה כזו \u0003שריא\u0004 \u0005[מותרת]\u0006 לגמרי.","שנינו במשנה: \u0003חלצו — בית שמאי פוסלים\u0004 אותן מלהנשא לכהן. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שהוא כך, שאם יש בצרות מצות ייבום, אם חלצו להן — דינן כשאר חלוצות!","ומשיבים, כי זה בא \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 מדברי \u0003ר' יוחנן בן נורי,\u0004 ש\u0003אמר: בואו ונתקן להם לצרות\u0004 של עריות \u0003שיהו חולצות ולא מתייבמות.\u0004 שאם היו מתקנים תקנה קבועה כזו, היו צרות אלה נפסלות (מגזירת חכמים) אף לבית הלל כשאר חלוצות, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיעה לנו\u0006 המשנה\u0005]\u0006 ש\u0003בית הלל מכשירים\u0004 לגמרי, שלא תיקנו לשיטתם חליצה בצרות ערוה, ולכן אין להחשיב כלל חליצה כזו.","שנינו במשנה: אם \u0003נתייבמו\u0004 — בית שמאי מכשירין ו\u0003בית הלל פוסלין.\u0004 ושואלים: \u0003הא תו\u0004 \u0005[זו עוד]\u0006 \u0003למה לי,\u0004 שהרי אף דבר זה נובע ממה שאמרנו קודם לכן לגבי חליצה! ומשיבים: \u0003איידי דתנא\u0004 \u0005[מתוך ששנה\u0006 במשנה\u0005]\u0006 מחלוקת בהלכה ביחס ל\u0003חלצו, תנא נמי\u0004 \u0005[שנה גם כן]\u0006 ביחס ל\u0003נתייבמו\u0004 אף שאינו נחוץ ואפשר היה להבינו מן הענין.","מתוך שנגענו כאן במחלוקת בית שמאי ובית הלל, ואף הוספנו דברים כיצד היו נוהגים זה בזה, דנים בשאלת המחלוקת בכללה. \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]\u0006 במסכת מגילה: \u0003מגילה נקראת באחד עשר,\u0004 או \u0003בשנים עשר,\u0004 או \u0003בשלשה עשר,\u0004 או \u0003בארבעה עשר,\u0004 או \u0003בחמשה עשר\u0004 באדר בערים המוקפות חומה, \u0003לא פחות ולא יותר.\u0004 בארבעה עשר ובחמישה עשר — הוא כפי שנאמר במפורש במגילת אסתר, ואת הימים הנוספים לקריאת המגילה תיקנו חכמים עבור אנשי הכפרים שאינם בקיאים בקריאת המגילה ובאים לעיר כדי לשומעה, וכיון שממילא באים הם לעיר בימי שני וחמישי כדי לעסוק בהספקת מים ומזון לבני הכרכים, לכך תיקנו שאם יצא אחד מן התאריכים הללו ביום שני או חמישי, שייצאו בקריאתה בו ביום, כדי שלא להטריחם לבוא לעיר פעם נוספת לצורך קריאת המגילה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש לר' יוחנן:\u0004 מדוע לא \u0003איקרי\u0004 \u0005[אקרא]\u0006 \u0003כאן,\u0004 כלומר, לא אדון בענין זה את הכתוב \u0003\"לא תתגדדו\"\u0004 (דברים יד, א) שפירשוהו: \u0003לא תעשו אגודות אגודות,\u0004 אלא על כל ישראל להיות כיחידה אחת, ולא להיעשות חבורות חבורות הנוהגות בדרכים שונות. לפני בירור השאלה העיקרית, שואלים: הרי \u0003האי\u0004 \u0005[\u0006הכתוב \u0005הזה]\u0006 \u0003\"לא תתגדדו\" מיבעי ליה לגופיה\u0004 \u0005[נצרך\u0006 הוא \u0005לו לגופו\u0006 של מקרא\u0005],\u0006 \u0003דאמר רחמנא\u0004 \u0005[שאמרה התורה]\u0006 כפשט הדברים במקרא: \u0003לא תעשו חבורה\u0004 כאות אבילות \u0003על מת,\u0004 שהוא איסור גדידה!","ומשיבים: \u0003אם כן\u0004 שלזה בלבד היתה הכוונה, \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 בלשון \u0003\"לא תגדדו\", מאי\u0004 \u0005[מהו]\u0006 לשון \u0003\"לא תתגדדו\" — שמע מינה להכי\u0004 \u0005[למד מכאן\u0006 ש\u0005לכך]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 ללמוד מכאן גם איסור עשיית אגודות אגודות. ושואלים: אם כך אנו מפרשים, \u0003ואימא כוליה להכי\u0004 \u0005[ואמור\u0006 שפסוק זה \u0005כולו לכך]\u0006 \u0003הוא דאתא\u0004 \u0005[שבא]\u0006 ולא לאסור בעשיית חבורה! ומשיבים: \u0003אם כן, לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003\"לא תגודו\", מאי\u0004 \u0005[מהו]\u0006 לשון \u0003\"לא תתגדדו\" — שמע מינה תרתי\u0004 \u0005[למד מכאן שני\u0006 דברים\u0005],\u0006 הן לעניינו כפשוטו, איסור עשיית חבורה על מת, והן לענין אגודות אגודות.","פירשנו בדרך אגב את הכתוב, אך עדיין עומדים אנו בשאלתו של ריש לקיש: מדוע אין אומרים שקריאת המגילה במקומות ובזמנים שונים יש בכך משום עשיית אגודות אגודות?! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: וכי \u0003עד כאן לא שנית\u0004 כי ב\u0003מקום שנהגו לעשות מלאכה בערבי פסחים עד חצות\u0004 היום — \u0003עושין, מקום שנהגו שלא לעשות — אין עושין.\u0004 משמע שיש מקום למנהגים שונים, ואין אומרים שיש בשינוי מנהג משום \"לא תתגודדו\".","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמינא לך אנא איסורא\u0004 \u0005[אומר אני לך\u0006 דבר שיש בו \u0005איסור],\u0006 שאסור לבני הכפרים לקרוא ביום חמישה עשר ולברך, וזאת לפי מה ש\u0003אמר רב שמן בר אבא אמר ר' יוחנן,\u0004 נאמר: \u0003\"לקים את ימי הפרים\u0004 האלה \u0003בזמניהם\"\u0004 (אסתר ט, לא), לומר: \u0003זמנים הרבה תיקנו להם חכמים,\u0004 וקבעו זאת כחובה, שאסור לסטות ממנה, שעל בני ארבעה עשר לקרוא ביומם ואינם יכולים לקרוא בחמישה עשר, ולהיפך — \u0003ואת אמרת לי מנהגא\u0004 \u0005[ואתה אומר,\u0006 מוכיח \u0005לי\u0006 מ\u0005מנהג]\u0006 שאין בו איסור ממש, ובכן, איפוא, כיצד קובעים בדבר שיש בו משום איסור אגודות אגודות?!","אמר לך ר' יוחנן: \u0003והתם לאו איסורא הויא\u0004 \u0005[ו\u0006האם \u0005שם\u0006 בענין איסור עשיית מלאכה בערבי פסחים \u0005אין איסור]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003בלילה,\u0004 כלומר, ליל ארבעה עשר בניסן, \u0003בית שמאי אוסרין\u0004 לעשות בו מלאכה, \u0003ובית הלל מתירין.\u0004 משמע שלשיטת בית שמאי זהו איסור גמור ובכל זאת יש העושים מלאכה ויש שאינם עושים, והרי יש בכך משום \"לא תתגודדו\"!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: שם אין ניכר שעושים אגודות שונות, כי \u0003התם\u0004 \u0005[שם],\u0006 \u0003הרואה\u0004 שאדם איננו עושה מלאכה \u0003אומר:\u0004 שזה שאינו עושה מלאכה בשעה זו, הרי זה משום שבדיוק \u0003מלאכה הוא דלית ליה\u0004 \u0005[שאין לו],\u0006 ולכן ביטול המלאכה אינו נראה כעשיית אגודות אגודות. הקשה לו ר' יוחנן: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003בית שמאי מתירין הצרות לאחים ובית הלל אוסרים,\u0004 שיש כאן ענין של איסור גמור, ובכל זאת רואים שנהגו בשני מנהגים שונים, מנהג בית שמאי ומנהג בית הלל ומדוע לא חששו ל\"לא תתגודדו\"?"]]};
